// 结构：KZ[现代名]={o:[原书药名], src:[来源], d:详注}
// ============================================================

const KZ = {
  "䲡鱼":{o:[],src:["本草纲目"],d:"新五。消渴饮水︰用泥鳅鱼（十头阴干，去头尾，烧灰）、干荷叶等分。为末。"},
  "不灰木":{o:[],src:["本草纲目"],d:"肺热咳嗽，卧时盛者︰不灰木一两半，太阴玄精石二两，甘草（炙）半两，贝母一两半，天南星（白矾水煮过）半两。为末。每服半钱，姜汤下。"},
  "丝瓜":{o:["丝瓜"],src:["本草备要", "本草纲目"],d:"泻热凉血，宣通经络 \n甘平（苏颂曰冷）。凉血解毒，除风化痰，通经络，行血脉（老者筋络贯穿，象人经络， \n故可借其气以引之），消浮肿，稀痘疮（出不快者，烧存性，入朱砂，蜜水调服）。治肠风崩 \n漏，疝痔痈疽，滑肠下乳。"},
  "丹砂":{o:["丹砂"],src:["本草备要", "本草纲目"],d:"重，镇心，定惊，泻热 \n体阳性阴（内含阴汞），味甘而凉，色赤属火（性反惊者，离中虚有阴也。味不苦而甘 \n者，火中有土也）。泻心经邪热（心经血分主药），镇心清肝，明目发汗（汗为心液），定惊 \n祛风，辟邪（胡玉少卿多恶梦，遇推官胡用之，胡曰∶昔常患此，有道士教戴灵砂而验。逐 \n解髻中绛囊授之，即夕无梦）解毒（胎毒、痘毒宜之），止渴安胎（《博救方》∶水煮一两， \n研，酒服，能下死胎。李时珍曰∶同远志、龙"},
  "乌头":{o:[],src:["本草纲目"],d:"少阴发热，少阴病始得，反发热脉沉者，麻黄附子细辛汤发其汗︰麻黄（去节）二两，附子（炮去皮）一枚，细辛二两，水一斗，先煮麻黄去沫，乃纳二味，同煮三升，分三服。（同上）人面赤色，或腹痛，或干呕，或咽痛，或利止脉不出者︰通脉四逆汤︰用大附子一个（去皮生破八片），甘草（炙）二两，干姜三两，水三升，煮一升二合，分温再服，其脉即出者愈。面赤加葱九茎；腹痛，加芍药二两；呕，加生姜二两；咽痛，加桔梗一两；利止脉不"},
  "乌烂死蚕":{o:[],src:["本草纲目"],d:"新一。消渴烦乱︰蚕蛹二两，以无灰服。（《圣惠方》）茧卤汁藏器曰︰此是茧中蛹汁，非碱卤也。"},
  "乌臼木":{o:["乌臼木"],src:["本草备要"],d:"泻热毒 \n苦凉、性沉而降。利水通肠，功胜大戟。疗疔肿，解砒毒（极能泻下。凡患肿毒，中砒 \n毒者，不拘根、皮、枝、叶，捣汁多饮，得大利即愈。虚人忌用）。 \n子，可作烛。"},
  "乌蛇":{o:[],src:["本草纲目"],d:"旧二，新五。大风︰《朝野佥载》云︰商州有人患大风。家人恶之，山中为起茅屋。 ；新二。大风龙胆膏︰治大风疾神效。用冬瓜一个，截去五寸长，去瓤，掘地坑深三尺，令净，安瓜于内。 ；新一。小儿紧唇，脾热唇疮︰并用乌蛇皮烧灰，酥和敷之。（《圣惠》）卵。"},
  "乌贼鱼":{o:[],src:["本草纲目"],d:"旧三。新二十一。女子血枯︰见上。"},
  "乌韭":{o:[],src:["本草纲目"],d:"腰脚风冷︰石花，浸酒饮之。（《圣惠方》）。妇人血崩︰石花、细茶（焙为末）、旧漆碟（烧存性）各一匙。"},
  "乌骨鸡":{o:["乌骨鸡"],src:["本草备要"],d:"补虚劳 \n甘平。鸡属木，而骨黑者属水，得水木之精气，故能益肝肾，退热补虚。治虚劳消渴， \n下痢噤口（煮汁益胃），带下崩中，肝、肾血分之病。鬼击卒死者，用其血涂心下效（《睽车 \n志》∶夏侯弘捉得一小鬼，问∶所持何物？曰∶杀人以此矛戟，中心腹者，无不辄死。弘曰 \n∶治此有方否？鬼曰∶以乌鸡敷之即瘥）。骨肉俱黑者良，舌黑者骨肉俱黑。男用雌，女用 \n雄（女科有乌鸡丸，治百病）。"},
  "云实":{o:[],src:["本草纲目"],d:"下不止︰云实、女萎各一两，桂半两，川乌头二两，为末，蜜丸梧子大。每服五丸，水下，日三服。（《肘后方》）花。"},
  "云母":{o:["云母"],src:["本草备要", "本草纲目"],d:"补中 \n甘平属金，色白入肺。下气补中，坚肌续绝。治劳伤疟痢，疮肿痈疽（同黄丹熬膏贴之 \n。《千金翼》∶用敷金疮。青城山人康道丰，有云母粉方，能治百病）。有五色，以色白光 \n莹者为上。古人亦有炼服者（云母入火，经时不焦，入土不腐，故云服之长生）。使泽泻。 \n恶羊肉。"},
  "五色石脂":{o:[],src:["本草纲目"],d:"小儿水痢形羸，不胜汤药。白石脂半两研粉，和白粥空肚食之。（《子母秘录》）小儿滑泄︰白龙丸︰白石脂、白龙骨等分。 ；小儿疳泻︰赤石脂末，米饮调服半钱，立瘥。加京芎等分，更妙。（《斗门方》）大肠寒滑，小便精出︰赤石脂、干姜各一两，胡椒半两。"},
  "五谷虫":{o:["五谷虫"],src:["本草备要"],d:"\\x即粪蛆\\x \n泻热，疗疳 \n寒。治热病谵（音占，妄语）妄，毒痢作吐，小儿疳积疳疮。漂净晒干，或炒，或 ，为 \n末用。"},
  "井泉水":{o:["井泉水"],src:["本草备要"],d:"补 \n将旦首汲，曰井华水；出瓮未放，曰无根水，无时初出，曰新汲水。解热闷烦渴（凡热 \n病不可解者，新汲水浸青色衣服互熨之炒。心闷汗出，新汲水蜜和饮炒），煎补阴之药宜之 \n（井以有地脉山泉者为上；从江湖渗来者次之；其城市近沟渠污秽者，咸而有碱。煮粥煎茶， \n味各有异，以之入药，其可无择乎？）。"},
  "井泉石":{o:[],src:["本草纲目"],d:"膀胱热闭，小便不快︰井泉石、海金沙、车前子、滑石各一两。为末。每服二钱，蜜汤下。"},
  "人中白":{o:["人中白"],src:["本草备要"],d:"泻火 \n咸平。降火散瘀，治肺瘀鼻衄（刮人中白，新瓦火上逼干，调服即止），劳热消渴，痘 \n疮倒陷，牙疳口疮。即溺 ， 研用（以蒙馆童子便桶、山中老僧溺器刮下者，尤佳）。"},
  "人中黄":{o:["人中黄"],src:["本草备要"],d:"泻热 \n甘寒入胃。清痰火，消食积，大解五脏实热。治天行热狂，痘疮血热，黑陷不起。纳甘 \n草末于竹筒中，紧塞其孔，冬月浸粪缸中。至春取出洗，悬风处阴干，取甘草用（亦有用皂 \n荚末者，竹须削去青皮）。一云即粪缸多年黄 ， 存性用。"},
  "人乳":{o:["人乳"],src:["本草备要"],d:"补虚，润燥 \n甘咸。润五脏，补血液，止消渴，泽皮肤，治风火证（昂按∶老人便秘，人乳最良）。 \n本血所化，目得血而能视，用点赤涩多泪（热者，黄连浸点）。然性寒滑，脏寒胃弱人不宜 \n多服（时珍曰∶人乳无定性。其人和平，饮食冲淡，其乳必平。其人躁暴，饮酒食辛，或有 \n火病，其乳必热。又有孕之乳，为忌乳，最有毒，小儿食之吐泻，成疳魃之病，内亦损胎。 \n昂按∶乳乃阴血所化，生于脾胃，摄于冲任。未受孕则下为月"},
  "人牙":{o:["人牙"],src:["本草备要"],d:"宣，发痘 \n咸温有毒。治痘疮倒 （《痘疹论》∶出不快而黑陷者， 猪血调下一钱；服凉药而血 \n涩倒陷者，麝香酒调服。时珍曰∶欲其窜入肾经，发出毒瓦斯，盖劫剂也。若伏毒在心，不省 \n人事，气虚色白、痒塌无脓，及热痱紫泡之证，只宜补虚解毒。苟误服此，则郁闷声哑，反 \n成不救）。 退火毒，研用。"},
  "人虱":{o:[],src:["本草纲目"],d:"新一。脚指鸡眼︰先挑破。取黑、白虱各一枚置于上缚之，数用自愈也。"},
  "伏龙肝":{o:["伏龙肝"],src:["本草备要"],d:"重，调中，止血，燥湿，消肿 \n辛温。调中止血、去湿消肿。治咳逆反胃，吐衄崩带，尿血遗精，肠风痈肿（醋调涂）， \n脐疮（研敷）丹毒（腊月猪脂或鸡子白调敷），催生下胎（《博救方》子死腹中，水调三钱服， \n其土当儿头上戴出）。斧心多年黄土，一云灶额内火气，积久结成如石，外赤中黄。研细， \n水飞用。"},
  "假苏":{o:[],src:["本草纲目"],d:"头项风强︰八月后，取荆芥穗作枕，及铺床下，立春日去之。（《千金方》）风热头痛︰荆芥穗、石膏等分，为末。每服二钱，茶调下。"},
  "兔矢":{o:["兔矢"],src:["本草备要"],d:"\\x一名明月砂\\x \n宣，明目，杀虫 \n杀虫明目，治痨瘵五疳，痘后生翳。 \n兔肝泻肝热，故能明目。 \n兔肉治消渴（《海上方》∶澄汁冷冻饮料），小儿食之稀痘疮（陶弘景曰∶孕妇食之，令儿缺 \n唇。保寿堂兔血丸，令小儿永不出痘，虽出亦稀。腊八日取生兔刺血，和荞麦面，加雄黄四 \n五分，和丸，如绿豆大。初生小儿，乳汁送下二三丸，遍身发出红点，此其验也）。"},
  "兰草":{o:[],src:["本草纲目"],d:"食牛马毒杀人者。省头草（连根叶），煎水服，即消。（《唐瑶经验方》）。"},
  "冬瓜":{o:["冬瓜"],src:["本草备要", "本草纲目"],d:"\\x又名白瓜\\x \n泻热，补脾 \n寒泻热，甘益脾。利二便，消水肿（冬瓜任吃效），止消渴（苗、叶皆治消渴），散热毒 \n痈肿（切片敷之。丹溪曰∶冬瓜性急而走，久病阴虚者忌之。昂按∶冬瓜日食常物，于诸瓜 \n中尤觉宜人，且味甘而不辛，何以见其性急而走乎？）。 \n子，补肝明目（凡药中所用瓜子，皆冬瓜子也）。"},
  "冬葵子":{o:["冬葵子"],src:["本草备要"],d:"滑肠，利窍 \n甘寒淡滑。润燥利窍，通营卫，滋气脉，行津液，利二便，消水肿（用榆皮等分煎服）， \n通关格，下乳滑胎。 \n秋葵复种，经冬至春作子者，名冬葵子。根、叶同功。春葵子亦滑，不堪入药。 \n蜀葵花，赤者治赤带，白者治白带，赤者治血燥，白者治气燥。亦治血淋、关格，皆取 \n其寒润滑利之功也。"},
  "冰":{o:["冰"],src:["本草备要"],d:"泻热 \n甘寒。太阴之精，水极似土。伤寒阳毒热甚昏迷者，以一块置膻中（两乳中间）良。解 \n烧酒毒（陈藏器曰∶盛夏食冰，与气候相反，冷热相激，却致诸疾。宋徽宗食冰太过，病脾 \n疾，国医不效。杨介进大理中丸，上曰∶服之屡矣。介曰∶病因食冰，臣请以冰煎此药，治 \n受病之源也，果愈）。"},
  "决明":{o:[],src:["本草纲目"],d:"积年失明︰决明子二升为末，每食后粥饮服方寸匕。（《外台秘要》）青盲雀目︰决明一升，地肤子五两，为末，米饮丸梧子大，每米饮下二三十丸。（《普济方》）补肝明目︰决明子一升，蔓荆子二升，以酒五升煮，曝干为末。"},
  "凝水石":{o:[],src:["本草纲目"],d:"男女转脬，不得小便︰寒水石二两，滑石一两，葵子一合。为末。水一斗，煮五升，时服一升，即利。"},
  "凤仙":{o:[],src:["本草纲目"],d:"产难催生︰凤仙子二钱，研末。水服，勿近牙。外以蓖麻子，随年数捣涂足心。 ；风湿卧床不起︰用金凤花、柏子仁、朴硝、木瓜煎汤洗浴，每日二、三次。内服独活寄生汤。（吴《扶寿精方》）根、叶。 ；咽喉物哽︰金凤花根嚼烂噙咽，骨自下，鸡骨尤效。即以温水漱口，免损齿也。亦治误吞铜铁。"},
  "刀豆":{o:["刀豆"],src:["本草备要"],d:"宣，下气 \n甘平。温中止呃（ 存性服），胜于柿蒂。"},
  "列当":{o:[],src:["本草纲目"],d:"阳事不兴︰栗当（好者）二斤（即列当）。捣筛毕，以好酒一斗浸之经宿，随性日饮之。（昝殷《食医心镜》）。"},
  "刘寄奴草":{o:["刘寄奴草"],src:["本草备要", "本草纲目"],d:"泻，破血，止血 \n苦温。破血通经，除症下胀，止金疮血。多服令人吐利。 \n一茎直上，叶尖长、糙涩，花白芯黄，如小菊花，有白絮如苦 絮，子细长亦似苦 子 \n。茎、叶、花、子皆可用（刘裕，小字寄奴。微时，曾射一蛇，明日，见童子林中捣药，问 \n之，答曰∶吾王为刘寄奴所伤，合药敷之。裕曰∶王何不杀之？童曰∶寄奴，王者，不可杀 \n也。叱之不见，乃收药回。每遇金疮，敷之立愈）。"},
  "剪草":{o:[],src:["本草纲目"],d:"风虫牙痛︰剪草、细辛、本等分，煎水热漱，少顷自止。（《中藏经》）风疮瘙痒︰滑肌散︰治风邪客于肌中，浑身瘙痒，致生疮疥，及脾肺风毒攻冲，生疮干湿，日久不瘥︰用剪草七两（不见火），轻粉一钱。为末。"},
  "卤碱":{o:[],src:["本草纲目"],d:"风热赤眼，虚肿涩痛︰卤碱一升，青梅二十七个，古钱二十一文。新瓶盛，密封，汤中煮一炊时。三日后取点，日三、五度。"},
  "卫矛":{o:["卫矛"],src:["本草备要"],d:"\\x一名鬼箭羽\\x \n泻，破血 \n苦寒（时珍曰∶酸涩）。破陈血，通经落胎，杀虫祛祟。干有三羽，叶似野茶。酥炙用。"},
  "卷柏":{o:["卷柏"],src:["本草备要", "本草纲目"],d:"生用破血，炙用止血 \n生用辛平，破血通经，治症瘕淋结。炙用辛温，止血，治肠风脱肛。 \n生石上，拳挛如鸡足，俗呼万年松。凡使盐水煮半日，井水煮半日，焙用。"},
  "原蚕":{o:[],src:["本草纲目"],d:"旧二，新八。丈夫阴痿︰未连蚕蛾二升、去头、翅、足，炒为末，蜜丸梧子大。每夜服一丸，可御十室。 ；旧四，新六。半身不遂︰蚕砂二硕，以二袋盛之，蒸熟，更互熨患处。仍以羊肚，粳米煮粥，日食一枚，十日即止。"},
  "原蚕砂":{o:["原蚕砂"],src:["本草备要"],d:"燥湿，去风 \n蚕食而不饮，属火性燥，燥能去风胜湿（经曰∶燥胜风，燥属金，风属木也）其沙辛甘 \n而温。炒黄浸酒，治风湿为病，支节不随，皮肤顽痹，腰脚冷痛，冷血瘀血（史国公药酒中 \n用之）。炒热，熨患处亦良（寇宗 曰∶醇酒三升，拌蚕沙五升，蒸热铺暖室席上，令患冷 \n风气痹人以患处就卧，浓复取汗。不愈，间日再作，须防昏闷）。麻油调敷，治烂弦风眼（目 \n上下胞属脾。脾有风湿，则虫生弦烂。又新瓦炙，为末，少"},
  "及己":{o:[],src:["本草纲目"],d:"书》）。"},
  "发":{o:["发"],src:["本草备要"],d:"\\x一名血余\\x \n补，和血 \n发者血之余。味苦微寒，入足少阴、厥阴（肾、肝）。补阴消瘀，通关格 \n，利二便。治诸血疾（能去心窍之血，故亦治惊痫），血痢血淋，舌血（ 末，茅根汤服） \n鼻血（烧灰吹鼻），转胞不通（烧灰，服），小儿惊热（合鸡子黄，煎为汁服，鸡子能去风痰）。 \n合诸药煎膏，凉血去瘀长肉（发属心，禀火气而上生；眉属肝，禀木气而侧生；须属肾，禀 \n水气而下生。或曰发属肝，禀木气而直生；眉属"},
  "古文钱":{o:[],src:["本草纲目"],d:"时气欲死︰大钱百文，水一斗煮八升，入麝香末三分，稍饮至尽，或吐或下愈。（《肘后方》）时气温病，头痛壮热脉大，始得一日者。比轮钱一百五十七文，水一斗，煮取七升，服汁。"},
  "古镜":{o:[],src:["本草纲目"],d:"小儿夜啼︰明鉴挂床脚上。（《圣惠方》）锡铜镜鼻（《本经》下品）。 ；小儿客忤，面青惊痛。铜照子鼻烧赤，少酒淬过，与儿饮。（《圣惠方》）镜锈（即镜上绿也。"},
  "吊":{o:[],src:["本草纲目"],d:"新二。阳事痿弱︰紫梢花、生龙骨各二钱，麝香少许，为末。蜜丸梧子大。"},
  "土菌":{o:[],src:["本草纲目"],d:"新一。疔肿︰黑牯牛撒粪石上，待生菌子，焙干，草等分为末。以竹筒去两头，紧缚，合住疔上。"},
  "土蜂":{o:[],src:["本草纲目"],d:"新一。面黑令白︰土蜂子未成头翅者，炒食，并以酒浸敷面。（《圣惠方》）房。 ；新一。疔肿疮毒已笃者︰二服即愈，轻者一服立效。用土蜂房一个，蛇蜕一条，黄存性，为末。"},
  "土马鬃":{o:[],src:["本草纲目"],d:"九窍出血︰墙头苔，塞之。（《海上方》）。鼻衄不止︰寸金散︰用墙上土马鬃二钱半，石州黄药子五钱。"},
  "地浆":{o:["地浆"],src:["本草备要"],d:"泻热，解毒 \n甘寒。治泻痢冷、热、赤、白，腹内热毒绞痛。解一切鱼肉、菜、果、药物、诸菌毒（ \n菌，音郡，生朽木湿地上。亦名蕈，音寻，上声），及虫蜞入腹（如误食马蟥蜞入腹，生子 \n为患，用地浆下之），中 （暑热）卒死者（取道上热土围脐，令人尿脐中，以热土大蒜等 \n分，捣水去渣，灌之即活）。以新水沃黄土搅浊，再澄清用（凡跌打损伤，取净土蒸热，以 \n布裹更互熨之，勿大热，恐破肉。虽瘀血凝积，气绝欲死者亦"},
  "地肤":{o:[],src:["本草纲目"],d:"风热赤目︰地肤子（焙）一升，生地黄半斤，取汁和作饼，晒干研末。每服三钱，空心酒服。目痛眯目︰凡目痛及眯目中伤有热瞑者。 ；物伤睛陷，肉突出︰地肤（洗去土）二两。捣绞汁，每点少许。冬月以干者煮浓汁。"},
  "地胆":{o:[],src:["本草纲目"],d:"新三。小肠气痛︰地胆（去翅、足、头，微炒）、朱砂各半两，滑石一两，为末。每苦杖酒食前调服二钱，即愈。"},
  "地衣草":{o:[],src:["本草纲目"],d:"身面丹肿，如蛇状者︰以雨滴阶上苔痕水花，涂蛇头上，即愈。（危氏《得效方》）。雀目夜昏︰七月七日、九月九日取地衣草，阴干为末。"},
  "地锦":{o:[],src:["本草纲目"],d:"脏毒赤白︰地锦草洗，曝干为末。米饮服一钱，立止。（《经验方》）。"},
  "地黄":{o:[],src:["本草纲目"],d:"三捣三压，取汁令尽，以瓦器盛之，密盖勿泄气，汤上煮减半，绞去滓，再煎如饧，丸弹子大。每温酒服一丸，日二服。（《千金》）斤半，生姜半斤（绞取汁），蜜二升，酒四升。 ；（晒）、槐点少许，日三、四次。（《圣惠方》）。"},
  "堇":{o:[],src:["本草纲目"],d:"旧二，新一。结核气：堇菜，晒干为末，油煎成膏。摩之，日三、五度，便瘥。"},
  "墨":{o:["墨"],src:["本草备要"],d:"辛温。止血生肌。飞丝、尘芒入目，浓磨点之；点鼻止衄；猪胆汁磨，涂诸痈肿（醋磨 \n亦可）。酒磨服，治胞不下。"},
  "壁钱":{o:[],src:["本草纲目"],d:"新一。喉痹乳蛾︰已死者复活。用墙上壁钱七个，内要活蛛二枚，捻作一处，以白矾七分一块，化开，以壁钱惹矾，烧存性，出火窠幕。 ；虫牙疼痛︰《普济方》︰以壁上白丸之，纳入牙中甚效。又以乳香入耳，左痛塞右，右痛塞左，手。"},
  "壶卢":{o:[],src:["本草纲目"],d:"新一。腹胀黄肿︰用亚腰壶卢连子烧存性，每服一个，食前温酒下。不饮酒者，白汤下。 ；新一。预解胎毒︰七、八月，或三伏日，或中秋日，剪壶卢须如环子脚者，阴干，于除夜煎汤浴小儿，则可免出痘。（唐瑶《经验方》）子。"},
  "夜明砂":{o:["夜明砂"],src:["本草备要"],d:"\\x一名天鼠矢\\x \n泻，散血，明目 \n辛寒。肝经血分药。活血消积，治目盲障翳（加石决明猪肝煎，名决明夜灵散，治鸡盲 \n眼）疟 （音奇。小儿鬼）惊疳（蝙蝠及矢，并治惊、疳、疟、痫、厥阴之病），血气腹痛 \n（《经疏》曰∶辛能散内外滞气，寒能除血热气壅，明目之外，余皆可略。吴鹤皋曰∶古人 \n每用虻虫、水蛭治血积，以其善吮血耳。若天鼠矢，乃食蚊而化者也，当亦可以攻血积，《本 \n草》称其下死胎，则其能攻血"},
  "大戟":{o:["大戟"],src:["本草备要", "本草纲目"],d:"大泻，通脏腑水湿 \n苦寒有毒。能泻脏腑水湿，行血发汗，利大小便。 \n治十二种水，腹满急痛，积聚症瘕，颈腋痈肿，风毒脚肿，通经堕胎。误服损真气（时 \n珍曰∶痰涎为物，随气升降，无处不到。入心则迷，成癫痫；入肺则塞窍，为咳喘背冷；入 \n肝则胁痛干呕，寒热往来；入经络则麻痹疼痛；入筋骨则牵引隐痛；入皮肉则瘰 痈肿。陈 \n无择并以控涎丹主之，殊有奇效，此乃治痰之本。痰之本，水也，湿也，得气与火。则结为 \n"},
  "大腹皮":{o:["大腹皮"],src:["本草备要"],d:"泻，下气，通，行水 \n辛泄肺、温和脾。下气行水，通大、小肠。 \n治水肿香港脚，痞胀痰膈，瘴疟霍乱。气虚者忌用。 \n子，似槟榔，腹大形扁（故与槟榔同功）。取皮，酒洗，黑豆汤再洗。煨用（鸠鸟多栖 \n其树，故宜洗净）。"},
  "大蒜":{o:["大蒜"],src:["本草备要"],d:"\\x张骞使西域，始得种入中国，故一名葫\\x \n宣，通窍，辟恶 \n辛温。开胃健脾，通五脏，达诸窍（凡极臭极香之物，皆能通窍），去寒湿，解暑气， \n辟瘟疫，消痈肿（捣烂，麻油调敷），破症积，化肉食，杀蛇虫蛊毒。治中暑不醒（捣，和 \n地浆温服），鼻衄不止（捣，贴足心，能引热下行），关格不通（捣，纳肛中，能通幽门）。 \n敷脐能达下焦，消水，利大、小便。切片，灼艾，灸（音九）一切痈疽，恶疮肿核。独头者 \n尤"},
  "大蓟、小蓟":{o:[],src:["本草纲目"],d:"心热吐血口干︰用刺蓟叶及根，捣绞取汁，每顿服二小盏。（《圣惠方》）舌硬出血不止︰刺蓟捣汁，和酒服。干者为末，冷水服。"},
  "大青":{o:["大青"],src:["本草备要", "本草纲目"],d:"泻心胃热毒 \n微苦咸，大寒。解心胃热毒。 \n治伤寒，时疾热狂，阳毒发斑（热甚伤血，里实表虚，则发斑。轻如疹子，重如锦纹。 \n紫黑者，热极而胃烂也，多死。《活人书》∶治赤斑烦痛，有犀角大青汤），黄胆热痢，丹 \n毒喉痹。 \n处处有之。高二三尺，茎圆叶长，叶对节生，八月开小红花成簇，实大如椒，色赤。用 \n茎叶。"},
  "大风子":{o:["大风子"],src:["本草备要"],d:"燥痰，外用治疮 \n辛热有毒。取油治疮癣疥癞，有杀虫劫毒之功（丹溪曰∶粗工治大风病，佐以大风油， \n殊不知此物性热，有燥痰之功而伤血，至有病将愈而先失明者）。出南番。子中有仁，白色 \n，久则油黄，不可用。入丸药，压去油。"},
  "大麦芽":{o:["大麦芽"],src:["本草备要"],d:"开胃健脾，行气消积 \n咸温。能助胃气上行，而资健运，补脾宽肠，和中下气，消食除胀，散结祛痰（咸能软 \n坚），化一切米、面、果、食积，通乳下胎（《外台方》∶麦芽一升、蜜一升服，下胎神验。 \n薛立斋治一妇人，丧子乳胀，几欲成痈，单用麦芽一二两炒，煎服立消，其破血散气如此。 \n《良方》云∶神曲亦下胎，皆不可轻用）。久服消肾气（王好古曰∶麦芽，神曲，胃虚人宜 \n服之，以伐戊己，腐熟水谷。李时珍曰∶无积而服"},
  "大麻仁":{o:["大麻仁"],src:["本草备要"],d:"\\x大麻，即作布之麻，俗作火麻\\x \n润燥滑肠 \n甘平滑利。脾、胃、大肠之药，缓脾润燥。治阳明病、胃热汗多而便难（三者皆燥也， \n汗出愈多，则津枯而大便愈燥。张仲景治脾约有麻仁丸。成无己曰∶脾欲缓，急食甘以缓之 \n，麻仁之甘，以缓脾润燥。张子和曰∶诸燥皆三阳病），破积血，利小便，通乳催生。又木 \n谷也，亦能治风。极难去壳，帛裹置沸汤，待冷，悬井中一夜，晒干，就新瓦上 去壳，捣 \n用。畏茯芩、白薇、"},
  "大黄蜂":{o:[],src:["本草纲目"],d:"新一。雀斑面︰七月七日取露蜂子，于漆碗中水酒浸过，滤汁，调胡粉敷之。（《普济方》）。"},
  "天仙藤":{o:["天仙藤"],src:["本草备要", "本草纲目"],d:"通，活血，消肿 \n苦温。疏气活血。治风劳腹痛，妊娠水肿（有天仙藤散，专治水肿）。 \n叶似葛，圆而小，有白毛，根有须，四时不凋（一云即青木香藤）。"},
  "天名精":{o:[],src:["本草纲目"],d:"男女吐血︰皱面草（即地菘），晒干为末。每服一、二钱，以茅花泡汤调服，日二次。（《卫生易简》）根、叶捣汁，鹅翎扫入，去痰最妙。 ；大肠虫出不断，断之复生，行坐不得︰鹤虱末，水调半两服，自愈。（《怪疾奇方》）。"},
  "天牛":{o:[],src:["本草纲目"],d:"新三。疔肿恶毒︰透骨膏︰用八角儿（杨柳上者，阴干去壳）四个（如冬月无此，用其窠代之），蟾酥半钱，巴豆仁一个，粉霜、雄黄、麝香少许。先以八角儿研如泥，入熔化黄蜡少许，同众药末和作膏子，密收。"},
  "天竹黄":{o:["天竹黄"],src:["本草备要"],d:"泻热，豁痰，凉心 \n甘而微寒。凉心经，去风热，利窍豁痰，镇肝明目。功同竹沥，而性和缓，无寒滑之患 \n。治大人中风不语，小儿客忤惊痫为尤宜。出南海。大竹之津气结成（即竹内黄粉），片片 \n如竹节者真。"},
  "天蓼":{o:[],src:["本草纲目"],d:"生肌肉水荭花根，煎汤淋洗，仍以其叶晒干研末，撒疮上，每日一次。（《谈野翁试验方》）。"},
  "天门冬":{o:[],src:["本草纲目"],d:"辟谷不饥︰天门冬二斤，熟地黄一斤，为末，炼蜜丸弹子大。每温酒化三丸，日三服。居山远行，辟谷良。"},
  "天雄":{o:[],src:["本草纲目"],d:"三建汤，治元阳素虚，寒邪外攻，手足厥冷，大小便滑数，小便白浑，六脉沉微，除固冷，扶元气，及伤寒阴毒。用乌头、附子、天雄（并炮裂去皮脐）等分。㕮咀。"},
  "太阴玄精石":{o:["太阴玄精石"],src:["本草备要"],d:"泻热，补阴 \n太阴之精，咸寒而降。治上盛下虚，救阴助阳，有扶危拯逆之功（正阳丹，用治伤寒壮 \n热。来复丹，用治伏暑热泻）。出解池、通泰积盐处，咸卤所结，青白莹彻，片皆六棱者良 \n。今世用者，多是绛石。"},
  "女萎":{o:[],src:["本草纲目"],d:"下不止︰女萎、云实各一两，川乌头二两，桂心五钱。为末，蜜丸梧子大。每服五丸，水下，一日三服。"},
  "女青":{o:[],src:["本草纲目"],d:"人卒暴死︰捣女青屑一钱，安咽中，以水或酒送下，立活也。（《南岳魏夫人内传》）吐利卒死，及大人小儿，卒腹皮青黑赤，不能喘息︰即急用女青末纳口中，酒送下。（《子母秘录》）辟禳瘟疫︰正月上寅日，捣女青末，三角绛囊盛，系帐中，大吉。"},
  "姜石":{o:[],src:["本草纲目"],d:"疔疮肿痛︰白姜石末，和鸡子清敷之，干即易，疗自出，神效。（崔氏方）乳痈肿大如碗肿痛︰方同上。（《外台秘要》）产后胀冲气噎︰KT石、代赭石等分，为末，醋糊丸梧子大。"},
  "孔公孽":{o:[],src:["本草纲目"],d:"风气脚弱︰孔公二斤，石斛五两，酒二斗，浸服。（《肘后方》）。"},
  "孩儿茶":{o:["孩儿茶"],src:["本草备要"],d:"泻热，生津，涩，收湿 \n苦涩、清上膈热，化痰生津，止血收湿，定痛生肌。涂金疮口疮（硼砂等分），阴疳痔 \n肿。出南番，云是细茶末。纳竹筒，埋土中，日久取出，捣汁熬成。块小、润泽者上，大而 \n枯者次之。"},
  "守宫":{o:[],src:["本草纲目"],d:"新十四。小儿脐风︰用壁虎后半截焙为末，男用女乳，女用男乳，调匀，入稀鸡矢少许，掺舌根及牙关。仍以手蘸摩儿，取汗出，甚妙。 ；新一。胎赤烂眼昏暗︰用蝎虎数枚，以罐盛黄土按实，入蝎虎在内，勿令损伤。以纸封口，穿数孔出气。"},
  "密陀僧":{o:["密陀僧"],src:["本草备要", "本草纲目"],d:"重，镇惊，劫痰，消积 \n辛咸小毒。感银铅之气而结。坠痰镇惊，止血散肿，消积杀虫，疗肿毒，愈冻疮（用桐 \n油调敷），解狐臭（油调搽腋。以馒头蒸热劈开，掺末夹腋下亦佳），染髭须。出银坑难得， \n今用者乃倾银 底。入药煮一伏时。"},
  "小青":{o:[],src:["本草纲目"],d:"蛇虺螫伤︰《卫生易简方》︰用小青一握（细研），入香白芷半两。酒调服。手患处，候黄水出为效。"},
  "小麦":{o:["小麦"],src:["本草备要"],d:"补 \n味甘微寒。养心除烦，利溲止血（李时珍曰∶《素问》麦属火，心之谷也；郑玄谓属木 \n；许慎谓属金；《别录》云养肝，与郑说合；孙思邈云养心，与《素问》合，当以《素问》 \n为准。按∶麦，秋种夏熟，备受四时之气。南方地暖下湿，不如北产者良。张仲景治妇人脏 \n躁证，悲伤欲绝，状若神灵，用甘麦大枣汤。大枣十枚，小麦一升，甘草一两，每服一两， \n亦补脾气。《圣惠方》∶小麦饭治烦热。少睡，多渴）。 \n面粉甘温"},
  "屋游":{o:[],src:["本草纲目"],d:"犬咬︰旧屋瓦上刮下青苔屑，按之即止。（《经验方》）。"},
  "山柰":{o:["山柰"],src:["本草备要", "本草纲目"],d:"宣，温中，辟恶 \n辛温。暖中辟恶。 \n治心腹冷痛，寒湿霍乱，风虫牙痛。 \n生广中，据叶皆如生姜，入合诸香用。"},
  "山茶花":{o:["山茶花"],src:["本草备要"],d:"泻，凉血 \n甘微辛寒。色赤，入血分。治吐衄肠风。麻油调末，涂汤火伤。用红者为末，入童便、 \n姜汁、酒调服，可代郁金。"},
  "山豆根":{o:["山豆根"],src:["本草备要", "本草纲目"],d:"泻热，解毒 \n苦寒。泻心火以保金气，去肺，大肠之风热（心火降，则不灼肺而金清。肺与大肠相表 \n里，肺金清，则大肠亦清），消肿止痛。 \n治喉痈喉风，龈肿齿痛（含之咽汁），喘满热咳，腹痛下痢，五痔诸疮。解诸药毒，敷 \n秃疮、蛇狗蜘蛛伤，疗人、马急黄（血热极所致）。 \n苗蔓如豆，经冬不凋。"},
  "常山":{o:["常山"],src:["本草备要"],d:"宣，吐痰，截疟，通，行水 \n辛苦而寒，有毒。能引吐行水，祛老痰积饮（痰有六∶风痰、寒痰、湿痰、热痰、食痰 \n、气痰也。饮有五，流于肺为支饮，于肝为悬饮，于心为伏饮，于经络为溢饮，于肠胃为痰 \n饮也。常山力能吐之，下之），专治诸疟。然悍暴能损真气，弱者慎用（时珍曰∶常山蜀漆， \n韧痰截疟，须在发散表邪及提出阳分之后用之。疟有经疟、脏疟、风、寒、暑、湿、痰、食 \n、瘴、鬼之别，须分阴、阳、虚、实，不可"},
  "常山、蜀漆":{o:[],src:["本草纲目"],d:"截疟诸汤︰《外台秘要》︰用常山三两，浆水三升，浸一宿，煎取一升，欲发前顿服，取吐。《肘后方》︰用常山一两，秫米一百粒，水六升，煮三升，分三服。先夜、未发、临发时服尽。"},
  "常春藤":{o:[],src:["本草纲目"],d:"疔疮黑凹︰用发绳扎住，将尖叶薜荔捣汁，和蜜一盏服之。外以葱、蜜捣敷四围。（《圣惠方》）衄血不止︰龙鳞薜荔，研水饮之。"},
  "庵䕡":{o:[],src:["本草纲目"],d:"月水不通，妇人宿有风冷，留血积聚，月水不通︰庵子一升，桃仁二升（酒浸去皮尖）。研匀入瓶内，以酒二斗浸，封五日后，每饮三合，日三服。（《圣惠方》）产后血痛︰庵子一两。"},
  "庵子":{o:["庵子"],src:["本草备要"],d:"泻，行水，散血 \n苦辛微寒（《别录》微温）。入肝经血分。行水散血，散中有补。 \n治阳痿经涩，腰、膝、骨节重痛，产后血气作痛，闪锉折伤（扑打方多用之）。能制蛇 \n（见之则烂）。 \n叶似菊而薄，茎似艾而粗。薏苡为使。"},
  "律草":{o:[],src:["本草纲目"],d:"小便石淋︰葛掘出根，挽断，以杯于坎中承取汁。服一升，石当出。不出更服。"},
  "徐长卿":{o:[],src:["本草纲目"],d:"小便关格：徐长卿汤：治气壅关格不通，小便淋结，脐下妨闷。徐长卿（炙）半两，茅根三分，木通、冬葵子一两，滑石二两，槟榔一分，瞿麦穗半两。每服五钱，水煎，入朴硝一钱，温服，日二服。"},
  "御米壳":{o:["御米壳"],src:["本草备要"],d:"\\x即罂粟壳\\x \n涩肠，敛肺，固肾 \n酸涩微寒。敛肺涩肠而固肾。治久嗽泻痢，遗精脱肛，心腹筋骨诸痛（东垣曰∶收涩固 \n气，能入肾，故治骨病尤宜），嗽、痢初起者忌用（丹溪曰∶此是收后药，要先除病根）。一 \n名丽春花，红黄紫白，艳丽可爱。凡使壳，洗去蒂及筋膜，取薄皮。醋炒或蜜炒用（性紧涩 \n，不制多令人吐逆）。得醋、乌梅、陈皮良。罂中有米极细，甘寒润燥，煮粥食，治反胃（加 \n参尤佳）。"},
  "忍冬":{o:[],src:["本草纲目"],d:"忍冬酒︰治痈疽发背，不问发在何处，发眉发颐，或头或项，或背或腰，或胁或乳，或手足，皆有奇效。乡落之间，僻陋之所，贫乏之中，药材难得，但虔心服之，俟其疽破，仍以神异膏贴之，其效甚妙︰用忍冬藤（生取）一把，以叶入砂盆研烂，入生饼子酒少许，稀稠得所，涂于四围，中留一口泄气。其藤只用五两（木槌槌损，不可犯铁），大甘草节（生用）一两。"},
  "急流水":{o:["急流水"],src:["本草备要"],d:"通 \n性速而趋，下通二便，风痹药宜之（昔有病小便闭者，众不能瘥。张子和易以急流之 \n水，煎 \n前药一饮而溲。时珍曰∶天下之水，灭火濡枯则同。至于性从地变，质与物迁者，未尝同也）。"},
  "恶实":{o:[],src:["本草纲目"],d:"风水身肿欲裂︰鼠粘子二两，炒研为末。每温水服二钱，日三服。（风热浮肿，咽喉闭塞︰牛蒡子一合（半生半熟），为末。 ；时气余热不退，烦躁发渴，四肢无力，不能饮食︰用牛蒡根捣汁，服一小盏，效。（《圣惠方》）天行时疾︰生牛蒡根，捣汁五合，空腹分为二服。服讫，取桑叶一把，炙黄，以水一升，煮取五合，顿服取汗，无叶用枝。"},
  "悬钩子":{o:[],src:["本草纲目"],d:"血崩不止︰木莓根四两，酒一碗，煎七分。空心温服。（仙《乾坤生意》）治妇人崩中及下痢，日夜数十起欲死者，以此入腹即活︰悬钩根、蔷薇根、柿根、菝各一斛，锉入釜中，水淹上四、五寸，煮减三之一，去滓取汁，煎至可丸，丸梧子大。"},
  "戎盐":{o:[],src:["本草纲目"],d:"小便不通︰戎盐汤︰用戎盐（弹丸大）一枚，茯苓半斤，白术二两。水煎，服之。（仲景《金匮方》）风热牙痛︰青盐一斤，槐枝半斤。"},
  "扁青":{o:[],src:["本草纲目"],d:"顽痰不化︰石青一两，石绿半两，并水飞为末，面糊丸绿豆大。每服十丸，温水下。吐去痰一、二碗，不损人。"},
  "旋花":{o:[],src:["本草纲目"],d:"被斫断筋︰旋葍根捣汁，沥疮中，仍以滓敷之，日三易。半月即断筋便续。此方出苏景中家獠奴，用效。"},
  "无名异":{o:["无名异"],src:["本草备要", "本草纲目"],d:"重，和血，行伤 \n咸入血，甘补血。治金疮折伤，痈疽肿毒（醋磨涂），止痛生肌（人受杖时，须服三五 \n钱，不甚痛伤）。生川广。小黑石子也，一包数百枚。"},
  "旱莲草":{o:["旱莲草"],src:["本草备要"],d:"\\x一名鲤肠，又名金陵草\\x \n补肾 \n甘咸，汁黑。补肾止血，黑发乌髭（《千金》云∶当及时多收，其效甚速。《经疏》云 \n∶性凉不益脾胃，故《千金方》金陵煎丸用姜汁和剂）。 \n苗如旋复，实似莲房，断之有计，须臾而黑。熬膏良。"},
  "昨叶何草":{o:[],src:["本草纲目"],d:"小便沙淋︰瓦松（即屋上无根草），煎浓汤乘热熏洗小腹，约两时即通。（《经验良方》）。通经破血︰旧屋阴处瓦花（活者）五两（熬膏），当归须、干漆一两（烧烟尽），当门子二钱。"},
  "景天":{o:[],src:["本草纲目"],d:"惊风烦热︰慎火草煎水浴之。（《普济方》）。小儿中风︰汗出中风，一日头颈腰背热，二日即腹热，手足不屈。"},
  "曼陀罗花":{o:[],src:["本草纲目"],d:"面上生疮︰曼陀罗花，晒干研末。少许贴之。（《卫生易简方》）小儿慢惊︰曼陀罗花七朵（重一字），天麻二钱半，全蝎（炒）十枚，天南星（炮）、丹砂、乳香各二钱半，为末。"},
  "曾青":{o:[],src:["本草纲目"],d:"斑疮入目不退者︰曾青一钱，丹砂二钱。为末。蛴螬五枚，捣汁和点。"},
  "月季花":{o:[],src:["本草纲目"],d:"瘰&#30311;未破︰用月季花头二钱，沉香五钱，芫花（炒）三钱，碎锉，入大鲫鱼腹中，就以鱼肠封固，酒、水各一盏，煮熟食之，即愈。鱼须安粪水内游死者方效。此是家传方，活人多矣。"},
  "木槿":{o:["木槿"],src:["本草备要"],d:"泻热 \n苦凉。活血润燥。治肠风泻血，痢后热渴。作饮服，令人得睡。川产者治癣疮（癣疮有 \n虫，用川槿皮肥皂水浸，时时搽之，或浸汁磨雄黄尤妙）。用根、皮。"},
  "木耳":{o:[],src:["本草纲目"],d:"新六。眼流冷泪︰木耳一两（烧存性），木贼一两，为末。每服二钱，以清米泔煎服。 ；旧三，新十一。少小鼻衄，小劳辄出︰桑耳熬焦捣末，每发时，以杏仁大塞鼻中，数度即可断。（《肘后方》）。 ；旧三，新三。肠痔下血︰槐树上木耳，为末。饮服方寸匕，日三服。 ；新一。服食方《淮南万毕术》云︰八月榆，以美酒渍曝，同青粱米、紫苋实蒸熟为末。每服三指撮，酒下，令人辟谷不饥。 ；新一。反胃吐痰︰柳树蕈五、七个，煎汤服即"},
  "木莲":{o:[],src:["本草纲目"],d:"惊悸遗精︰木馒头（炒）、白牵牛等分，为末。每服二钱，用米饮调下。（《乾坤秘韫》）阴囊肿︰木莲（即木馒头），烧研，酒服二钱。"},
  "木贼":{o:["木贼"],src:["本草备要", "本草纲目"],d:"轻，发汗，退目翳 \n温微甘苦。中空轻扬，与麻黄同形、性；亦能发汗解肌，升散火郁、风湿，入足厥阴， \n少阳血分。益肝胆。 \n治目疾，退翳膜（翳乃肝邪郁遏，不能上通于目），及疝痛脱肛，肠风痔 ，赤痢崩中 \n诸血病。"},
  "木鳖子":{o:["木鳖子"],src:["本草备要", "本草纲目"],d:"泻热，外用治疮 \n苦温微甘。有小毒，利大肠。 \n治泻痢疳积，瘰 疮痔，乳痈蚌毒。消肿追毒，生肌除 （音旱，黑斑），专入外科。 \n核扁如鳖，绿色。拣去油者，能毒狗。"},
  "本":{o:["本"],src:["本草备要"],d:"宣，去风寒湿 \n辛温雄壮，为太阳经（膀胱）风药，寒郁本经、头痛连脑者必用之（凡巅顶痛，宜 本、 \n防风、酒炒升、柴）。治督脉为病，脊强而厥（督脉并太阳经贯脊）；又能下行去湿，治妇人 \n疝瘕，阴寒肿痛，腹中急痛（皆太阳寒湿），胃风泄泻（夏英公病泄，医以虚治不效。霍翁 \n曰∶此风客于胃也，饮以 本汤而愈。盖 本能除风湿耳），粉刺酒 （音查，和白芷作面 \n脂良）。 \n根紫色似芎 而轻虚，气香味麻。"},
  "朴硝":{o:[],src:["本草纲目"],d:"紫雪︰疗伤寒温疟，一切积热烦热，狂易叫走，瘴疫毒疠，猝死脚气，五尸五疰，心腹诸疾，疠刺切痛，解诸热毒，邪热发黄，蛊毒鬼魅，野道热毒，小儿惊痫百病。黄金一百两，石膏、寒水石、滑石、磁石各三斤。捣碎，水一斛，煮四斗，去滓；入犀角屑、羚羊角、青木香、沉香各五两，玄参（洗焙）、升麻各一斤，甘草（炒）八两，丁香一两，入前汁中煮取一斗五升，去滓；入炼朴硝十斤，硝石三十二两，于药汁中，微火煎之，柳木不住搅，至水"},
  "杉木":{o:["杉木"],src:["本草备要"],d:"宣，散肿胀 \n辛温。去恶气，散风毒。治香港脚肿痛，心腹胀满，洗毒疮（柳子浓纂《救死方》云∶得 \n香港脚夜半痞绝，胁块如石，昏困且死。郑洵美传杉木汤，食顷大下，块散气通。用杉木节一 \n升，橘叶一升，无叶以皮代，大腹槟榔七枚，连子槌碎，童便三升煮，分二服。若一服得快 \n利，即停后服）。有赤、白二种，赤、油斑如野鸡者，作棺尤贵。性直，烧炭最发火药。"},
  "杜衡":{o:[],src:["本草纲目"],d:"饮水停滞：大热行极，及食热饼后，饮冷水过多不消，停滞在胸不利，呼吸喘息者。杜衡三分，瓜蒂二分，人参一分。为末。"},
  "松节":{o:["松节"],src:["本草备要"],d:"燥湿，去风 \n松之骨也，坚劲不凋，故取其苦温之性，以治骨节间之风湿（丹溪曰∶能燥血中之湿）。 \n杵碎浸酒良（史国公药酒中用之）。 \n松脂 苦甘性燥。祛风去湿，化毒杀虫，生肌止痛。养生家炼之服食，今熬膏多用之（ \n龋齿有孔，松脂 塞，虫即从脂出）。 \n松毛 酿酒（煮汁代水），亦治风痹香港脚。"},
  "枫脂香":{o:["枫脂香"],src:["本草备要"],d:"\\x即白胶香\\x \n宣，调气血 \n苦平。活血解毒，止痛生肌。治血衄咯血，齿痛风疹，痈疽金疮。外科要药。色白微黄 \n，能乱乳香，功颇相近。"},
  "枳子":{o:["枳子"],src:["本草备要"],d:"\\x一名木蜜\\x \n润，解酒 \n甘平。止渴除烦，润五脏，解酒毒（葛根解酒毒，而发散不如枳 。屋外有枳 树，屋 \n内酿酒多不佳。赵以得治酒毒、房劳病热者，加葛根于补气血药中，一贴微汗，反解怠，热 \n如故。知气血虚，不禁葛根之散也，必得枳 方可，偶得干者加入即愈。《东坡集》曰∶杨 \n颖臣病消渴，日饮水数斗，饭亦倍进，小便频数，服消渴药，日甚。延张肱诊之，笑曰∶君 \n几误死，取麝香当门子，以酒濡作十许丸"},
  "枳实、枳壳":{o:["枳实、枳壳"],src:["本草备要"],d:"泻，破气，行痰。枳实小，枳壳大 \n苦酸微寒。其功皆能破气。气行则痰行喘止，痞胀消（脾无积血；心下不痞；浊气在上 \n，则生腹胀。东垣曰∶枳实治下而主血，枳壳治上而主气），痛刺息，后重除。 \n治胸痹结胸，食积五膈，痰癖症结，呕逆咳嗽，水肿胁胀（肝郁），泻痢淋闭，痔肿肠 \n风。除风去痹（辛散风），开胃健脾。所主略同，但枳实利胸膈，枳壳宽肠胃。枳实力猛（大、 \n小承气汤皆用之。丹溪曰∶枳实泻痰，能冲墙倒壁"},
  "柳蠹虫":{o:[],src:["本草纲目"],d:"新三。口疮风疳︰小儿病此，用柳木蛀虫矢，烧存性为末，入麝香少许，搽之。杂木亦可。"},
  "柿干":{o:["柿干"],src:["本草备要"],d:"润肺，涩肠，宁嗽 \n甘平性涩（生柿性寒）。脾、肺血分之药。健脾涩汤，润肺宁嗽，而消宿血。治肺痿热 \n咳，咯血反胃（有人三世病反胃，得一方，柿干同干饭日日食，不饮水，遂愈），肠风痔漏 \n（肺与大肠相表里，脏清则腑热亦除。《泊宅编》∶柿干烧灰饮，服二钱，治下血）。忌蟹。 \n柿霜乃其精液。生津化痰，清上焦心、肺之热为尤佳。治咽喉口舌疮痈。 \n柿蒂止呃逆（古方单用，取其苦温降气。《济生》加丁香、生姜，取其"},
  "栗":{o:["栗"],src:["本草备要"],d:"补肾 \n咸温。浓肠胃，补肾气（寇宗 曰∶小儿不可多食。生则难化，熟则滞气。能解羊膻）。"},
  "栝蒌":{o:[],src:["本草纲目"],d:"痰咳不止︰栝蒌仁一两，文蛤七分，为末，以姜汁澄浓脚，丸弹子大。噙之。（《摘玄方》）干咳无痰︰熟栝蒌捣烂绞汁，入蜜等分，加白矾一钱，熬膏。 ；消渴饮水︰《千金方》作粉法︰取大栝蒌根去皮寸切，水浸五日，逐日易水，取出捣研，滤过澄粉晒干。每服方寸匕，水化下，日三服。亦可入粥及乳酪中食之。"},
  "根叶":{o:[],src:["本草纲目"],d:"仙灵脾酒︰益丈夫兴阳，理腰膝冷。用淫羊藿一斤，酒一斗，浸三日，逐时饮之。（《食医心镜》）偏风不遂、皮肤不仁，宜服。"},
  "桂心":{o:["桂心"],src:["本草备要"],d:"燥，补阳，活血 \n苦入心，辛走血。能引血、化汗、化脓，内托痈、疽、痘疮（同丁香，治痘疮灰塌）， \n益精明目，消瘀生肌，补劳伤，暖腰膝，续筋骨。 \n治风痹症瘕，噎膈腹满，腹内冷痛，九种心痛（一虫、二疰、三风、四悸、五食、六饮 \n、七冷、八热、九去来痛，皆邪乘于手少阴之络，邪正相激，故令心痛）。"},
  "桑花":{o:[],src:["本草纲目"],d:"大便后血︰桑树上白藓花，水煎服，或末服。亦止吐血。（《圣惠方》）。"},
  "桑蠹虫":{o:[],src:["本草纲目"],d:"新二。崩中漏下赤白︰用桑蝎烧灰，温酒服方寸匕，日二。（《千金》）堕胎下血不止︰桑木中蝎虫，烧末。 ；新四。肠风下血︰枯桑树下虫矢，烧存性，酒服一钱。（《圣惠》）产后下痢，日五十行︰用桑木里蠹虫粪，炒黄，急以水沃之，稀稠得所，服之，以瘥为度。"},
  "梨":{o:["梨"],src:["本草备要"],d:"润肠，泻火，清热 \n甘微酸寒。润肺凉心，消痰降火，止渴解酒，利大小肠。治伤寒发热，热嗽痰喘，中风 \n失音（捣汁频服。《圣惠方》梨汁煮粥，治小儿心脏风热昏躁）。切片，贴汤火伤。多食冷利 \n。脾虚泄泻及乳妇、血虚人忌之（生者清六腑之热，熟者滋五脏之阴。实火宜生，虚火宜熟 \n。《泊宅编》有仕宦病消渴，医谓不过三十日死。亟弃官归，途遇一医，令致北梨二担，食 \n尽则瘥。宦如其言，食及五六十枚而病愈。杨吉老介"},
  "棕榈":{o:["棕榈"],src:["本草备要"],d:"涩，止血 \n苦能泄热，涩可收脱，烧黑能止血（红见黑则止，不可烧过。棕榈、侧柏、卷柏烧存性 \n，饭丸，止远年下血。亦可煎服）。治吐衄下痢，崩带肠风，失血过多者，初起未可遽用。 \n年久败棕尤良。（与发灰同用更良）。"},
  "椿樗白皮":{o:["椿樗白皮"],src:["本草备要"],d:"涩肠，燥湿 \n苦燥湿，寒胜热，涩收敛。入血分而涩血。去肺、胃之陈痰。治湿热为病，泄泻久痢， \n崩带肠风，梦遗便数，有断下之功（痢疾滞气未尽者勿遽用，勉强固涩，必变他证），去疳 \n、樗皮尤良（时珍曰∶椿皮入血气而性涩；樗皮入气分而胜利。凡血分受病不足者宜椿皮； \n气分受病有郁者宜樗皮。《乾坤生意》治疮肿下药，用樗皮水研，服汁取利，是其验矣。昂 \n按∶樗皮止泻痢，终是涩剂。寇氏曰∶一妇年四十余，耽饮无"},
  "楮实":{o:["楮实"],src:["本草备要"],d:"平，补，助阳 \n甘寒。助阳气，起阴痿，补虚劳，壮筋骨，明目充肌（时珍曰∶《别录》、《大明》皆 \n云楮实大补益，而《修真秘书》又云久服令人骨痿，《济生秘览》治骨哽用楮实煎汤，岂非 \n软骨之征乎？《本草发明》甚言其功，而云今补药中罕用，惜未之察耳）。 \n取子浸去浮者，酒蒸用。 \n楮皮善行水。治水肿气满（皮可为纸。楮汁和白芨飞面，调糊接纸，永不解脱）。"},
  "榆白皮":{o:["榆白皮"],src:["本草备要"],d:"滑，利窍 \n甘滑下降。入大、小肠、膀胱经。行经脉、利诸窍，通二便，渗湿热，滑胎产（或胎死 \n腹中，服汁可下），下有形留着之物。治五淋肿满（《备急方》∶捣屑作粥食，小便利差）喘 \n咳不眠（嵇康《养生论》∶榆令人瞑），疗疥癣秃疮，消赤肿妒乳（乳痈汁不出，内结成肿， \n名妒乳。和陈醋滓调，日六七易效。《十剂》曰∶滑可去着，冬葵子、榆白皮之属是也）。 \n有赤白二种，去粗皮，取白用（采皮为面，荒年当粮可食。"},
  "榧实":{o:["榧实"],src:["本草备要"],d:"润肺 \n甘涩。润肺（《本草》未尝言润，然润剂也。故寇氏云∶多食润肠）杀虫（有虫积者， \n宜上旬日日食之，食一斤，虫乃绝）。"},
  "榼藤子":{o:[],src:["本草纲目"],d:"喉痹肿痛︰藤子烧研，酒服一钱。（《圣惠方》）五痔下血︰藤子烧存性。米饮服二钱，有功。"},
  "槐实":{o:["槐实"],src:["本草备要"],d:"\\x即槐角\\x \n泻风热，凉大肠 \n苦寒纯阴。入肝经气分。疏风热，润肝燥，凉大肠。 \n治烦闷风眩，痔血肠风（粪前有血名外痔，粪后有血名内痔，谷道 肉名举痔，头上有 \n孔名痔 ，疮内有虫名虫痔。大法用槐角、地榆、生地以凉血，芩、连、栀、柏以清热。防 \n风、秦艽以祛风湿，芎、归、人参以和血生血，枳壳以宽肠，升麻以升提。治肠风略同，不 \n宜专用寒凉，须兼补剂收功），阴疮湿痒，明目止泪（清肝，泪为肝热），"},
  "樗鸡":{o:[],src:["本草纲目"],d:"新四。子宫虚寒︰《杏林摘要》云︰妇人无子，由子宫虚寒，下元虚，月水不调，或闭或漏，或崩中豆一百二十枚，为末。枣肉为丸，如弹子大。"},
  "樟脑":{o:["樟脑"],src:["本草备要"],d:"宣，通窍，除湿 \n辛热香窜，能于水中发火（置水中焰益炽）。通关利滞，除湿杀虫。置鞋中去香港脚（《集 \n要》曰∶和乌头为末，醋丸弹子大，置足心，微火烘之，汗出为效）熏衣箧，辟疰虫。以樟 \n木切片，浸水煎成。升打得法，能乱冰片。"},
  "橄榄":{o:["橄榄"],src:["本草备要"],d:"宣，清肺 \n甘涩而温。肺、胃之果，清咽生津，除烦醒酒，解河豚毒（投入煮佳）及鱼骨鲠（如无 \n橄榄，以核磨水服。橄榄木作舟楫，鱼拨即浮出，物之相畏有如此者）。 \n核，烧灰，敷疰疳良。"},
  "水斳":{o:[],src:["本草纲目"],d:"旧一，新二。小儿吐泻：芹菜切细，煮汁饮之，不拘多少。（《子母秘录》）。"},
  "水杨柳":{o:["水杨柳"],src:["本草备要"],d:"宣，行气血 \n苦平。痘疮顶陷，浆滞不起者，用枝煎汤浴之（此因气凝血滞，或风寒外束而热，得此 \n暖气透达，浆随暖而行，再用助气血药更效）。 \n枝，煎汁，治黄胆。"},
  "水苏":{o:[],src:["本草纲目"],d:"漏血欲死︰鸡苏煮汁一升，服之。（《梅师方》）吐血下血︰鸡苏茎叶，煎汁饮之。（《梅师方》）吐血咳嗽︰龙脑薄荷焙研末。"},
  "水萍":{o:[],src:["本草纲目"],d:"夹惊伤寒︰紫背浮萍一钱，犀角屑半钱，钓藤钩三七个，为末。每服半钱，蜜水调下，连消渴饮水︰日至一石者。浮萍捣汁服之。"},
  "水蛇":{o:[],src:["本草纲目"],d:"新一。《圣惠》水蛇丸︰治消渴，四肢烦热，蜗牛五十个（水浸五日取涎），入天花粉末煎稠，丸，姜汤下。皮。 ；新二。小儿骨疮︰《海上方》诗云︰小儿骨痛不堪言，出血流脓实可怜。寻取水蛇皮一个，烧灰蛇一条，去头尾，取中截如手指长，剖去骨肉。"},
  "水银":{o:["水银"],src:["本草备要", "本草纲目"],d:"重，外用杀虫 \n辛寒，阴毒。功专杀虫。治疮疥虮虱（性滑重，且入肉。头疮切不可用，恐入经络，令 \n人筋骨拘挛），解金、银、铜、锡毒（能杀五金），堕胎绝孕。从丹砂烧 而出。畏磁石、砒 \n霜。得铅则凝，得硫则结，并枣肉入唾研则碎。散失在地者，以花椒、茶末收之。"},
  "水银粉":{o:[],src:["本草纲目"],d:"小儿初生︰浴汤中入盐少许，拭干，以腻粉少许摩其身，既不畏风，又散诸气。（《全幼心鉴》）初生锁肚︰证由胎中热毒，结于肛门，儿生之后，闭而不通三日者。急令妇人咂儿前后心手足心并脐七处，四、五次。"},
  "汤瓶内碱":{o:[],src:["本草纲目"],d:"消渴引饮︰汤瓶内碱、葛根、水萍（焙）等分。每服五钱，水煎服。又方︰汤瓶内碱、菝根（炒）各一两，乌梅（连核）二两（焙）。"},
  "沙参":{o:["沙参"],src:["本草备要", "本草纲目"],d:"补阴，泻肺火 \n甘苦微寒。味淡体轻，专补肺气，清肺养肝，兼益脾肾（脾为肺母，肾为肺子）。久嗽 \n肺痿，金受火克者宜之，寒客肺中作嗽者勿服（人参补五脏之阳，沙参补五脏之阴，肺热者 \n用之，以代人参）。 \n似人参而体轻松，白实者良，生沙地者长大，生黄土者瘦小。畏防己。反黎芦（北地 \n真者难得。郑奠一曰∶能疗胸痹、心腹痛、邪热结，去皮肤游风、疥癣、恶疮、疝气、崩带） \n。"},
  "没石子":{o:["没石子"],src:["本草备要"],d:"涩精，外用染须 \n苦温入肾。须精固气，收阴汗，乌须发。出大食诸番。颗小、纹细者佳。炒研用，虫食 \n成孔者拣去。忌铜、铁器。"},
  "河砂":{o:[],src:["本草纲目"],d:"人溺水死︰白沙（炒），覆死人面上下，惟露七孔，冷湿即易。（《千金》）。"},
  "泽漆":{o:["泽漆"],src:["本草备要", "本草纲目"],d:"通，行水 \n辛苦微寒。消痰退热，止嗽杀虫，利大、小肠。治大腹水肿，益丈夫阴气。 \n生平泽，叶园黄绿，颇类猫睛，一名猫儿眼睛草。茎中有白汁，黏人（时珍曰∶《别录 \n》云是大戟苗，非也。功相类耳）。"},
  "浮石":{o:["浮石"],src:["本草备要", "本草纲目"],d:"\\x一名海石\\x \n泻火，软坚 \n咸润下，寒降火。色白体轻，入肺清其上源（肺为水之上源）。止渴止嗽，通淋软坚， \n除上焦痰热，消瘿瘤结核（顽痰所结，咸能软坚。俞琰《席上腐谈》云∶肝属木，当浮而反 \n沉；肺属金，当沉而反浮何也？以肝实而肺虚也。故石入水则沉，而南海有沉水之香，虚实 \n之反如此）。水沫日久结成，海中者味咸更良。"},
  "浮萍":{o:["浮萍"],src:["本草备要"],d:"轻，发汗，利湿 \n辛散轻浮。入肺经，达皮肤，能发扬邪汗（丹溪曰∶浮萍发汗，甚于麻黄），止瘙痒、 \n消渴（捣汁服）生于水，又能下水气，利小便。 \n治一切风湿瘫痪（浮萍一味，蜜丸酒服，治三十六种风；浓煮汁浴，治恶疾疮癞遍身）。 \n烧烟辟蚊。 \n紫背者良。"},
  "海带":{o:["海带"],src:["本草备要"],d:"下水消瘿，功同海藻。似海藻而粗，柔弱而长。"},
  "海松子":{o:["海松子"],src:["本草备要"],d:"润燥 \n甘温。润肺温胃，散水除风。治咳嗽（松子一两，胡桃二两，炼蜜和服，治肺燥咳嗽） \n虚秘（同柏子仁、麻仁，溶蜡为丸，名三仁丸）。出辽东云南，松须五鬣。"},
  "海桐皮":{o:["海桐皮"],src:["本草备要"],d:"宣，祛风湿 \n苦温（《经疏》云∶应兼辛）。入血分。祛风、去湿、杀虫，能行经络达病所。治风蹶顽 \n痹，腰膝疼痛（《传信方》∶海桐、薏苡各二两，芎 、羌活、地骨皮、五加皮各二两，甘 \n草五钱，生地七两，酒二斗浸，此方不得增减。早、中、晚饮，常令醺醺），疳 疥癣，目 \n赤（煎洗）牙虫（煎服，或含漱）。出广南。皮白坚韧，作索不烂。"},
  "海狗肾":{o:["海狗肾"],src:["本草备要"],d:"\\x一名腽肭脐\\x \n补肾，助阳 \n甘咸大热。补肾助阳，治虚损劳伤，阴痿精冷，功近苁蓉、锁阳。出西番，今东海亦有 \n之。似狗而鱼尾。置器中长年湿润，腊月浸水不冻。置睡犬旁，犬惊跳者为真（或曰∶连脐 \n取下故名脐，或曰∶乃腽肭兽之脐也。昂按∶两名不类，恐一是海鱼之肾。一是山兽之脐也 \n。《纲目》以此条入兽部）。"},
  "海马":{o:[],src:["本草纲目"],d:"新二。海马汤︰治远年虚实积聚症块。用海马雌雄各一枚，木香一两，大黄（炒）、白牵牛（炒）各二两，巴豆四十九粒，青皮二两（童子小便浸软，包巴豆扎定，入小便内再浸七日，取出麸炒黄色，去豆不用），取皮同众药为末。"},
  "淡竹叶":{o:["淡竹叶"],src:["本草备要"],d:"泻上焦烦热 \n辛淡甘寒。凉心暖脾，消痰止渴。除上焦风邪烦热（叶生竹上，故治上焦。仲景治伤寒 \n发热、大渴，有竹叶石膏汤。乃假其辛寒，以散阳明之邪热也），咳逆喘促，呕哕吐血，中 \n风失音，小儿惊痫。竹生一年以上者，嫩而有力。"},
  "淡豆豉":{o:["淡豆豉"],src:["本草备要"],d:"宣，解表，除烦 \n苦泄肺、寒胜热（陈藏器曰∶豆性生平，炒熟、热煮食寒，作豉冷）。发汗解肌，调中 \n下气。治伤寒头痛，烦躁满闷，懊 不眠，发斑呕逆（凡伤寒呕逆烦闷，宜引吐，不宜用下 \n药以逆之。淡豉合栀子，名栀子豉汤，能吐虚烦），血痢温疟（时珍曰∶黑豆性平，作豉则 \n温，既经蒸 ，故能升能散。得葱则发汗，得盐则能吐，得酒能治风，得薤则治痢，得蒜则 \n止血，炒熟又能止汗。孟诜治盗汗，炒香渍酒服。《肘后"},
  "清风藤":{o:[],src:["本草纲目"],d:"风湿痹痛︰青藤根三两，防己一两，咀。入酒一瓶煮饮。（《普济方》）一切诸风︰青藤膏︰用青藤，出太平荻港上者，二、三月采之，不拘多少，入釜内，微火熬七日夜成膏，收入瓷器内。"},
  "漆":{o:["漆"],src:["本草备要"],d:"泻，破血，消积，杀虫 \n辛温有毒。功专行血杀虫，削年深坚结之积滞（丹溪曰∶漆性急而飞补，用之中节，积 \n滞去后，补性内行，人不知也），破日久凝结之瘀血（能化瘀血为水），续筋骨绝伤（损伤必 \n有瘀血停滞）。治传尸劳瘵，瘕疝蛔虫。炒令烟尽入药，或烧存性，用半夏为使。畏川椒、 \n紫苏、鸡子、蟹（漆得蟹而成水）。"},
  "漏篮子":{o:[],src:["本草纲目"],d:"一切恶痢杂下，及休息痢︰百岁丸︰用漏篮子一个（大者），阿胶、木香、黄连、罂粟壳各半两，俱炒焦存性，入乳香少许为末，糊丸梧子大。每一岁一丸，米饮下。（罗天益《卫生宝鉴》）。"},
  "漏芦":{o:["漏芦"],src:["本草备要", "本草纲目"],d:"泻热，解毒 \n咸软坚，苦下泄，寒胜热。入胃、大肠，通肺、小肠。散热解毒，通经下乳，排脓止血 \n，生肌杀虫。 \n治遗精尿血，痈疽发背（古方以漏芦汤为称首），及预解时行痘疹毒（取其寒胜热，又 \n能入阳明故也）。 \n出闽中，茎如油麻，枯黑如漆者真。甘草拌蒸。连翘为使。"},
  "灯心草":{o:["灯草"],src:["本草备要", "本草纲目"],d:"轻，通，利水，清热 \n甘淡而寒。降心火（心能入心），清肺热，利小肠（心与小肠相表里，心火清则肺热小 \n肠亦清，而热从小便出矣），通气止血。 \n治五淋水肿，烧灰吹喉痹，涂乳止夜啼，擦癣最良（缚成把，擦摩极痒时，虫从草出， \n浮水可见，十余次则能断也）。"},
  "灰藋":{o:[],src:["本草纲目"],d:"新一。疔疮恶肿︰野灰菜叶烧灰，拨破疮皮，唾调少许点之，血出为度。（《普济》）子仁。"},
  "灵砂":{o:[],src:["本草纲目"],d:"伏热吐泻︰阴阳丸︰用硫黄半两，水银一钱，研黑，姜汁糊丸小豆大。三岁三丸，冷水下；大人三、四十丸。（郑氏《小儿方》）诸般吐逆︰方同上。"},
  "炉甘石":{o:["炉甘石"],src:["本草备要", "本草纲目"],d:"燥温，治目疾 \n甘温。阳明胃经药。受金、银之气，金胜木，燥胜湿，故止血消肿，收湿除烂，退赤去 \n翳，为目疾要药。产金银坑中，金银之苗也。状如羊脂，松似石脂，能点赤铜为黄（今之黄 \n铜，皆其所点也）。 红、童便淬七次，研粉，水飞用。"},
  "烟草":{o:["烟草"],src:["本草备要"],d:"\\x新增\\x \n宣，行气，辟寒 \n辛温有毒。 \n治风寒湿痹，滞气停痰，山岚瘴雾。其气入口，不循常度，顷刻而周一身，令人通体俱 \n快，醒能使醉，醉能使醒，饥能使饱，饱能使饥。 \n人以代酒代茗，终身不厌（故一名相思草）。然火气熏灼，耗血损年，人自不觉耳。闽 \n产者佳（烟筒中水，能解蛇毒）。"},
  "熊胆":{o:["熊胆"],src:["本草备要"],d:"泻热 \n苦寒。凉心平肝，明目杀虫。治惊痫五痔（涂之取瘥）。通明者佳。性善辟尘。扑尘水 \n上，投胆少许，则豁然而开。"},
  "燕脂":{o:[],src:["本草纲目"],d:"婴孩鹅口，白浓如纸︰用坯子燕脂，以乳汁调涂之，一宿效。男用女乳，女用男乳。（《集简方》）漏疮肿痛︰猪胆七个，绵燕脂十个洗水，和匀，搽七次即可。"},
  "牛肉":{o:["牛肉"],src:["本草备要"],d:"补脾土 \n甘温属土。安中补脾，益气止渴（倒仓法，用牡黄牛肉二十斤，洗净，煮为糜，滤去渣 \n，熬成琥珀色。前一晚不食，至日，空腹坐密室，取汁每饮一钟。少时又饮，积数十钟，身 \n体觉痛。如病在上则吐，在下则利，在中则吐而利，利后必渴，即饮已溺数碗，以涤余垢。 \n饥倦先与米饮，二日与淡粥，次与浓粥软饭，将养一月沉 悉安矣。须断房事半年，牛 \n肉五年。丹溪曰∶牛坤土，黄中色，肉、胃药，液、无形之物也！积聚"},
  "牛虱":{o:[],src:["本草纲目"],d:"新二。预解痘毒︰谈野翁方︰用白水牛虱一岁一枚，和米粉作饼，与儿空腹食之，取下恶粪，终身可免痘疮之患。一方︰用白牛虱四十九枚（焙），绿豆四十九粒，朱砂四分九厘，研末，炼蜜丸小豆大，以绿豆汤下。"},
  "牛黄":{o:["牛黄"],src:["本草备要"],d:"泻热，利痰，凉惊 \n甘凉。牛有病，在心、肝、胆之间凝结成黄，故还以治心、肝、胆之病（《经疏》云∶ \n牛食百草，其精华凝结成黄，犹人之有内丹。故能散火、消痰、解毒，为世神物。或云牛病 \n乃生黄者，非也）。清心解热，利痰凉惊，通窍辟邪。治中风入脏，惊痫口噤（心热则火自 \n生焰，肝热则木自生风，风火相搏，胶痰上壅，遂致中风不语。东垣曰∶中脏宜之。若中 \n腑及血脉者用之，反能引风入骨，如油入面。按∶中风中"},
  "牡丹":{o:[],src:["本草纲目"],d:"疝偏坠，气胀不能动者。牡丹皮、防风等分。为末，酒服二钱，甚效。"},
  "牡蒿":{o:[],src:["本草纲目"],d:"疟疾寒热︰齐头蒿根、滴滴金根各一把。擂生酒一钟，未发前服。以滓敷寸口，男左女右。"},
  "牵牛":{o:["牵牛"],src:["本草备要"],d:"大泻气分湿热 \n辛热有毒，属火善走。入肺经，泻气分之湿热（肺主气，火能平金而泄肺），能达右肾 \n命门，走精隧，通下焦郁遏。及大肠风秘、气秘，利大小便，逐水消痰，杀虫堕胎。 \n治水肿喘满 癖气块。若湿、热在血分、胃弱气虚人禁用（东垣曰∶牵牛苦寒误矣，其 \n味辛辣，久嚼猛烈雄壮，所谓苦寒安在哉？乃泻气之药，比诸辛药泄气尤甚。若湿从下受， \n下焦主血，血中之湿，宜苦寒之味。而反用辛热之药，泄上焦之气，是"},
  "犀角":{o:["犀角"],src:["本草备要"],d:"泻心、胃大热 \n苦酸咸寒。凉心泻肝，清胃中大热，祛风利痰，辟邪解毒。治伤寒时疫，发黄发斑（伤 \n寒下早，热乘虚入胃则发斑；下迟，热留胃中亦发斑），吐血下血，蓄血谵狂，痘疮黑陷， \n消痈化脓，定惊明目。妊妇忌之（能消胎气。时珍曰∶五脏六腑，皆禀气于胃。风邪热毒， \n必先干之，饮食药物，必先入胃。角，犀之精华所聚，足阳明胃药也。故能入阳明，解一切 \n毒，疗一切血，及惊、狂、斑、痘之证。《抱朴子》云∶犀"},
  "犬肉":{o:["犬肉"],src:["本草备要"],d:"补虚寒 \n酸而咸温。暖脾益胃，脾胃暖则腰肾受荫矣。补虚寒，助阳事（两肾、阴茎尤胜）。黄 \n者补脾，黑者补肾。畏杏仁。忌蒜（道家以为地厌。黄犬血，酒服二碗，治肠痈）。"},
  "独活羌活":{o:[],src:["本草纲目"],d:"中风口噤，通身冷，不知人。独活四两。好酒一升，煎半升服。"},
  "独用将军":{o:[],src:["本草纲目"],d:"下痢噤口︰独将军草根，有珠如豆者，取珠捣汁三匙，以白酒半杯和服。（《简便方》）。"},
  "猪肉":{o:["猪肉"],src:["本草备要"],d:"脏腑引经 \n水畜，咸寒。 \n心血，用作补心药之向导，盖取以心归心、以血导血之意（《延寿丹书》曰∶猪临杀， \n惊气入心，绝气入肝，皆不可多食）。 \n尾血，和龙脑（冰片），治痘疮倒 （能发之，时珍曰∶取其动而不息，亦有用心血者）。 \n肝，主藏血，补血药用之，入肝明目（雄者良。同夜明砂作丸，治雀目。雀目者，夜不 \n能睹，湿痰及肝火盛也）。 \n肺，补肺，治肺虚咳嗽（咳血者，蘸薏仁末食）。 \n肚，入胃健脾（"},
  "獭肝":{o:["獭肝"],src:["本草备要"],d:"补肝肾，杀传尸 \n甘咸而温。益阴补虚，杀虫止嗽，治传尸鬼疰有神功（尸疰、鬼疰乃五疰之一，变动有 \n三十三种，乃至九十九种。其症使人寒热，沉沉默默，不知病之所苦，而无处不恶，死后传 \n入，乃至灭门。古方有獭肝丸。獭肝烘干，炙为末。水服二钱，日三次，以瘥为度）。诸肝 \n皆有叶数，惟獭肝一月一叶，其间又有退叶，须于獭身取下，不尔多伪（吴鹤皋曰∶獭阴物 \n，昼伏夜出，故治鬼疰。昂谓∶不然，缘其肝独异于他兽"},
  "玄明粉":{o:[],src:["本草纲目"],d:"热厥气痛︰玄明粉三钱，热童尿调下。（《集简方》）伤寒发狂︰玄明粉二钱，朱砂一钱。末之。"},
  "玄精石":{o:[],src:["本草纲目"],d:"正阳丹︰治伤寒三日，头痛壮热，四肢不利。太阴玄精石、硝石、硫黄各二两，砂一两。细研，入瓷瓶固济。"},
  "玉":{o:[],src:["本草纲目"],d:"小儿惊啼︰白玉二钱半，寒水石半两，为末，水调涂心下。（《圣惠方》）癖鬼气，往来疼痛，及心下不可忍者，不拘大人小儿。白玉、赤玉等分，为末，糊丸梧子大。"},
  "玉簪":{o:[],src:["本草纲目"],d:"乳痈初起︰内消花（即玉簪花），取根擂酒服，以渣敷之。（《海上方》）妇人断产︰白鹤仙根、白凤仙子各一钱半，紫葳二钱半，辰砂二钱，捣末，蜜和丸梧子大。产内三十日，以酒半盏服之。"},
  "王瓜":{o:["王瓜"],src:["本草备要", "本草纲目"],d:"\\x即土瓜根\\x \n泻热，利水，行血 \n苦寒。泻热利水。治天行热疾，黄胆消渴（捣汁饮），便数带下，月闭瘀血。利大、小 \n肠，排脓消肿，下乳（通乳药多用之，单服亦可）堕胎。 \n根如栝蒌之小者，味如山药，根、子通用（《经疏》曰∶主治略似栝蒌。伤寒发斑，用 \n王瓜捣汁，和伏龙肝末服，甚效）。"},
  "珍珠":{o:["真珠"],src:["本草备要"],d:"泻热，定惊 \n甘咸性寒。感月而胎（语云∶上巳有风梨有蠹，中秋无月蚌无胎），水精所孕。水能制 \n火，入心、肝二经。镇心安魂（肝藏魂。昂按∶虽云泻热，亦借其宝气也。大抵宝物多能镇 \n心安魂，如金箔、琥珀、真珠之类。龙齿安魂，亦假其神气也），坠痰拔毒，收口生肌。治 \n惊热痘疗，下死胎胞衣（珠末一两，苦酒服），涂面好颜色，点目去翳膜，绵裹塞耳治聋。 \n取新洁未经钻缀者，乳浸三日，研粉极细用（不细伤人脏腑。"},
  "琥珀":{o:["琥珀"],src:["本草备要"],d:"通，行水，散瘀，安神 \n甘平。以脂入土而成实，故能通塞以宁心。安魂魄，疗癫邪（从镇坠药，则安心神）。 \n色赤入手少阴、足厥阴（心、肝）血分，故能消瘀血，破症瘕，生肌肉，合金疮（从辛温药、 \n则破血生肌）。其味甘淡上行，能使肺气下降而通膀胱（经曰∶饮食入胃，游溢精气。上输 \n于脾，脾气散精，上归于肺，通调水道，下输膀胱。凡渗药皆上行而后下降），故能治五淋， \n利小便，燥脾土（从淡渗药，则利窍行水。然"},
  "甘松香":{o:["甘松香"],src:["本草备要", "本草纲目"],d:"宣，理气醒脾 \n甘温芳香。理诸气，开脾郁。 \n治腹卒然满痛，风疳齿 ，香港脚膝浮。煎汤淋洗。 \n出凉州及黔蜀。叶如茅，用根（根极繁密）。"},
  "甘澜水":{o:["甘澜水"],src:["本草备要"],d:"补 \n用流水以瓢扬万遍，亦曰劳水。水性咸而重，劳之则甘而轻。仲景用煎伤寒劳伤等药， \n取其不助肾气而益脾胃也。"},
  "甘蔗":{o:["甘蔗"],src:["本草备要"],d:"补脾，润燥 \n甘寒。和中助脾，除热润燥，止渴（治消渴）消痰，解酒毒，利二便（《外台方》∶嚼咽 \n或捣汁，治发热口干便涩）。治呕哕反胃（《梅师方》∶蔗汁、姜汁和服），大便燥结（蔗汁熬 \n之，名石蜜，即白霜糖。唐大历间，有邹和尚始传造法，性味甘温，补脾缓肝，润肺和中， \n消痰治嗽，多食助热损齿生虫。紫沙糖功用略同）。"},
  "甘蕉":{o:[],src:["本草纲目"],d:"发背欲死︰芭蕉根捣烂涂之。（《肘后方》）一切肿毒︰方同上。赤游风疹︰方同上。 ；小儿截惊︰以芭蕉汁、薄荷汁煎匀，涂头顶，留囟门，涂四肢，留手足心勿涂，甚效。（《邓笔峰杂兴》）叶。 ；消或破，皆无痕也。（《仁斋直指方》）花。"},
  "甜瓜蒂":{o:["甜瓜蒂"],src:["本草备要"],d:"宣，涌，吐。与淡豆豉、赤小豆，并为吐药 \n苦寒。阳明（胃）吐药，能吐风热痰涎，上隔宿食（吐去上焦之邪，经所谓其高者因而 \n越之。在上者涌之，木郁达之是也。越以瓜蒂、淡豉之苦，涌以赤小豆之酸，吐去上焦有形 \n之物，则木得舒畅，天地交而万物通矣。当吐而胃弱者，代以参芦。朱丹溪曰∶吐中就有发 \n散之义。张子和曰∶诸汗法，古方多有之，惟以吐发汗，世罕知之。故予尝曰∶吐法兼汗以 \n此夫。昂按∶汗、吐、下、和"},
  "田螺":{o:["田螺"],src:["本草备要"],d:"泻热 \n味甘大寒。利湿清热，止渴（消渴）醒酒，利大、小便（能引热下行。熊彦诚病前后不 \n通，腹胀如鼓，众医莫措。遇一异人曰∶此易耳，奉施一药。即脱靴入水，探得一大螺，曰∶ \n事济矣。以盐和壳捣碎，帛系脐下一寸三分，曾未安席，砉然暴下。归访异人，无所见矣。 \n董守约以香港脚攻注，或教捶数螺系两股，便觉冷气趋下至足，即而亦安）。治香港脚黄胆，噤 \n口毒痢（用螺少加麝，捣饼烘热，贴脐下，引热下行，自然思"},
  "番木鳖":{o:[],src:["本草纲目"],d:"喉痹作痛︰番木鳖、青木香、山豆根等分，为末吹之。（杨拱《医方摘要》）缠喉风肿︰番木鳖仁一个，木香三分，同磨水，调熊胆三分，胆矾五分。以鸡毛扫患处取效。"},
  "番红花":{o:[],src:["本草纲目"],d:"人所传。（王玺《集要》)。"},
  "白石英":{o:["白石英"],src:["本草备要", "本草纲目"],d:"重，润肺 \n甘辛微温。肺、大肠经气分之药。润以去燥，利小便，实大肠。治肺痿吐脓，咳逆上气 \n。但系石类，祗可暂用（《十剂》曰∶湿可去枯，白石英、紫石英之属是也。湿，即润也。 \n按∶润药颇多，石药终燥，而徐之才取二石英为润剂，存其意可取）。白如水晶者良。"},
  "白矾":{o:["白矾"],src:["本草备要"],d:"涩，燥湿，坠痰 \n酸咸而寒，性涩而收。燥湿追涎，化痰坠浊，解毒生津，除风杀虫，止血定痛，通大、 \n小便，蚀恶肉，生好肉，除痼热在骨髓（髓为热所劫则空，故骨痿而齿浮）。治惊痫黄胆， \n血痛喉痹，齿痛风眼，鼻中息肉，崩带脱肛，阴蚀阴挺（阴肉挺出，肝经之火），疔肿痈疽， \n瘰疥癣，虎、犬、蛇、虫咬伤（时珍曰∶能吐风，热痰涎，取其酸苦涌泄也；治诸血痛、 \n阴挺、脱肛、疮疡，取其酸涩而收也；治风眼、痰饮、泄"},
  "白芥":{o:[],src:["本草纲目"],d:"新八。反胃上气：白芥子末，酒服一、二钱。（《普济方》）。"},
  "白芨":{o:[],src:["本草纲目"],d:"鼻衄不止︰津调白芨末，涂山根上，仍以水服一钱，立止。（《经验生编》）重舌鹅口︰白芨末，乳汁调涂足心。（《圣惠方》）妇人阴脱︰白芨、川乌头等分。"},
  "白花蛇":{o:[],src:["本草纲目"],d:"新十三。驱风膏︰治风瘫疠风，遍身疥癣。用白花蛇肉四两（酒炙），天麻七钱半，薄荷、荆芥各二钱半，为末。 ；新一。紫癜风︰除风散︰以白花蛇头二枚（酒浸，炙），蝎梢一两（炒），防风一两，上为末。每服一目睛。"},
  "白芷香":{o:[],src:["本草纲目"],d:"一切伤寒︰神白散，又名圣僧散︰治时行一切伤寒，不问阴阳轻重、老少男女孕妇，皆可服之。用白芷一两，生甘草半两，姜三片，葱白三寸，枣一枚，豉五十粒。水二碗，煎服取汗。 ；小儿身热︰白芷苗、苦参等分。煎浆水，入盐少许洗之。（《卫生总微论》）。"},
  "白苣":{o:[],src:["本草纲目"],d:"旧一。鱼脐疮，其头白似肿，痛不可忍︰先以针刺破头及四畔，以白苣取汁滴孔中，良。（《外台秘要》）。"},
  "白英":{o:[],src:["本草纲目"],d:"补益虚损，极益房劳︰用萝四两，枸杞根皮、五味子、柏子仁、酸枣仁、干地黄各三两。为末。每服方寸匕，酒下，日三服。"},
  "白茅":{o:[],src:["本草纲目"],d:"山中辟谷：凡辟难无人之境，取白茅根冼净，咀嚼，或石上晒焦捣末，水服方寸匕，可辟谷不饥。（《肘后方》）温病冷：因热甚饮水成暴冷者。茅根（切）、枇杷叶（拭去毛，炙香）各半斤。 ；妇人阴痒：墙头烂茅、荆芥、牙皂等分。煎水频熏洗之。（《摘玄方》）大便闭塞，服药不通者。"},
  "白药子":{o:[],src:["本草纲目"],d:"天行热病︰白药为末，浆水一盏，冷调二钱服，仰卧少顷，心闷或腹鸣痛，当吐利数行。如不止，吃冷粥一碗止之。（崔元亮《海上方》）心痛解热︰白药根、野猪尾（二味，洗去粗皮，焙干）等分。"},
  "白蒿":{o:[],src:["本草纲目"],d:"恶疮癞疾，但是恶疾遍体，面目有疮者，皆可服之︰用白艾蒿十束如升大，煮取汁，以曲及米一如酿酒法，候熟稍服之。（《深师方》）子。"},
  "白蔹":{o:["白蔹"],src:["本草备要", "本草纲目"],d:"泻火，散结 \n苦能泄，辛能散，甘能缓，寒能除热。杀火毒，散结气，生肌止痛。 \n治痈疽疮肿，面上 疮，金疮扑损（箭镞不出者，同丹皮或半夏为末，酒服），敛疮方 \n多用之（故名，每与白芨相须），搽冻耳（同黄柏末油调）。 \n蔓赤，枝有五叶，根如卵而长，三五枝同窠，皮乌肉白。一种赤蔹，功用皆用（郑奠一 \n曰∶能治温疟血痢，肠风痔 ，赤白带下）。"},
  "白藓":{o:[],src:["本草纲目"],d:"鼠已破，出脓血者。白藓皮煮汁，服一升，当吐若鼠子也。（《肘后方》）产后中风，人虚不可服他药者。"},
  "白藓皮":{o:["白藓皮"],src:["本草备要"],d:"通，祛风湿 \n气寒善行，味苦性燥（行水故燥）。入脾、胃除湿热，兼入膀胱、小肠。行水道，通关 \n节，利九窍。 \n为诸黄、风痹之要药（一味白藓皮汤，治产后风。时珍曰∶世医止施之疮科，浅矣）。 \n兼 \n治风疮疥癣，女子阴中肿痛（湿热乘虚客肾与膀胱所致）。 \n根黄白而心实。取皮用。恶桑螵蛸、桔梗、茯苓、萆 。"},
  "白蜡":{o:["白蜡"],src:["本草备要"],d:"外用生肌 \n甘温属金。生肌止血（郑赞寰曰∶汪御章年十六，常患尿血，屡医不效。予以白蜡加入 \n冲血滋肾药中，遂愈），定痛补虚，续筋接骨，外科要药。"},
  "白马溺":{o:["白马溺"],src:["本草备要"],d:"泻，杀虫，消症 \n辛寒。杀虫，破症积，治反胃，（祖台之志怪云∶昔有人与奴皆患心腹痛病，奴死，剖 \n之得一鳖，尚活。以诸药投口中，不死。有人乘白马观之，马溺坠鳖而鳖缩，遂以灌之，即 \n化成水。主乃服马溺而愈）。"},
  "白龙须":{o:[],src:["本草纲目"],d:"诸风瘫痪，筋骨不收︰用白龙须根皮一两，闹羊花（即老虎花）七分，好烧酒三斤，封固，煮一炷香，埋土中一夜。能饮者三杯，不能饮者一杯，卧时服。服至三、五杯，见效。"},
  "百棱藤":{o:[],src:["本草纲目"],d:"头风脑痛︰百灵藤十斤，水一石，煎汁三斗，入糯米三斗作饭。候冷，拌神曲炒末九两，同入瓮中，如常酿酒。经三、五日，看沫尽，更炊一斗糯米饭冷投之，待熟澄清。"},
  "百沸汤":{o:["百沸汤"],src:["本草备要"],d:"宣，助阳气 \n助阳气，行经络（汪颖曰∶汤须百沸者佳。寇宗 曰∶患风冷气痹，人以汤淋脚至膝， \n浓复取汗，然别有药，特假阳气而行耳。四时暴泻痢，四肢、脐、腹冷，坐深汤中，浸至腹 \n上，生阳之药，无速于此。张从正曰∶凡伤风寒、酒食，初起无病，便饮太和汤。或酸荠水 \n揉肚探吐，汗出即已。昂按∶感冒风寒，而以热汤澡浴，亦发散之一法。故《内经》亦有可 \n汤熨、可浴及摩之、浴之之文。《备急方》治心腹卒胀痛，欲"},
  "百草霜":{o:["百草霜"],src:["本草备要"],d:"轻，止血，消积 \n辛温。止血（鼻衄者，水调涂之。红见黑则止，水克火也）消积。治诸血病，伤寒阳毒、 \n发斑，疸膈疟痢，咽喉、口舌、白秃、诸疮（时珍曰∶皆兼取火化从治之法）。灶突上烟煤。"},
  "皂矾":{o:["皂矾"],src:["本草备要"],d:"\\x一名绿矾\\x \n涩，燥湿，化痰 \n酸涌涩收。燥湿化痰、解毒杀虫之功与石矾同，而力差缓。主治略同白矾，利小便，消 \n食积（同健脾消食药为丸），散喉痹（醋调咽汁。时珍曰∶胀满、黄肿、疟痢、疳疾方往往 \n用之。其源则自仲景用矾石硝石治女劳黄胆方中变化而来）。深青莹净者良。 赤用（ 赤 \n名绛矾，能入血分，伐肝木，燥脾湿。张三丰治肿满，有伐木丸。苍术二斤，米泔浸，黄酒， \n面曲四两炒，绛矾一斤，醋拌晒"},
  "皂角":{o:["皂角"],src:["本草备要"],d:"通关窍，搜风 \n辛咸性燥，气浮而散。入肺、大肠经。金胜木，燥胜风，故兼入肝。搜风泄热，吹之导 \n之，则通上、下关窍，而涌吐痰涎，搐鼻立作喷嚏。 \n治中风口噤，胸痹喉痹（凡中风不省人事，口噤不能进药。急提头发，手掐人中，用皂 \n角末或半夏末吹入鼻中，有嚏者生，无嚏者肺气已绝，死。或用稀涎散吐之，皂角末一两， \n白矾五钱，每用一钱，温水调灌。或加藜芦、少麝，鹅翎探喉，令微吐稀涎，再用药治。年 \n老、气"},
  "皂角蕈":{o:[],src:["本草纲目"],d:"新一。肠风泻血︰皂角树上蕈，瓦焙为末。每服一钱，温酒下。"},
  "皮":{o:["皮"],src:["本草备要"],d:"泻，凉血 \n苦平。治肠风泻血，五痔（烧末，油调敷，水服亦佳）阴肿。脂滴耳中治聋。胆点痘后 \n风眼。似鼠而圆大，褐色，攒毛，外刺如栗房。 黑存性用。"},
  "益智子":{o:[],src:["本草纲目"],d:"小便频数，脬气不足也。雷州益智子（盐炒，去盐）、天台乌药等分，为末，酒煮山药粉为糊，丸如梧子大。每服七十丸，空心盐汤下。"},
  "省藤":{o:[],src:["本草纲目"],d:"五淋涩痛︰赤藤（即做草鞋者）、白茯苓、苧麻根等分，为末。百沸汤下，每服一钱，如神。"},
  "石":{o:["石"],src:["本草备要"],d:"重，燥，祛寒积 \n辛热，有大毒。治坚癖痼冷，寒湿风痹（苏恭曰∶攻寒冷之病最良。《别录》曰∶不炼 \n服，杀人。此石生于山无雪，入水不冰。时珍曰∶性气与砒石相近。《博物志》言∶鹳伏卵 \n时，取此石暖足。谬也）。有疮、白数种，火烧但解散，不能脱其坚。置水不冻者真。恶羊 \n血。"},
  "石南叶":{o:["石南叶"],src:["本草备要"],d:"宣，去风，补肾 \n辛散风、苦坚肾。补内伤阴衰，利筋骨皮毛，为治肾虚、脚弱、风痹要药。妇人不可久 \n服，令思男（时珍曰∶今人绝不知用，盖为《药性论》有令人阴痿之说也。不知此药能令肾 \n强，人或借此纵欲，以致痿弱，归咎于药，良可慨也。昂按∶石南补阴祛风则有之，然味辛 \n不热，不助相火，亦未闻淫邪方中用石南者，《别录》思男之说，殆不可信）。 \n关中者佳。炙用。"},
  "石榴皮":{o:["石榴皮"],src:["本草备要"],d:"涩肠，外用染须 \n酸涩而温。能涩肠，止泻痢下血（ 末服），崩带脱肛（泻痢至于脱肛者，以石榴皮、 \n陈壁土加明矾少许，浓煎熏洗，再用五倍子炒研、敷托而止之）。浸水，汁黑如墨，乌须方 \n绿云油中用之。勿犯铁器（《客座新闻》云∶一人患腹胀，夏成诊曰∶饮食如常，非水肿蛊 \n胀，乃湿热生虫之象也。以石榴、椿树东引根皮、槟榔各五钱，空心服，腹大痛，泻虫长丈 \n余，遂愈）。"},
  "石灰":{o:["石灰"],src:["本草备要"],d:"重，燥湿，止血，生肌 \n辛温性烈。能坚物散血，定痛生肌，止金疮血（腊月用黄牛胆汁和，纳胆中，阴干用）， \n杀疮虫（有人脚肚生一疮，久遂成漏，百药不效，自度必死。一村人见之曰∶此鳝漏也。以 \n锻石温泡、熏洗、觉痒即是也。洗不数次，遂愈）蚀恶肉，无瘢疵（和药点痣）解酒酸（酒 \n家多用之，然有灰之酒伤人），内用止泻痢、崩带，收阴挺（阴肉挺出，亦名阴菌，或产后 \n玉门不闭。熬黄水泡，澄清暖洗）、脱肛，消积"},
  "石炭":{o:[],src:["本草纲目"],d:"金疮出血︰急以石炭末浓敷之。疮深不宜速合者，加滑石。（《医学集成》）误吞金银及钱，在腹中不下者。"},
  "石燕":{o:[],src:["本草纲目"],d:"伤寒尿涩，小腹胀满︰石燕为末。葱白汤调下半钱，频服，胀通为度。（《圣惠方》）小便淋痛︰石燕子七枚（捣黍米大），新桑根白皮三两（锉）。"},
  "石硫赤":{o:[],src:["本草纲目"],d:"风湿脚气︰石亭脂（生用）一两，川乌头（生）一两，无名异二两。为末，葱白自然汁和丸梧子大。每服一钱，空心淡茶、生葱吞下，日一服。"},
  "石硫黄":{o:["石硫黄"],src:["本草备要", "本草纲目"],d:"燥，补阳，杀虫 \n味酸有毒。大热纯阳（硫黄阳精极热，与大黄极寒，并号将军），补命门真火不足。性 \n虽热而疏利大肠，与燥涩者不同（热药多秘，惟硫黄暖而能通；寒药多泄，惟黄连肥汤而止 \n泻），若阳气暴绝，阳毒伤寒，久患寒泻，脾胃虚寒，命欲垂尽者用之，亦救危妙药也。治 \n寒痹冷癖，足寒无力，老人虚秘（《局方》用半硫丸），妇人阴蚀，小儿慢惊。暖精壮阳，杀 \n虫疗疮，辟鬼魅，化五金，能干汞（王好古曰∶太白丹"},
  "石耳":{o:[],src:["本草纲目"],d:"新一。泻血脱肛︰石耳五两（炒），白枯矾一两，密陀僧半两，为末，蒸饼丸梧子大，每米饮下二十丸。（《普济方》）互考诸菜香薷紫苏紫菀錾菜牛膝苗防风苗薄荷荏苏马兰蒌蒿泽兰根地黄苗诸葵菜酸模菖蒲牛蒡苗青葙苗龙葵决明甘蓝萝红花苗车前苗萱草芦笋茭笋苹海苔菜独帚苗羊蹄蒲笋菜齐头蒿昆布苗昆布地菘蓼芽海藻王瓜百部藕丝荷头芡茎菱茎豆藿豆芽豆荚豆腐罂粟苗椿芽槐芽芜荑枸杞皂荚苗榆芽槿芽棕笋五加{{PD-old}}Categ"},
  "石胆":{o:[],src:["本草纲目"],d:"老小风痰︰胆矾末一钱。小儿一字，温醋汤调下，立吐出涎，便醒。（谭氏小儿方）女人头晕，天地转动，名曰心眩，非血风也。"},
  "石胡荽":{o:[],src:["本草纲目"],d:"寒痰齁喘︰野园荽研汁，和酒服，即住。（《集简方》）。鼻去翳︰碧云散︰治目赤肿胀，羞明昏暗，隐涩疼痛，眵泪风痒，鼻塞头痛脑酸，外翳扳睛诸病。"},
  "石蒜":{o:[],src:["本草纲目"],d:"便毒诸疮：一枝箭，捣烂涂之即消。若毒太甚者，冼净，以生白酒煎服，得微汗即愈。（王永辅《济世方》）产肠脱下：老鸦蒜（即酸头草）一把。"},
  "石蟹":{o:["石蟹"],src:["本草备要", "本草纲目"],d:"重，泻，明目 \n咸寒。治青盲目翳，天行热疾，解一切金石药毒。醋磨，敷痈肿。出南海。身全是蟹， \n而质石也。细研，水飞用。"},
  "石钟乳":{o:[],src:["本草纲目"],d:"钟乳煎︰治风虚劳损，腰脚无力，补益强壮。用钟乳粉炼成者三两，以夹练袋盛之，牛乳一大升，煎减三之一，去袋饮乳，分二服，日一作。不吐不利，虚冷人微溏无苦。"},
  "石首鱼":{o:["石首鱼"],src:["本草备要", "本草纲目"],d:"补，调胃 \n甘平。开胃消食，治暴痢腹胀（《菽园杂记》曰∶痢疾最忌油腻、生冷，惟白鲞相宜。 \n以其无脂不腻，而能消宿食、理肠胃也）。即干白鱼鲞，首中有石，故名（石治石淋。昂按∶ \n今人多以石首鱼鳔合破故纸等药为丸，名鱼鳔丸，云暖精种子。而《本草》全未之及，何也 \n）。"},
  "石龙子":{o:[],src:["本草纲目"],d:"新二。小儿阴︰用蜥蜴一枚烧灰，酒服。（《外台秘要》）诸不愈︰用蜥蜴（炙）三枚，地胆（炒）三十枚，斑蝥（炒）四十枚，为末，蜜丸小豆大。 ；去生胎︰蜥蜴肝、蛇脱皮等分，以苦酒和匀，摩妊妇脐上及左右令温，胎即下也。（《圣惠》）。"},
  "石龙芮":{o:[],src:["本草纲目"],d:"结核气︰堇菜日干为末，油煎成膏。摩之，日三、五度，便瘥。（孟诜《食疗》）蛇咬伤疮︰生堇杵汁涂之。"},
  "矾石":{o:[],src:["本草纲目"],d:"中风痰厥，四肢不收，气闭膈塞者︰白矾一两，牙皂角五钱。为末。每服一钱，温水调下，吐痰为度。"},
  "砂":{o:["砂"],src:["本草备要"],d:"泻，消肉积 \n咸苦辛热，有毒。消食破瘀。治噎膈症瘕，去目翳 肉，暖子宫，助阳道（性大热，能 \n烂五金。《本草》称其能化人心为血，亦甚言不可多服耳。凡煮硬肉，投少许即易烂，故治 \n噎膈、症瘕、肉积有殊功。《鸡峰方》云∶人之脏腑，多因触冒成病，而脾胃最易受触。饮 \n食过多，则停滞难化。冷热不调，则呕吐泻痢，而膏梁者为尤甚。口腹不节，须用消化药。 \n或言饮食既伤于前，难以毒药反攻其后，不使 砂、巴豆等，"},
  "砒石":{o:["砒石"],src:["本草备要", "本草纲目"],d:"大燥，劫痰 \n辛苦而咸。大热大毒，砒霜尤烈。专能燥痰，可作吐药。疗风痰在胸膈，截疟除哮。外 \n用蚀败肉，杀虫枯痔。出信州，故名信石，衡州次之。锡之苗也（故锡壶亦云有毒）。生者 \n名砒黄，炼者名砒霜。畏绿豆、冷水、羊血。"},
  "硝石":{o:[],src:["本草纲目"],d:"头痛欲死︰硝石末吹鼻内，即愈。（《炮炙论》）诸心腹痛︰焰硝、雄黄各一钱。研细末。"},
  "硵砂":{o:[],src:["本草纲目"],d:"元脏虚冷，气攻脐腹疼痛︰用砂一两，以纤霞草末二两和匀，用小砂罐不固济，慢火烧赤，乃入在罐内，不盖口，加顶火一秤，待火尽炉寒取出。用川乌头（去皮脐，生研末）二两，和匀，汤浸蒸饼丸梧子大。每服三丸，木香汤、醋汤任下，日一服。"},
  "硼砂":{o:["硼砂"],src:["本草备要", "本草纲目"],d:"润，生津，去痰热 \n甘微咸凉。色白质轻，故除上焦胸膈之痰热，生津止嗽。治喉痹、口齿诸病（初觉喉中 \n肿痛，含化咽津，则不成痹）。能金而去垢腻，故治噎膈积块，结核 肉，目翳骨哽（碱 \n能软坚，含之咽汁）。出西番者，白如明矾，出南番者，黄如桃胶。能制汞、哑铜（硼砂、 \n砂，并可作金银焊）。"},
  "碱":{o:["碱"],src:["本草备要"],d:"\\x一作碱\\x \n泻，磨积，去垢 \n辛苦涩温。消食磨积，去垢除痰。治反胃噎膈，点痣、 、疣、赘（与矿灰等分，用小 \n麦杆灰，煎干为末。挑破痣，三点即瘥）。发面，浣衣用之。取蓼蒿之属，浸晒烧灰，以原 \n水淋汁，每百斤入粉面二三斤，则凝定如石。"},
  "礜石":{o:[],src:["本草纲目"],d:"风冷脚气︰白石（）二斤，酒三斗，渍三日，稍稍饮之。（《肘后方》）。"},
  "礞石":{o:["礞石"],src:["本草备要", "本草纲目"],d:"重，泻痰 \n甘威有毒，体重沉坠。色青入肝，制以硝石，能平肝下气，为治惊利痰之圣药（吐痰在 \n水上，以石末掺之，痰即随下。王隐君有礞石滚痰丸，能治百病。礞石、焰硝各二两， 研 \n，水飞净一两，大黄酒蒸八两，黄芩酒洗八两，沉香五钱，为末，水丸，量虚实服。时珍曰 \n∶风木太过，来制脾土，气不运化，积滞生痰，壅寒上、中二焦，变生诸证。礞石重坠，硝 \n性疏快，使痰积通利，诸证自除）。气弱脾虚者禁用。坚细青黑"},
  "禹余粮":{o:["禹余粮"],src:["本草备要", "本草纲目"],d:"重，涩固下 \n甘平性涩。手、足阳明（大肠、胃）血分重剂。治咳逆下痢，血闭（症瘕）血崩，能固 \n下（李先知云∶下焦有病患难会，须用余粮、赤石脂），又能催生。石中黄粉，生于池泽。 \n无砂者良。牡丹为使。"},
  "秋石":{o:["秋石"],src:["本草备要"],d:"补肾水，润三焦 \n咸温。滋肾水，润三焦，养丹田，安五脏，退骨蒸，软坚块。治虚劳咳嗽，白浊遗精， \n为滋阴降火之圣药。若煎炼失道，多服误服，反生燥喝之患（咸能走血，且经 炼，中寓暖 \n气，使虚阳妄作，则真水愈亏。）《蒙筌》曰∶每月取童便，每缸用石膏七钱，桑条搅澄， \n倾去清液，如此二三次，乃入秋露水搅澄（故名秋石）如此数次，滓秽净，咸味减，以重纸 \n铺灰上晒干，刮去在下重浊，取轻清者为秋石。世医不取"},
  "秦皮":{o:["秦皮"],src:["本草备要"],d:"涩而补，明目 \n苦寒，色青，性涩。补肝胆而益肾。以能平木（能除肝热）故治目疾（洗目赤，退翳膜） \n惊痫。以其收涩而寒，故治崩带下痢（仲景白头翁汤用之）。以其涩而补下焦，故能益精有 \n子（时珍曰∶天道贵啬，惟收涩故能补。今人只知治目一节，几于废弃，良为可婉）。出西 \n土。皮有白点、渍水碧色、书纸不脱者真。大戟为使。恶吴茱萸。"},
  "积雪草":{o:[],src:["本草纲目"],d:"女子少腹痛︰颂曰︰《天宝单行方》云︰女子忽得小腹中痛，月经初来，便觉腰中切痛连脊间，如刀锥所刺，不可忍者。众医不别，谓是鬼疰，妄服诸药，终无所益，其疾转增。审察前状相当，即用此药。"},
  "稷":{o:["稷"],src:["本草备要"],d:"补、和中 \n甘平。益气和中，宣脾利胃（陶宏景曰∶稷米，人亦不识。书记多云黍与稷相似，又注 \n∶黍米云 米。与黍米相似，而粒殊大，食之不宜，人发旧病。《诗》云∶黍稷稻粱，禾麻 \n菽麦，此八谷也。俗犹不能辨证，况芝英乎？按∶黍、稷辨者颇多，皆无确义。李时珍曰∶ \n稷、黍一类二种。粘者为黍，不粘者为稷。昂谓∶诗人既云八谷，何必取一类者强分二种？ \n是仍为七谷矣。盖 、稷同音，故世妄谓 为稷，不知 乃黍类"},
  "空青":{o:["空青"],src:["本草备要", "本草纲目"],d:"重，明目 \n甘酸而寒。益肝明目，通窍利水。产铜坑中。大块、中空有水者良。"},
  "穿山甲":{o:["穿山甲"],src:["本草备要"],d:"\\x一名鲛鲤\\x \n宣，通经络 \n咸寒善窜（喜穿山），专能行散，通经络，达病所（某处病，用某处之甲，更良），入厥 \n阴、阳明（肝、胃）。治风湿冷痹。通经下乳，消肿溃痈，止痛排脓，和伤发痘（元气虚者 \n慎用）。风、疟、疮科为要药（以其穴山寓水，故能出入阴阳，贯穿经络，达于营分，以破 \n邪结，故用为使），以其食蚁，又治蚁 （漏也，音闾，亦音漏。有妇人项下忽肿一块，渐 \n延至颈，偶刺破，出水一碗，疮久不"},
  "童便":{o:["童便"],src:["本草备要"],d:"\\x一名还元水。饮自己溺，名轮回酒\\x \n平，泻火，补阴，散瘀血 \n咸寒（时珍曰温）。能引肺火下行从膀胱出，乃其旧路，降火滋阴甚速。润肺散瘀（咸 \n走血），治肺痿失音，吐衄损伤（凡跌打损伤、血闷欲死者，擘开口以热尿灌之，下咽即醒。 \n一切金疮受杖，并宜用之，不伤脏腑。若用他药，恐无瘀者，反致误人矣），胞胎不下（皆 \n散瘀之功）。凡产后血晕，败血入肺，阴虚久嗽，火蒸如燎者，惟此可以治之（晋褚澄《劳 "},
  "竹沥":{o:["竹沥"],src:["本草备要"],d:"泻火，滑痰，润燥 \n甘寒而滑。消风降火，润燥行痰，养血益阴（竹之有沥，犹人之有血也。故能补阴清火） \n。利窍明目。 \n治中风口噤，痰迷大热，风痉癫狂，烦闷（《产乳》方∶妊娠苦烦名子烦，竹沥不限多 \n少细服。梅师加茯苓煎）消渴，血虚自汗。然寒胃滑肠、有寒湿者勿服（《经疏》曰∶中风 \n要药。凡中风未有不因阴虚火旺、痰热壅结所致，如果外来风邪，安得复用此寒滑之药治之 \n哉！丹溪曰∶痰在经络、四肢、皮里、"},
  "竹虱":{o:[],src:["本草纲目"],d:"新一。中风偏痹，半身不遂者︰用麻孔，其病处不糊。以竹虱（焙为末）臾药行如风声，口吐出恶水，身出臭汗日，手足如故也。"},
  "竹蠹虫":{o:[],src:["本草纲目"],d:"新六。耳出水︰苦竹蛀屑、野狼牙、白蔹等分，为末和匀，频掺之。（《圣惠》）。"},
  "箬":{o:[],src:["本草纲目"],d:"一切眼疾︰笼烧灰，淋汁洗之，久之自效。（《经验方》）咽喉闭痛︰辽叶、灯心草（烧灰）等分。吹之，甚妙。"},
  "粉铅":{o:[],src:["本草纲目"],d:"劳复食复欲死者︰水服胡粉少许。（《肘后方》）小儿脾泄不止︰红枣二十个去核，将官粉入内，以阴阳瓦焙干，去枣研粉。每服三分，米汤下。"},
  "粉霜":{o:[],src:["本草纲目"],d:"小儿急惊，搐搦涎盛︰粉霜二钱，白牵牛（炒）、轻粉各一钱。为末。每服一字，薄荷汤下，吐涎为效。"},
  "粟":{o:["粟"],src:["本草备要"],d:"补肾 \n甘咸微寒。养肾益气。治胃热消渴，止霍乱，利二便（《千金方》粟米粉水丸，梧子大 \n，煮七枚，纳醋中，细吞之，治反胃吐食）。即粱米。有青、黄、赤、白、黑诸色，陈者良 \n。"},
  "粪清":{o:["粪清"],src:["本草备要"],d:"\\x一名金汁\\x \n泻火热 \n主治同人中黄。用棕皮棉纸，上铺黄土，淋粪滤汁，入新瓮，碗复埋土中一年，清若泉 \n水，全无秽气用。年久者弥佳（野间残粪下土，筛敷痈疽，如冰着背）。"},
  "粳米":{o:["粳米"],src:["本草备要"],d:"\\x粳，硬也\\x \n补脾清肺 \n甘凉。得天地中和之气，和胃补中，色白入肺。除烦清热，煮汁止渴（仲景白虎汤、桃 \n花汤、竹叶石膏汤，并用之以清热、补不足。张文潜《粥记》∶粥能畅胃气，生津液，每晨 \n空腹食之，所补不细。昂按∶今人终日食粥，不知其妙。迨病中食之，觉与脏腑相宜，迥非 \n他物之所能及也）。粳，乃稻之总名，有早、中、晚三收。晚者得金气多，性凉，尤能清热 \n（北粳凉，南粳温，白粳凉，红粳温，新"},
  "糯米":{o:["糯米"],src:["本草备要"],d:"\\x糯，懦也。《本草》名稻米。按∶《诗》，黍、稷、稻、粱、禾、麻、菽、麦，名八\\x \n\\x此稻与禾所以有异乎。\\x \n补温脾肺 \n甘温。补脾、肺虚寒，坚大便，缩小便，收自汗（同龙骨、牡蛎为粉，能扑汗），发痘 \n疮（解毒化脓）。然性粘滞，病患及小儿忌之（糯米酿酒则热，熬饧尤甚。饧即饴糖，润肺 \n和脾，化痰止嗽。仲景建中汤用之，取其甘以补脾缓中。多食发湿热、动痰火、损齿）。"},
  "紫参":{o:[],src:["本草纲目"],d:"紫参汤︰治痢下。紫参半斤。水五升，煎二升，入甘草二两，煎取半升，分三服。"},
  "紫堇":{o:[],src:["本草纲目"],d:"旧一。脱肛，凡大人、小儿脱肛，每天冷及吃冷食，即暴痢不止，肛则下脱，久疗不瘥者：春间收紫堇花二斤，曝干为散，加磁毛末七两，相和研细。涂肛上纳入，即使人冷水于面上，即吸入肠中。"},
  "紫檀":{o:["紫檀"],src:["本草备要"],d:"重，和血 \n咸寒。血分之药。和荣气，消肿毒，敷金疮，止血定痛。"},
  "紫河车":{o:["紫河车"],src:["本草备要"],d:"\\x即胞衣，一名混沌皮\\x \n大补气血 \n甘咸性温。本人之血气所生，故能大补气血，治一切虚劳损极（虚损∶一损肺，皮槁毛 \n落；二损心，血脉衰少；三损脾，肌肉消脱；四损肝，筋缓不收；五损肾，骨痿不起。六极 \n，曰气极、血极、筋极、肌极、骨极、精极），恍惚失志癫痫。以初胎及无病妇人者良。有 \n胎毒者害人（以银器插入，焙煮，不黑则无毒）。长流水洗极净，酒蒸焙干研末。或煮烂捣 \n碎入药（如新瓦炙者，反损其"},
  "紫石英":{o:["紫石英"],src:["本草备要", "本草纲目"],d:"重，镇心，润，补肝 \n甘平。性温而补，重以去怯，湿以去枯。入心、肝血分，故心神不安，肝血不足，女子 \n血海虚寒不孕者宜之（冲为血海，任主胞胎。《经疏》云∶女子系胞于肾及心包络，虚则风 \n寒乘之，故不孕。紫石英辛温，走二经，散风寒，镇下焦，为暖子宫之要药）。色深紫莹彻 \n，五棱。火 、醋淬七次，研末水飞用。二英俱畏附子。恶黄连（石英五色，各入五脏）。"},
  "紫苏":{o:["紫苏"],src:["本草备要"],d:"宣，发表，散寒 \n味辛入气分，色紫入血分。香温散寒，通心利肺，开胃益脾（气香入胃），发汗解肌， \n和血下气，宽中消痰，祛风定喘，止痛安胎，利大、小肠，解鱼、蟹毒。多服泄人真气（时 \n珍曰∶同陈皮、砂仁，行气安胎；同霍香、乌药，温中止痛；同香附、麻黄，发热解肌；同 \n芎、当归，和血散血；同桔梗、枳壳，利膈宽肠；同卜子、杏仁，消痰定喘；同木瓜、浓 \n朴，散温解暑治霍乱香港脚）。 \n气香者良。宜橘皮。忌"},
  "紫葳":{o:["凌霄花"],src:["本草备要", "本草纲目"],d:"\\x一名紫葳\\x \n泻血热 \n甘酸而寒。入厥阴（心包、肝）血分。能去血中伏火，破血去瘀。 \n生产乳余疾，崩带症瘕，肠结（不大便）血闭，淋 风痒，血热生风之证。女科多用， \n孕妇忌之（《本经》云∶养胎。《经疏》云∶破血之药，非所宜也。肺痈有用之为君药者。凌 \n霄花为末，和密陀僧唾调，敷酒 甚验）。 \n藤生，花开五瓣，黄赤有点，不可近鼻，嗅之伤脑。"},
  "紫金藤":{o:[],src:["本草纲目"],d:"紫金藤丸，补肾脏，暖丹田，兴阳道，减小便，填精髓，驻颜色，润肌肉，治元气虚惫，面目黧黑，口干舌涩，梦想虚惊，耳鸣目泪，腰胯沉重，百节酸疼，项筋紧急，背胛劳倦，阴汗盗汗，及妇人子宫久冷，月水不调，或多或少，赤白带下，并宜服之︰用紫金藤十六两、巴戟天（去心）三两，吴茱萸、高良姜、肉桂、青盐各二两。为末，酒糊丸梧子大。每温酒下二十丸，日三服。"},
  "紫铆":{o:[],src:["本草纲目"],d:"新三。齿缝出血︰紫矿、乳香、麝香产后血晕，狂言失志︰用紫矿一两。为末。"},
  "红曲":{o:["红曲"],src:["本草备要"],d:"宣，破血，燥，消食 \n甘温色赤。入营而破血，燥胃消食，活血和血。治赤白下痢，跌打损伤，产后恶露不尽 \n（李时珍曰∶人之水谷入胃，中焦湿热熏蒸，游溢精气，化为营血，此造化自然之妙也。红 \n曲以白米饭杂曲面母，湿热蒸 ，即变为真红，此人窥造化之巧者也。故治脾胃营血，得同 \n气相求之理）。红入米心、陈久者良（昂按∶红曲温燥，能腐生物使熟。故鱼肉 用之，不 \n特取其色也）。"},
  "红蓝花":{o:[],src:["本草纲目"],d:"六十二种风，张仲景治六十二种风，兼腹内血气刺痛︰用红花一大两，分为四分。以酒一大升，煎钟半，顿服之。不止再服。 ；血气刺痛︰红蓝子一升。捣碎，以无灰酒一大升拌子，曝干，重捣筛，蜜丸梧子大，空心酒下四十丸。（张仲景方）疮疽不出︰红花子、紫草茸各半两，蝉蜕二钱半，水酒钟半，煎减半，量大小加减服。"},
  "线香":{o:[],src:["本草纲目"],d:"杨梅毒疮︰龙挂香、孩儿茶、皂角子各一钱，银朱二钱，为末，纸卷作捻，点灯置桶中，以鼻吸烟，一日三次，三日止。内服解毒药，疮即干。（《集简方》）。"},
  "络石":{o:[],src:["本草纲目"],d:"小便白浊︰方同上。喉痹肿塞，喘息不通，须臾欲绝，神验︰方︰用络石草一两。水一升，煎一大盏。"},
  "续随子":{o:["续随子"],src:["本草备要", "本草纲目"],d:"\\x一名千金子\\x \n泻，行水，破血，解毒 \n辛温有毒，行水破血。 \n治症瘕痰饮，冷气胀满，蛊毒鬼疰。利大、小肠，下恶滞物，涂疥癣疮（玉枢丹用之， \n治百病多效。《经疏》曰∶乃以毒治毒之功）。 \n去壳，取色白者，压去油用（时珍曰∶续随子、大戟、泽漆、甘遂，茎叶相似，主疗亦 \n相似，长于利水，用之得法，皆要药也）。"},
  "绿盐":{o:[],src:["本草纲目"],d:"胎赤眼痛︰盐绿一分，蜜半两。于蚌蛤壳内相和。每夜卧时浆水洗目，炙热点之，能断根。"},
  "绿矾":{o:[],src:["本草纲目"],d:"重舌木舌︰皂矾二钱，铁上烧红，研，掺之。（陆氏《积德堂方》）喉风肿闭︰皂矾一斤，米醋三斤拌，晒干末，吹之。痰涎出尽，用良姜末少许，入茶内漱口，咽之即愈。"},
  "绿豆":{o:["绿豆"],src:["本草备要"],d:"泻热解毒 \n甘寒。行十二经，清热解毒（一切草木、金石、砒霜毒皆治之），利小便，止消渴，治 \n泻痢，连皮用（其凉在皮）。 \n粉，扑痘疮溃烂良（一市民诵观音经甚诚，出行折一足，哀叫菩萨，梦僧授一方，绿豆 \n粉新铫炒紫色，井水调，浓敷纸贴，杉木扎定，其效如神）。"},
  "绿青":{o:[],src:["本草纲目"],d:"服，取吐。（《全婴方》）风痰迷闷︰碧霞丹︰用石绿十两，乌头尖、附子尖、蝎梢各七十个。为末，糊丸芡子大。"},
  "缩砂蔤":{o:[],src:["本草纲目"],d:"冷滑下痢，不禁虚羸。用缩砂仁熬为末，以羊子肝薄切掺之，瓦上焙干为末，入干姜末等分，饭丸梧子大。每服四十丸，白汤下，日二服。"},
  "罗勒":{o:[],src:["本草纲目"],d:"新二。鼻疳赤烂：兰香叶（烧灰）二钱，铜青五分，轻粉二字，为末，日敷三次。（钱乙《小儿方》）。 ；新二。目昏浮翳：兰香子每用七个，睡时水煎服之，久久有效也。（《海上名方》）。"},
  "羊桃":{o:[],src:["本草纲目"],d:"伤寒毒攻，手足肿痛︰羊桃煮汁，入少盐豉渍之。（《肘后》）水汽鼓胀，大小便涩︰羊桃根、桑白皮、木通、大戟（炒）各半斤（锉）。水一斗，煮五升，熬如稀饧。"},
  "羊肉":{o:["羊肉"],src:["本草备要"],d:"补虚劳 \n甘热属火。补虚劳，益气血，壮阳道，开胃健力，通气发疮（仲景治虚羸蓐劳，有当归 \n羊血汤。《十剂》曰∶补可去弱，人参、羊肉之属是也。东垣曰∶人参补气，羊肉补形。凡 \n味同羊肉者，皆补血虚，阳生则阴长也）。 \n羊肝，苦寒（苏颂曰温）色青。补肝而明目（肝以泻为补。羊肝丸，治目疾加黄连）。 \n胆，苦寒。点风泪眼，赤障白翳（腊月入蜜胆中，纸套笼住，悬檐下，待霜出，扫取点 \n眼。又入蜜胆中蒸之，候干"},
  "羊血":{o:["羊血"],src:["本草备要"],d:"解金银、丹石、砒硫一切诸毒。 \n乳，甘温。补肺肾虚，润胃脘、大肠之燥。治反胃消渴，口疮舌肿（含漱），蜘蛛咬伤 \n（有浑身生丝者，饮之瘥）。 \n肉、肝，青 羊良；胆，青羯羊良；乳，白 羊良。骨 用。反半夏、菖蒲。忌铜器（ \n牡羊曰 、曰羝，去势曰羯。子曰羔，羔五月曰 ）。"},
  "羊踯躅":{o:[],src:["本草纲目"],d:"风痰注痛︰踯躅花、天南星，并生时同捣作饼，甑上蒸四五遍，以稀葛囊盛之。临时取焙为末，蒸饼丸梧子大。每服三丸，温酒下。"},
  "羊蹄":{o:[],src:["本草纲目"],d:"大便卒结︰羊蹄根一两，水一大盏，煎六分，温服。（《圣惠方》）肠风下血︰败毒菜根（洗切），用连皮老姜各半盏，同炒赤，以无灰酒淬之，碗盖少顷，去滓，任意饮。（《永类方》）。"},
  "羚羊角":{o:["羚羊角"],src:["本草备要"],d:"泻心、肝火 \n苦咸微寒。羊属火，而羚羊属木，入足厥阴（肝）、手太阴、少阴（肺、心）经。目为 \n肝窍，此能清肝，故明目去障。肝主风，其合在筋，此能祛风舒筋，故治惊痫搐搦，骨痛筋 \n挛；肝藏魂，心主神明，此能泻心、肝邪热，故治狂越僻谬，梦魇惊骇；肝主血，此能散血， \n故治瘀滞恶血，血痢肿毒；相火寄于肝胆，在志为怒，（经曰∶大怒则形气绝，而血菀于上）， \n此能下气降火，故治伤寒伏热，烦懑气逆，食噎不通；"},
  "翘摇":{o:[],src:["本草纲目"],d:"新二。活血明目︰漂摇豆为末，甘草汤服二钱，日二钱。（《卫生易简方》）。"},
  "翻白草":{o:[],src:["本草纲目"],d:"新七。崩中下血︰用湖鸡腿根一两捣碎，酒二盏，煎一盏服。（《濒湖集简方》）。"},
  "肥皂荚":{o:["肥皂荚"],src:["本草备要"],d:"泻热毒 \n辛温。除风湿，去垢腻（故澡身，盥面用之），疗无名肿毒有奇功（不拘奇疡恶毒，用 \n生肥皂去子、弦及筋捣烂，酽醋和敷立愈，不愈再敷奇验。此方方书未载，若贫人，僻地 \n仓卒无药者，用之甚便，故特着之。《集成》曰∶生肥皂火 存性，生油，腻粉调敷诸恶疮 \n）。"},
  "胆矾":{o:["胆矾"],src:["本草备要"],d:"\\x一名石胆\\x \n宣，吐风痰，涩，敛咳逆 \n酸涩辛寒。入少阳胆经。性敛而能上行，涌吐风、热痰诞，发散风木相火。治喉痹（醋 \n调咽，吐痰诞立效）咳逆，痉痫崩淋。能杀虫，治牙虫、疮毒、阴蚀。产铜坑中，乃铜之精 \n液（故能入肝、胆治风木）。磨铁作铜色者真，形似空青鸭嘴色为上（市人多以醋揉青矾伪 \n之）。畏桂、芫花、辛夷、白薇。"},
  "胡卢巴":{o:["胡卢巴"],src:["本草备要"],d:"燥，补肾命，除寒湿 \n苦温纯阳。入右肾命门。暖丹田，壮元阳。 \n治肾脏虚冷，阳气不能归元（同附子、硫黄），瘕疝冷气（同茴香、巴戟、川乌、川楝、 \n吴茱萸），寒湿香港脚。 \n出岭南番舶者良，云是番莱菔子。酒浸曝，或蒸，或炒。"},
  "胡桃":{o:["胡桃"],src:["本草备要"],d:"补命门，肉润，皮涩 \n味甘气热。皮涩（皮敛肺定喘，固肾涩精。今药中罕用，昂谓若用之，当胜金樱、莲须 \n也）肉润，皮汁青黑，属水入肾。通命门，利三焦，温肺润肠，补气养血。佐补骨脂，一木 \n一火，大补下焦（胡桃属木，破故纸属火，有木火相生之妙。古云∶黄柏无知母，破故纸无 \n胡桃，犹水母之无虾也。时珍曰∶三焦者，无气之别使；命门者，三焦之本原。命门指所居 \n之府而言，为藏精、系胞之物；三焦指所治之部而名"},
  "胡桐泪":{o:["胡桐泪"],src:["本草备要"],d:"泻热，杀虫 \n苦能杀虫，咸能入胃软坚，大寒能除热。治咽喉热痛（磨扫取涎），齿 风疳，瘰 结 \n核（苏颂曰∶古方稀用，今口齿家，多用为要药）。出凉肃。乃胡桐脂，入土得斥卤之气结 \n成，如小石片，木泪状如膏油。"},
  "胡椒":{o:["胡椒"],src:["本草备要"],d:"燥，快膈，消痰 \n辛热纯阳。暖胃快膈，下气消痰。治寒痰食积，肠滑冷痢，阴毒腹痛，胃寒吐水，牙齿 \n浮热作痛（合荜茇散之）。杀一切鱼、肉、鳖、蕈（音寻，上声）毒。食料宜之，嗜之者众。 \n多食损肺，走气动火，发疮、痔、脏毒，齿痛目昏。 \n毕澄茄一类二种，主治略同。"},
  "胡瓜":{o:[],src:["本草纲目"],d:"旧一，新六。小儿热痢︰嫩黄瓜同蜜食十余枚，良。（《海上名方》）。"},
  "胡荽":{o:["胡荽"],src:["本草备要", "本草纲目"],d:"宣，发痘疹，辟恶气 \n辛温香窜。内通心脾，外达四肢。辟一切不正之气，痧疹、痘疮不出。煎酒喷之（心脾 \n之气，得芳香而营运，含喷遍身，勿 头面。痘疹家悬挂，辟邪恶，胡荽久食，令人多忘， \n病患不宜食胡荽、黄花菜）。"},
  "胡葱":{o:[],src:["本草纲目"],d:"新一。身面浮肿，小便不利，喘急：用胡葱十茎，赤小豆三合，硝石一两，以水五升，煮葱、豆至熟，候水干，入硝石，同擂成膏。每空心温酒服半匙。"},
  "胡麻":{o:["胡麻"],src:["本草备要"],d:"\\x即芝麻，一名巨胜子，种出大宛，故曰胡麻\\x \n补肝肾，润五脏，清肠 \n甘平。补肺气、益肝肾，润五脏，填精髓，坚筋骨，明耳目，耐饥渴（可以辟谷，但滑 \n肠，与白术并用为胜），乌髭发，利大小肠，逐风湿气（刘河间曰∶麻木谷而治风。又云∶ \n治风先治血，血活则风散，胡麻入肝益血，故风药中不可阙也。郑奠一用鳖虱胡麻，佐苦参、 \n蒺藜，治大疯疥癞，屡有愈者），凉血解毒。生嚼敷小儿头疮。 \n麻油滑胎疗疮，熬"},
  "腊雪水":{o:["腊雪水"],src:["本草备要"],d:"泻热 \n甘寒。治时行瘟疫，宜煎伤寒、火 （音谒，伤暑）之药，抹痱良。"},
  "自然铜":{o:["自然铜"],src:["本草备要", "本草纲目"],d:"重，续筋骨 \n辛平。主折伤，续筋骨，散瘀止痛（折伤必有死血瘀滞经络，然须审虚实，佐以养血、 \n补气、温经之药。铜非 不可用，火毒、金毒相煽，复挟香药，热毒内攻，虽有接骨之功， \n必多燥散之祸，用者慎之）。产铜坑中。火 、醋淬七次，细研，甘草水飞用（昔有饲折翅 \n雁者，雁飞去，故治折伤）。"},
  "船底苔":{o:[],src:["本草纲目"],d:"乳石发动，小便淋沥，心神闷乱︰船底青苔半鸡子大，煎汁温服，日三、四次。（《圣惠。"},
  "艾":{o:[],src:["本草纲目"],d:"伤寒时气，温病头痛，壮热脉盛。以干艾叶三升。水一斗，煮一升，顿服取汗。"},
  "芋":{o:[],src:["本草纲目"],d:"旧二，新二。腹中癖气︰生芋子一斤压破，酒五斤渍二七日。空腹每饮一升，神良。 ；新一。黄水疮︰芋苗晒干，烧存性研搽。（邵真人《经验方》）。"},
  "芍药":{o:[],src:["本草纲目"],d:"旧六，新一十。服食法︰颂曰︰安期生服炼芍药法云︰芍药有二种︰救病用金芍药，色白多脂肉；其木芍药，色紫瘦多脉。若取审看，勿令差错。"},
  "芎䓖":{o:[],src:["本草纲目"],d:"生犀丸︰宋真宗赐高相国，去痰清目，进饮食。生犀丸︰用川芎十两，紧小者，粟米泔浸二日换，切片子，晒干为末，分作两料。每料入麝、脑各一分，生犀半两，重汤煮，蜜和丸小弹子大。"},
  "芙蓉花":{o:["芙蓉花"],src:["本草备要"],d:"泻，凉血，解毒 \n辛平、性滑涎粘。清肺凉血，散热止痛，消肿排脓。治一切痈疽肿毒有殊功（用芙蓉花 \n，或叶、或皮、或根，生捣或干研末，蜜调涂四围，中间留头，干则频换。初起者即觉清凉 \n，痛止肿消。已成者即脓出，已溃者则易敛。疡科秘其名为清凉膏、清露散、铁箍散，皆此 \n物也。或加赤小豆末，或苍耳烧存性为末，加入亦妙）。"},
  "芜夷":{o:["芜夷"],src:["本草备要"],d:"宣，散风湿，泻，消积，杀虫 \n辛散满，苦杀虫，温燥湿化食（诸虫皆因湿而生，气食皆因寒而滞）。祛五脏、皮肤、 \n肢节风湿，心腹积冷，症痛鳖瘕（《直指方》云∶嗜酒人，血入于酒为酒鳖；多气人，血入 \n于气为气鳖；虚劳人，败血杂痰为血鳖。如虫之行，上侵人咽，下蚀人肛，或附胁背，或隐 \n胸腹。惟用芜夷炒，兼暖胃、理气、益血之药，乃可杀之），痔 疮癣，小儿惊疳冷痢（得 \n诃子、豆蔻良），胃中有虫，食即作痛（和"},
  "芜菁":{o:[],src:["本草纲目"],d:"旧七，新七。预禳时疾：立春后遇庚子日，温蔓荆汁，合家大小并服之，不限多少，一年可免时疾。（《神仙教子法》）。 ；旧十二，新十。明目益气：芜菁子一升，水九升，煮汁尽，晒干。如此三度，研细。"},
  "芝":{o:[],src:["本草纲目"],d:"新一。紫芝丸︰治虚劳短气，胸胁苦伤，手足逆冷，或时烦躁口干，目视，腹内时痛，不思饮食，此药安神保精也︰紫芝一两半，山芋（焙）、天雄（炮去皮）、柏子仁（炒）、巴戟天（去心）、白茯苓（去皮）、枳实（去瓤麸炒）各三钱五分，生地黄（焙）、麦门冬（去心焙）、五味子（炒）、半夏（制炒）、附子（炒去皮）、牡丹皮、人参各七钱五分，远志（去心）、蓼实各二钱五分，瓜子仁（炒）、泽泻各五钱，为末，炼蜜丸梧子大。每服十五"},
  "芥":{o:[],src:["本草纲目"],d:"新四。牙龈肿烂，出臭水者：芥菜秆烧存性，研末，频敷之，即愈。飞丝入目：青菜汁点之如神。 ；旧八，新十六。感寒无汗：水调芥子末填脐内，以热物隔衣熨之，取汗出妙。（杨起《简便单方》）。"},
  "芦":{o:[],src:["本草纲目"],d:"生姜各十两，橘皮、茯苓各五两，水二斗，煮八升，去滓，分五服，取汗乃瘥。（《外台秘要》）水煮浓汁，频饮二升。必效。 ；霍乱烦渴腹胀︰芦叶一握，水煎服。又方︰芦叶五钱，糯米二钱半，竹茹一钱。水煎，入姜汁、蜜各半合，煎两沸，时时呷之。 ；干霍乱病，心腹胀痛︰芦蓬茸一把，水煮浓汁，顿服二升。（《肘后方》）诸般血病︰水芦花、红花、槐花、白鸡冠花、茅花等分。水二钟，煎一钟服。"},
  "芦荟":{o:["芦荟"],src:["本草备要"],d:"泻热，杀虫 \n大苦大寒。功专清热杀虫，凉肝明目，镇心除烦。治小儿惊痫五疳，敷 齿湿癣（甘草 \n末和敷），吹鼻杀脑疳，除鼻痒。小儿脾胃虚寒作泻者勿服。出波斯国。木脂也，味苦、色 \n绿者真。"},
  "芭蕉根":{o:["芭蕉根"],src:["本草备要"],d:"泻热 \n味甘大寒。治天行热狂，烦闷消渴，产后血胀（并捣汁服），涂痈肿结热（为末，油调 \n敷。霜后者佳）。"},
  "花乳石":{o:[],src:["本草纲目"],d:"花蕊石散︰治五内崩损，喷血出斗升，用此治之。花蕊石存性，研如粉。以童子小便一钟，男，入酒一半；女，入醋一半，煎温，食后调服二钱，甚者五钱。"},
  "花蕊石":{o:["花蕊石"],src:["本草备要"],d:"涩，止血 \n酸涩气平。专入肝经血分。能化瘀血为水，止金疮出血（刮末敷之即合，仍不作脓。《 \n局方》治损伤诸血，胎产恶血、血晕，有花蕊石散），下死胎胞衣（恶血化则胞胎无阻）。出 \n陕华代地。体坚色黄。 研，水飞用。"},
  "芸苔":{o:["芸薹"],src:["本草备要", "本草纲目"],d:"宣，散血，消肿 \n辛温。散血消肿，捣贴乳痈丹毒（孙思邈曰∶捣贴丹毒，随手即消，其效如神），动疾 \n发疮。即油菜（道家五荤之一）。 \n子，与叶同功，治产难。"},
  "苋":{o:[],src:["本草纲目"],d:"旧二，新五。产后下痢，赤白者︰用紫苋菜一握切煮汁，入粳米三合，煮粥，食之立瘥也。（《寿亲养老书》）。"},
  "苍耳蠹虫":{o:[],src:["本草纲目"],d:"新三。一切疔肿及无名肿毒恶疮︰刘松石《经验方》︰用苍耳草梗中虫一条，白梅肉三、四分，同捣如泥，贴之立愈。《圣济总录》等分为末，蜜调涂之。"},
  "苎根":{o:["苎根"],src:["本草备要"],d:"泻热，散瘀 \n甘寒而滑。补阴破瘀，解热润燥。 \n治天行热疾，大渴大狂，胎动下血，诸淋血淋，捣贴赤游丹毒，痈疽发背，金疮折伤（ \n止血易痂），鸡鱼骨哽（捣如龙眼。鸡骨，鸡汤下，鱼骨，鱼汤下）。汁能化血为水。 \n苎皮与产妇作枕，止血运；安腹上，止产后腹痛（散瘀之功）沤苎汁，疗消渴。"},
  "苏":{o:[],src:["本草纲目"],d:"感寒上气︰苏叶三两，橘皮四两，酒四升，煮一升半，分再服。（《肘后方》）伤寒气喘不止︰用赤苏一把，水三升，煮一升，稍稍饮之。（《肘后》）劳复食复欲死者。 ；顺气利肠︰紫苏子、麻子仁等分，研烂，水滤取汁，同米煮粥食之。（《济生方》）治风顺气，利肠宽中。用紫苏子一升，微炒杵，以生绢袋盛，于三斗清酒中浸三宿，少少饮之。"},
  "苏木":{o:["苏木"],src:["本草备要"],d:"泻，行血，解表 \n甘咸辛凉。入三阴血分。行血去瘀，发散表里风气（宜与防风同用）。治产后血晕（《肘 \n后方》∶煮汁服。《海藏方》∶加乳香，酒服），胀满欲死，血痛血瘕，经闭气壅，痈肿朴伤， \n排脓止痛。多破血，少和血。出苏方国，交、爱亦有。忌铁。"},
  "苦楝子":{o:["苦楝子"],src:["本草备要"],d:"\\x一名金铃子\\x \n泻湿热，治疝，杀虫 \n苦寒有小毒。能入肝舒筋，能导小肠、膀胱之热，因引心包相火下行，通利小便。 \n为疝气要药。亦治伤寒热狂、热厥，腹痛心痛。杀三虫，疗疡疥（《夷坚志》∶消渴症 \n有虫、耗其津液者，取根、皮浓煎，加少麝服，下其虫而渴自止）。脾胃虚寒忌之。 \n川产良。酒蒸（寒因热用）。去皮取肉、去核用。用核则槌碎，浆水煮一伏时去肉用。 \n茴香为使。"},
  "苦瓠":{o:[],src:["本草纲目"],d:"旧八，新十七。急黄病︰苦瓠一枚，开孔，以水煮之，搅取汁，滴入鼻中。去黄水。 ；新一。小儿白秃︰瓠藤同裹盐，荷叶煎浓汁洗，三、五次愈。（《总录》）。"},
  "苦菜":{o:[],src:["本草纲目"],d:"新六。血淋尿血︰苦菜一把，酒、水各半，煎服。（《资生经》）。"},
  "苧麻":{o:[],src:["本草纲目"],d:"痰哮咳嗽︰苧根（存性），为末，生豆腐蘸三五钱，食即效。未全，可以肥猪肉二、三片蘸食，甚妙。（《医学正传》）小便不通︰《圣惠方》︰用麻根、蛤粉各半两，为末。 ；五日采麻叶，阴干为末。每服二钱，冷水调下。勿吃热物，令人闷倒。"},
  "茄":{o:[],src:["本草纲目"],d:"旧六，新十。妇人血黄︰黄茄子竹刀切，阴干为末。每服二钱，温酒调下。 ；新一。风蛀牙痛︰茄蒂烧灰掺之。或加细辛末等分，日用之。 ；新一。牙痛︰秋茄花干之，旋烧研涂痛处，立止。（《海上名方》）。 ；新九。血淋疼痛︰茄叶熏干为末，每服二钱，温酒或盐汤下。隔年者尤佳。"},
  "茄根":{o:["茄根"],src:["本草备要"],d:"泻，散血，消肿 \n散血消肿。煮汁渍冻疮（史国公药酒，用白茄根为君。茄根以马尿浸三日，晒炒为末， \n点牙即落）。 \n茄子甘寒，散血宽肠，动风发病。"},
  "茅香":{o:[],src:["本草纲目"],d:"冷劳久病︰茅香花、艾叶四两，烧存性，研末，粟米饭丸梧子大。初以蛇床子汤下二十丸至三十丸，微吐不妨，后用枣汤下，立效。（《圣济总录》）苗、叶。"},
  "茴香":{o:["茴香"],src:["本草备要", "本草纲目"],d:"\\x古作怀香\\x \n燥，补肾命门，治寒疝 \n大茴辛热。入肾膀胱。暖丹田，补命门，开胃下食，调中止呕。 \n疗小肠冷气， 疝阴肿（疝有七种，气、血、寒、水、筋、狐、 也。肝经病，不属肾 \n经，以厥阴肝脉络阴器也。多因寒湿所致，亦有挟虚者，当加参、术于温散药中），干湿脚 \n气。多食损目发疮。 \n小茴辛平，理气开胃，亦治寒疝。食料宜之。 \n大如麦粒，轻而有细棱者名大茴，出宁夏，他处小者名小茴。自番舶来，实"},
  "茵芋":{o:["茵芋"],src:["本草备要", "本草纲目"],d:"宣，去风湿 \n辛苦微温，有小毒。 \n治风湿拘挛痹痛（时珍曰∶古方治风痫，有茵芋丸；治风痹，有茵芋酒；治产后风，有 \n茵芋膏。风湿诸证多用之。茵芋、石南、莽草，皆治风妙品，近世罕知。莽草辛温有毒，治 \n头风痈肿乳痈疝瘕。苏颂曰∶古方风湿诸酒多用之，今人取叶煎汤热含，治牙虫喉痹甚效。 \n甄权曰∶不入汤）。 \n茎赤，叶如石榴而短浓，茎炙用。"},
  "茵陈蒿":{o:[],src:["本草纲目"],d:"茵陈羹︰除大热黄胆，伤寒头痛，风热瘴疟，利小便。以茵陈细切，煮羹食之。生食亦宜。"},
  "茶":{o:["茶"],src:["本草备要"],d:"泻热，清神，消食 \n苦甘微寒。下气消食，去痰热，除烦渴，清头目（得春初生发之气，故多整肃上膈之功 \n。《汤液》云∶茶苦寒下行，如何是清头目？《蒙鉴》曰∶热下降，则上自清矣），醒昏睡（ \n清神），解酒食、油腻、烧炙之毒，利大、小便。多饮消脂（最能去油）、寒胃（故浓茶能 \n引吐。《千金》疗卒头痛如破，非中冷、中风。由痰、厥气上冲所致，名厥头痛，单煮茶恣 \n饮取吐，直吐出胆汁乃已，渴而即瘥）。酒后饮茶，"},
  "茹":{o:["茹"],src:["本草备要", "本草纲目"],d:"泻，破血 \n辛寒，有小毒。蚀恶肉，排脓血，杀疥虫，除热痹，破症瘕（《内经》同乌贼骨。治妇 \n人血枯）。 \n根如莱菔，皮黄肉白，叶长微阔，折之有汁，结实如豆，一颗三粒。甘草为使。"},
  "茺蔚":{o:[],src:["本草纲目"],d:"济阴返魂丹︰昝殷《产宝》曰︰此方，乃吉安文江高师禹，备礼求于名医所得者，其效神妙，活人甚多，能治妇人胎前、产后诸疾危证。用野天麻，又名益母，又名火，又名负担，即茺蔚子也。叶似艾叶，茎类火麻，方梗凹面，四、五、六月节节开花，红紫色如蓼花，南北随处皆有，白花者不是。"},
  "荆三棱":{o:[],src:["本草纲目"],d:"症瘕鼓胀︰三棱煎︰用三棱根（切）一石。水五石，煮三石，去滓更煎，取三斗汁入锅中，重汤煎如稠糖，密器收之。每旦酒服一匕，日二服。"},
  "荆沥":{o:["荆沥"],src:["本草备要"],d:"宣通经络，滑痰泻热 \n甘平。除风热，化痰涎，开经络，行血气。治中风失音，惊痫痰迷，眩晕烦闷，消渴热 \n痢，为去风化痰妙药。气虚、食少者忌之（《延年秘录》云∶热多用竹沥，寒多用荆沥。丹 \n溪曰∶虚痰用竹沥，实痰用荆沥，并宜姜汁助送，则不凝滞）。 \n牡荆俗名黄荆，截取尺余，架砖上，中间火炙，两头承取汁用。"},
  "草":{o:["草"],src:["本草备要"],d:"宣，去风湿 \n苦辛。生寒，熟温。 \n治肝肾风气，四肢麻痹，筋骨冷痛，腰膝无力，风湿疮疡。若痹痛由脾肾两虚、阴血不 \n足，不由风湿而得者，忌服（风药能燥血）。 \n江东人呼猪为 ，其草似猪咏臭，故名（唐·成讷有进 表。宋·张咏进 表云∶ \n其草金棱银线，素茎紫 ，对节而生，颇同苍耳。臣吃百服，眼目清明，即至千服，须发乌 \n黑，筋力轻健，效验多端）。以五月五日、六月六日、七月七日、九月九日采者尤佳。去粗"},
  "草之三 芳草类五十六种":{o:[],src:["本草纲目"],d:"旧六，新一十。服食法︰颂曰︰安期生服炼芍药法云︰芍药有二种︰救病用金芍药，色白多脂肉；其木芍药，色紫瘦多脉。若取审看，勿令差错。凡采得，净洗去皮，以东流水煮百沸，阴干。停三日，又于木甑内蒸之，上覆以净黄土，一日夜熟，出阴干，捣末。以麦饮或酒服三钱匕，日三。服满三百日，可以登岭绝谷不饥。（《图经本草》）腹中虚痛︰白芍药三钱，炙甘草一钱。夏月，加黄芩五分；恶寒，加肉桂一钱；冬月大寒，再加桂一钱。水二盏"},
  "草乌头":{o:["草乌头"],src:["本草备要"],d:"大燥，开顽痰 \n辛苦大热。搜风胜湿，开顽痰。治顽疮，以毒攻毒，颇胜川乌。然至毒，无所酿制，不 \n可轻投。 \n野生，状类川乌，亦名乌喙。姜汁炒，或豆腐煮用。熬膏，名射罔，敷箭射兽，见面立 \n死。"},
  "草蜘蛛":{o:[],src:["本草纲目"],d:"新二。瘤疣︰用稻上花蜘蛛十余，安桃枝上，待丝垂下，取东边者捻为线系之，七日一换，自消落也。（《总微论》）截疟︰五月五日取花蜘蛛，晒干，绛囊盛之，临期，男左女右系臂上，勿令知之。"},
  "草豆蔻":{o:["草豆蔻"],src:["本草备要"],d:"\\x一名草果\\x \n燥湿祛痰，除痰截疟 \n辛热香散。暖胃健脾，破气开郁，燥湿祛寒，除痰化食。 \n治瘴疠寒疟（佐常山能截疟。或与知母同用，取其一阴一阳，治寒热瘴疟。盖草果治太 \n阴独胜之寒，知母治阳明独胜之火），寒客胃痛（散滞气，利膈痰，因滞因寒者多效），霍乱 \n泻痢，噎膈反胃，痞满吐酸，痰饮积聚。解口臭气、酒毒、鱼肉毒（故食料用之）。过剂助 \n脾热，耗气损目。 \n闽产名草蔻，如龙眼而微长，皮黄白、"},
  "荏":{o:[],src:["本草纲目"],d:"诜食疗。）蛇虺中人（以荏叶烂杵，猪脂和，薄敷上。梅师方。"},
  "荛花":{o:["荛花"],src:["本草备要"],d:"大通，行水 \n辛散结、苦泄热，行水捷药，主治略同芫花。"},
  "荜茇":{o:["荜茇"],src:["本草备要", "本草纲目"],d:"\\x茇、一作拨\\x \n燥，除胃冷，散浮热 \n辛热除胃冷，温中下气，消食祛痰。 \n治水泻气痢（牛乳点服），虚冷肠鸣（亦入大肠经），冷痰恶心，呕吐酸水， 癖阴疝。 \n辛散阳明之浮热，治头痛（偏头痛者，口含温水，随左右以末吹一字入鼻效）、牙痛（寒痛 \n宜干姜、荜茇、细辛，热痛宜石膏、牙硝，风痛宜皂角、僵蚕、蜂房、二乌，虫痛宜锻石、 \n雄黄），鼻渊。多服泄真气，动脾肺之火，损目。 \n出南番，岭南亦有。类椹"},
  "荞麦":{o:["荞麦"],src:["本草备要"],d:"泻，利肠，下气 \n甘寒。降气，宽肠胃沉积（孟诜曰∶能炼五脏垢秽。昂按∶亦解酒积），泄痢带浊，敷 \n痘疮溃烂，汤火灼伤。脾胃虚寒人勿服。"},
  "荠":{o:["荠"],src:["本草备要", "本草纲目"],d:"补，和中，解毒 \n寒利肺，甘解毒（能解百药及蛇虫毒，在诸药中，毒皆自解）。和中止嗽，治消渴强中 \n（渴症下消，茎长兴盛，不交精出，名强中。消渴之后，发为痈疽），痈肿疔毒。 \n似人参而体虚无心，似桔梗而味甘不苦（奸贾多用以乱人参。时珍曰∶荠 即甜桔梗）。"},
  "荠苨":{o:[],src:["本草纲目"],d:"强中消渴︰猪肾荠汤︰治强中之病，茎长兴盛，不交精液自出，消渴之后，即发痈疽。皆由恣意色欲，或饵金石所致，宜此以制肾中热也。用猪肾一具，荠、石膏各三两，人参、茯苓、磁石、知母、葛根、黄芩、栝蒌根、甘草各二两，黑大豆一升，水一斗半，先煮猪肾、大豆，取汁一斗，去滓下药，再煮三升，分三服。"},
  "荭草":{o:[],src:["本草纲目"],d:"瘰&#30311;︰水荭子不以多少，一半微炒，一半生用，同研末。食后好酒调服二钱，日三服。已破癖痞腹胀及坚硬如杯碗者︰用水荭花子一升，另研独颗蒜三十个（去皮），新狗脑一个，皮硝再贴二、三次。 ；胃脘血气作痛︰水荭花一大撮。水二钟，煎一钟服。百户毛菊庄屡验方也。"},
  "荷叶":{o:["荷叶"],src:["本草备要"],d:"轻宣，升阳，散瘀 \n苦平。其色青，其形仰，其中空，其象震（震仰盂），感少阳甲胆之气。烧饭合药，裨 \n助脾，胃而升发阳气（洁古枳术丸，用荷叶烧饭为丸），痘疮倒 者，用此发之（僵蚕等分 \n为末，胡荽汤下。闻人规曰∶胜于人牙、龙脑）。能散瘀血，留好血。治吐、衄、崩、淋， \n损伤产瘀（熬香末服），一切血证，洗肾囊风（东垣曰∶雷头风症，头面疙瘩肿痛，憎寒恶 \n热，状如伤寒，病在三阳，不可过用寒药重剂，诛罚无"},
  "荸荠":{o:["荸荠"],src:["本草备要"],d:"\\x一名凫茈，一名乌芋，一名地栗\\x \n补中，泻热，消食 \n甘微寒滑。益气安中，开胃消食（饭后宜食之），除胸中实热。治五种噎膈（五膈，忧 \n膈、恚膈、气膈、热膈、寒膈。噎亦五种，气噎、食噎、劳噎、忧噎、思噎），消渴黄胆， \n血证蛊毒（末服辟蛊），能毁铜（汪机曰∶食铜钱，食之则钱化。可见为消坚削积之物，故 \n能开五膈，消宿食，治误吞铜也）。"},
  "莎根、香附子":{o:[],src:["本草纲目"],d:"服食法︰颂曰︰唐玄宗《天宝单方图》云︰水香棱根名莎结，亦名草附子，说已见前。其根二大升，捣熬令香，以生绢袋盛，贮于三大斗无灰清酒中浸之。春三月后，浸一日即堪服；冬十月后，即七日，近暖处乃佳。"},
  "莕菜":{o:[],src:["本草纲目"],d:"一切痈疽及疮疖。用荇丝菜或根，马蹄草茎或子（即也），各取半碗，同苧麻根五寸去皮，以石器捣烂，敷毒四围。春夏秋日换四、五次，冬换二、三次，换时以荠水洗之，甚效。"},
  "莨菪":{o:[],src:["本草纲目"],d:"卒发颠狂︰莨菪三升为末，以酒一升渍数日，绞去滓，煎令可丸，如小豆三丸，日三服。当觉口面急，头中如有虫行，额及手足有赤色处，如此，并是瘥候也。未知再服，取尽神良。 ；疟疾不止︰莨菪根烧炭，水服一合。量人强弱用。（《千金方》）恶癣有虫︰莨菪根捣烂，蜜和敷之。"},
  "莱菔":{o:["莱菔"],src:["本草备要", "本草纲目"],d:"\\x俗作萝卜\\x \n宣，行气，化痰，消食 \n辛甘属土。生食升气，熟食降气。宽中化痰，散瘀消食（丹溪曰∶气升则食自降）。治 \n吐血衄血，咳嗽吞酸，利二便，解酒毒，制面毒、豆腐积（昔有人病，梦红裳女子引入宫殿， \n小姑歌云∶五灵楼阁晓玲珑，天府由来是此中，惆怅闷怀言不尽，一丸莱菔火吾宫。一道士 \n云∶此犯大麦毒也。女子心神，小姑脾神。《医经》∶莱菔制面毒，遂以药并莱菔治之，果 \n愈。腐浆见莱菔则难收）"},
  "莲蕊须":{o:["莲蕊须"],src:["本草备要"],d:"涩精 \n甘温而涩。精心通肾，益血固精，乌须黑发，止梦泄遗精，吐崩诸血。略与莲子同功。"},
  "莳萝":{o:[],src:["本草纲目"],d:"新二。闪挫腰痛：莳萝作末，酒服二钱匕。（《永类钤方》）。"},
  "莴苣":{o:[],src:["本草纲目"],d:"旧一，新五。乳汁不通︰莴苣菜煎酒服。（《海上方》）。 ；旧一，新六。乳汁不行︰莴苣子三十枚，研细酒服。又方︰莴苣子一合，生甘草三钱，糯米、粳米各半合，煮粥频食之。"},
  "莼":{o:[],src:["本草纲目"],d:"一切痈疽︰马蹄草即菜，春夏用茎，冬月用子，就于根侧寻取，捣烂敷之。未成即消，已成即毒散。用叶亦可。"},
  "莽草":{o:[],src:["本草纲目"],d:"贼风肿痹，风入五藏恍惚，宜莽草膏主之︰莽草一斤，乌头、附子、踯躅各二两，切，以水和醋一升，渍一宿。猪脂一斤，煎三上三下，绞去滓。向火，以手摩病上三百度，应手即瘥。"},
  "菊":{o:[],src:["本草纲目"],d:"服食甘菊︰《玉函方》云︰王子乔变白增年方︰用甘菊，三月上寅日采苗，名曰玉英；六月上寅日采叶，名曰容成；九月上寅日采花，名曰金精；十二月上寅日采根茎，名曰长生。四味并阴干，百日取等分，以成日合捣千杵为末，每酒服一钱匕。或以蜜丸梧子大。"},
  "菖蒲":{o:[],src:["本草纲目"],d:"服食法︰甲子日，取菖蒲一寸九节者，阴干百日，为末。每酒服方寸匕，日三服。久服耳健忘益智︰七月七日，取菖蒲为末，酒服方寸匕，饮酒不醉，好事者服而验之。"},
  "菘":{o:[],src:["本草纲目"],d:"旧一，新二。小儿赤游，行于上下，至心即死：菘菜捣敷之，即止。（张杰《子母秘录》）。 ；旧一。酒醉不醒：菘菜子二合细研，井华水一盏调，为二服。（《圣惠方》）。"},
  "菝葜":{o:[],src:["本草纲目"],d:"小便滑数︰金刚骨为末。每服三钱，温酒下，睡时。（《儒门事亲》方）取去根本︰用菝二两，为末。"},
  "菠薐":{o:[],src:["本草纲目"],d:"（新一）消渴引饮，日至一石者︰菠薐根、鸡内金等分，为末。米饮服一钱，日三。（《经验方》）。"},
  "菥蓂":{o:[],src:["本草纲目"],d:"旧一，新一。眼目热痛，泪出不止︰菥子，捣筛为末。卧时铜簪点少许入目，当有热泪及恶物出，甚佳。"},
  "菰":{o:[],src:["本草纲目"],d:"小儿风疮︰久不愈者。用菰蒋节烧研，敷之。（《子母秘录》）。"},
  "菱":{o:["菱"],src:["本草备要"],d:"\\x俗名菱角，一名芰\\x \n泻，解暑，止渴 \n甘寒。安中消暑，止渴解酒。有两角、三角、四角、老嫩之殊（《武陵记》以三角、四 \n角者为芰，两角者为菱。菱花随月而转，犹葵花之向日）。"},
  "菾菜":{o:[],src:["本草纲目"],d:"新一。痔下血︰子、芸苔子、荆芥子、芫荽子、莴苣子、蔓荆子、萝卜子、葱子等分，以大鲫鱼一个去鳞、肠，装药在内，缝合，入银、石器内，上下用火炼熟，放冷为末。每服二钱，米饮下，日二服。"},
  "萆":{o:["萆"],src:["本草备要"],d:"通，祛风湿，补下焦 \n甘苦性平。入足阳明、厥阴（胃、肝）。祛风去湿，以固下焦（阳明主肉，属湿。厥阴 \n主筋，属风），补肝虚（去风），坚筋骨（风湿去，则筋骨坚），益精明目。 \n治风寒湿痹，腰痛久冷，关节老血，膀胱宿水，阴痿失溺，茎痛遗浊，痔 恶疮（诸病 \n皆阳明湿热流入下焦，萆 能除浊厘清，古方有萆 厘清饮。史国信云∶若欲兴阳，先滋筋 \n力。若欲便清，先分肝火。《万金护命方》云∶凡人小便频数、便时痛"},
  "萎蕤":{o:[],src:["本草纲目"],d:"服食法︰二月、九月采葳蕤根，切碎一石，以水二石煮之，从旦至夕，以手烂，布囊榨取汁，熬稠。其渣晒为末，同熬至可丸，丸如鸡头子大。每服一丸，白汤下，日三服。"},
  "萤火":{o:[],src:["本草纲目"],d:"新二。黑发︰七月七日夜，取萤火虫二七枚，捻发自黑也。（《便民图纂》方）明目︰劳伤肝气目暗方︰用萤极妙。"},
  "营实、墙蘼":{o:[],src:["本草纲目"],d:"眼热昏暗︰营实、枸杞子、地肤子各二两，为末。每服三钱，温酒下。（《圣惠方》）根。 ；消渴尿多︰蔷薇根一把，水煎，日服之。（《千金方》）小便失禁︰蔷薇根煮汁饮，或为末酒服。野生白花者更良。"},
  "萱草":{o:[],src:["本草纲目"],d:"通身水肿︰鹿葱根叶，晒干为末。每服二钱，入席下尘半钱，食前米饮小便不通︰萱草根煎水频饮。（《杏林摘要》）大便后血︰萱草根和生姜，油炒，酒冲服。"},
  "落花生":{o:["落花生"],src:["本草备要"],d:"补脾润肺 \n辛能润肺，香能舒脾。果中佳品，出闽广。藤生花，落地而结实，故名（按∶落花生《 \n本草》未收，本无当医药之用，然能益脾润肺，实佳果也。因世人谤之者多，附见于此，明 \n其有利无害也）。炒食。"},
  "葈耳":{o:[],src:["本草纲目"],d:"酒服三十丸，日二服。生者捣汁服亦可。（《朱氏集验方》）葶苈（末）等分。 ；疮杖疮，牙疼喉痹︰五月五日采苍耳根叶数担，洗净晒萎细锉，以大锅五口，入水煮烂，以筛滤去粗滓，布绢再滤。复入净锅，武火煎滚，文火煎稠，搅成膏，以新罐贮封。每以敷贴，即愈。"},
  "葛":{o:[],src:["本草纲目"],d:"时气头痛壮热︰生葛根洗净，捣汁一大盏，豉一合，煎六分，去滓分服，汗出即瘥。未汗再服。若心热，加栀子仁十枚。 ；妇人吹乳︰葛蔓烧灰。酒服二钱。三服效。"},
  "葛上亭长":{o:[],src:["本草纲目"],d:"新二。经脉不通︰妇人经脉不通，症块胀满，腹有鬼胎。用葛上亭长五枚，以糙米和炒，去翅、足，研末。"},
  "葫":{o:[],src:["本草纲目"],d:"旧十五，新三十二。背疮灸法：凡觉背上肿硬疼痛，用湿纸贴寻疮头。用大蒜十颗，淡豉半合，乳香一钱，细研。"},
  "葫芦巴":{o:[],src:["本草纲目"],d:"小肠气痛︰葫芦巴（炒）研末，每服二钱，茴香酒下。（《直指方》）肾脏虚冷，腹胁胀满︰葫芦巴（炒）二两，熟附子、硫黄各七钱五分。为末，酒煮曲糊丸梧桐子大，每盐汤下三、四十丸。"},
  "葱":{o:["葱"],src:["本草备要"],d:"轻，发表和里，宣，通阳活血 \n生辛散，熟甘温（陶宏景曰∶白冷青热，伤寒汤中不得用青），外实中空，肺之菜也。 \n肺主皮毛，其合阳明（大肠）。故发汗解肌，以通上下阳气（仲景白通汤、通脉四逆汤并加 \n之，以通脉回阳），益目睛（白睛属肺），利耳鸣，通二便（时珍曰∶葱管吹盐入玉茎中，治 \n小便不通，及转脬危急者极效）。治伤寒头痛，时疾热狂，阴毒腹痛（阴证厥逆，用葱白安 \n脐上熨之）。气通则血活（气为血帅），"},
  "葱茎白":{o:[],src:["本草纲目"],d:"旧十二，新三十六。感冒风寒初起：即用葱白一握，淡豆豉半合，泡汤服之，取汗。（《濒湖集简方》）伤寒头痛如破者：连须葱白半斤，生姜二两，水煮温服。 ；旧三，新二。水病足肿：葱茎叶煮汤渍之，日三、五次妙。（韦宙《独行方》）。 ；旧二，新三。衄血不止：方见上。金疮出血不止：取葱炙热，汁涂之即止。 ；旧一。喉中肿塞，气不通者：葱须阴干为末，每用二钱，入蒲州胆矾末一钱，和匀。每用一字，吹之。 ；旧一。眼暗补中"},
  "葵":{o:[],src:["本草纲目"],d:"天行斑疮︰方见上。肉锥怪疾︰有人手足甲忽长，倒生刺肉，如锥痛不可忍者，但食葵菜即愈。（夏子益《奇疾方》）诸不合︰先以泔清温洗，拭净，取葵菜微火烘暖贴之。 ；每日平旦服二升。（《外台秘要》）漏胎下血，血尽子死︰葵根茎烧灰。酒服方寸匕，日三。 ；煮取一升服。不瘥更作。《圣惠》︰用葵子（末）、人乳汁等分。"},
  "葶苈":{o:["葶苈"],src:["本草备要", "本草纲目"],d:"大泻气秘，通，行水 \n辛苦大寒。属火性急，大能下气，行膀胱水。肿中水气 急者，非此不能除。破积聚症 \n结，伏留热气，消肿除痰，止嗽定喘（水湿泛溢，为肿胀，为痰嗽，为喘满）通经利便。久 \n服令人虚（《十剂》曰∶泄可去闭，葶苈、大黄之属是也。大黄泄阴分血闭，葶苈泄阳分气 \n闭，气味俱浓，不减大黄。然有甜、苦二种，甜者性缓，苦者性急，泄肺而伤胃，宜大枣辅 \n之。仲景有葶苈大枣泻肺汤，治肺气喘急不得卧。昂"},
  "蒜":{o:[],src:["本草纲目"],d:"旧七，新七。时气温病，初得头痛，壮热脉大：即以小蒜一升，杵汁三合，顿服。不过再作便愈。"},
  "蒟酱":{o:[],src:["本草纲目"],d:"牙疼︰酱、细辛各半两，大皂荚五铤（去子，每孔入青盐烧存性）。同研末。频掺吐涎。"},
  "蒴藋":{o:[],src:["本草纲目"],d:"手足偏风︰蒴叶，火燎，浓铺床上，趁热眠于上，冷复易之。冬月取根，舂碎熬热用。（《外台秘要》）风湿冷痹︰方同上。"},
  "蒺藜":{o:[],src:["本草纲目"],d:"服食法︰蒺藜子一石（七、八月熟时收取）。日干，舂去刺，杵为末。每服二钱，新汲水调下，日三服，勿令中绝，断谷长生。 ；鼻流清涕︰蒺藜苗二握，黄连二两，水五升，煎一升，少少灌鼻中取嚏，不过再灌。（《圣济录》）诸疮肿毒︰蒺藜蔓洗，三寸截之，取得一斗。以水五升，煮取二升，去滓，纳铜器中，又煮取一升，纳小器中，煮如饴状，以涂肿处。"},
  "蓄":{o:[],src:["本草纲目"],d:"热淋涩痛︰扁竹煎汤频饮。（《生生编》）热黄胆疾︰扁竹捣汁，顿服一升。多年者，日再服之。"},
  "蓍":{o:[],src:["本草纲目"],d:"腹中痞块︰蓍叶、独蒜、穿山甲（末）、食盐。同以好醋捣成饼，量痞大小贴之，两炷香为度。其痞化为脓血，从大便出。"},
  "蓖麻":{o:[],src:["本草纲目"],d:"半身不遂，失音不语︰取蓖麻子油一升，酒一斗，铜锅盛油，著酒中一日，煮之令熟。细细服之。（《外台秘要》）口目斜︰蓖麻子仁捣膏，左贴右，右贴左，即正。 ；喘痰嗽︰《儒门事亲》方︰用九尖蓖麻叶三钱，入飞过白矾二钱。以猪肉四两薄批，掺药在内，荷叶裹之，文武火煨熟。细嚼，以白汤送下。"},
  "蓖麻子":{o:["蓖麻子"],src:["本草备要"],d:"泻，通窍，拔毒，出有形滞物 \n辛苦有毒。性善收，亦善走，能开通诸窍、经络。 \n治偏风不遂， 斜（捣饼。左贴右，右贴左，即止）口噤，鼻窒耳聋（捣烂绵裹，塞耳 \n塞鼻），喉痹舌胀（油作纸，燃烟熏）。能利水气，治水症浮肿（研服。当下青黄水，壮人只 \n可五粒）能出有形滞物。治针刺入肉（捣敷伤处，频看，刺出即去药，恐努出好肉），竹木 \n骨哽（蓖麻子一两，凝水石二两，研匀。以一捻置舌根，噙咽，自然不见），胞胎"},
  "蓝淀":{o:[],src:["本草纲目"],d:"时行热毒，心神烦躁︰用蓝淀一匙。新汲水一盏服。（《圣惠方》）小儿热丹︰蓝淀，敷之。"},
  "蓬莪荗":{o:[],src:["本草纲目"],d:"一切冷气，抢心切痛，发即欲死。久患心腹痛时发者，此可绝根。蓬莪术二两（醋煮），木香一两（煨）。"},
  "蓬蘽":{o:[],src:["本草纲目"],d:"阳事不起：覆盆子酒浸焙研为末，每旦久服三钱（集简方）叶。 ；牙疼点眼︰用复盆子嫩叶捣汁，点目三、四次，有虫随眵泪出成块也。无新叶，干者煎浓汁亦可。即大麦莓也。"},
  "蓼":{o:[],src:["本草纲目"],d:"伤寒劳复，因交后卵肿，或缩入腹痛︰蓼子一把。水汁，饮一升。（《肘后方》）霍乱烦渴︰蓼子一两，香薷二两。 ；蓼汁酒，治胃脘冷，不能饮食，耳目不聪明，四肢有气，冬卧足冷︰八月三日取蓼日干，如五升大，六十把，水六石，煮取一石，去滓，拌米饭，如造酒法，待熟，日饮之。十日后，目明气壮也。（《千金方》）肝虚转筋吐泻︰赤蓼茎叶（切）三合。"},
  "蓼实":{o:["蓼实"],src:["本草备要"],d:"宣，温中 \n辛温。温中明目，耐风寒，下水气（时珍曰∶古人种蓼为蔬，收子入药，今为酒曲用其 \n汁耳。以香蓼、青蓼、紫蓼为良）。 \n有香蓼、青蓼、紫蓼、赤蓼、木蓼、水蓼、马蓼。"},
  "蔓菁子":{o:["蔓菁子"],src:["本草备要"],d:"\\x即芜菁\\x \n泻热，利水，明目 \n苦辛。泻热解毒，利水明目（古方治目，用之最多）。治黄胆（捣服）腹胀（捣研滤汁 \n饮，或吐或利，腹中自宽，得汗愈），症瘕积聚，小儿血痢（蜜和汁服），一切疮疽（凡痈疽 \n捣敷皆良。醋调敷秃疮，盐捣敷乳痈。冬取根用），敷蜘蛛咬毒（陈藏器曰∶蔓菁园中无蜘 \n蛛。李时珍曰∶蔓菁子可升可降，能汗能吐能下，能利小便，明目解毒，其功甚伟，世罕知 \n用，何哉？）。根，捣敷阴囊肿"},
  "蔷薇根":{o:["蔷薇根"],src:["本草备要"],d:"泻湿热 \n苦涩而冷。入胃、大肠经。除风热、湿热，生肌杀虫。 \n治泄痢消渴，牙痛口糜（煎汁含漱），遗尿好眠，痈疽疮癣。 \n花有黄、白、红、紫数色，以黄心、白色、粉红者入药。 \n子，名营实，酸温。主治略同（《千金》曰∶蔷薇根，角蒿，口疮之神药。角蒿所在多 \n有，开淡红紫花，角微弯，长二寸许，辛苦有小毒。治恶疮有虫，及口齿疮）。"},
  "蕤仁":{o:["蕤仁"],src:["本草备要"],d:"\\x亦名白 \\x \n补，明目 \n甘温（《别录》微寒）。入心、肝、脾三经。消风散热，益水生光（三经皆血脏也。血得 \n其养，则目疾平。凡目病在表，当疏风清热。在里属肾虚、血少、神劳，宜补肾养血安神。 \n远视为肾水亏，近视为火不足）。 \n治目赤肿痛， 烂泪出，亦治心腹邪热，结气痰痞（今人惟用疗眼。陈藏器曰∶生治足 \n睡，熟治不眠）。丛生有刺，实如五味，圆扁有纹，紫赤可食。取仁浸，去皮、尖，研用。"},
  "蕨":{o:[],src:["本草纲目"],d:"新一。肠风热毒︰蕨菜花焙，为末。每服二钱，米饮下。"},
  "蕺菜":{o:[],src:["本草纲目"],d:"旧一，新七。背疮热肿︰蕺菜捣汁涂之，留孔以泄热毒，冷即易之。（《经验方》）。"},
  "薇衔":{o:[],src:["本草纲目"],d:"年深恶疮︰无心草根、钓苓根、野狼毒、白丁香各五钱，麝香一字，为末掺之。又方︰无心小儿破伤风病，拘急口噤︰没心草半两，白附子（炮）二钱半，为末。每服一字，薄荷酒灌下。"},
  "薤":{o:["薤"],src:["本草备要", "本草纲目"],d:"\\x一名 子， 音叫\\x \n滑，利窍，助阳 \n辛苦滑温。调中助阳，散血生肌，泄下焦大肠气滞。治泄痢下重（王好古曰∶下重者， \n气滞也，四逆散加此以泄滞。按∶下重亦有气虚、血虚、火热、风燥之不同），胸痹刺痛（仲 \n景用栝蒌薤白白酒汤），肺气喘急。安胎利产，涂汤、火伤（和蜜捣用。《肘后方》∶中恶卒 \n死者，用薤汁灌鼻中，韭汁亦可）。叶似韭而中空，根如蒜。取白用。忌牛肉（其叶光滑， \n露亦难贮，故云薤露"},
  "薯蓣":{o:[],src:["本草纲目"],d:"旧一，新十。补益虚损，益颜色，补下焦虚冷，小便频数，瘦损无力︰用薯蓣于沙盆中研细，入铫中，以酥一大匙熬令香，旋添酒一盏煎搅令匀，空心饮之。每旦一服。"},
  "薰草":{o:[],src:["本草纲目"],d:"伤寒下痢︰蕙草汤︰用蕙草、当归各二两，黄连四两，水六升，煮二升服，日三服。（《范汪方》）伤寒狐惑，食肛者。蕙草、黄连各四两。"},
  "藕":{o:["藕"],src:["本草备要"],d:"凉血散瘀 \n涩平。解热毒，消瘀血，止吐、衄、淋、痢一切血证（和生地汁、童便服良）。藕生甘 \n寒，凉血散瘀（宋大官作血 ，误落藕皮，血遂涣散不凝。一人病血淋，痛胀欲死，李时珍 \n以发灰二钱，藕汁调服，三日而愈。《梅师方》∶产后余血上冲，煮汁服），止渴除烦（《圣惠 \n方》∶藕汁，蜜和服，治时气烦渴），解酒毒、蟹毒（捣烂，热酒调服）。煮熟甘温，益胃补 \n心（多孔象心），止泻（能实大肠）止怒，久服令人欢（"},
  "藜":{o:[],src:["本草纲目"],d:"新一。白癜风︰红灰五斤，茄子根、茎三斤，苍耳根、茎五斤，并晒干烧灰，以水一斗煎汤淋汁熬成膏，别以好乳香半两，铅霜一分，腻粉一分，炼成牛脂二两，和匀，每日涂三次。（《圣惠》）茎。"},
  "藜芦":{o:["藜芦"],src:["本草备要", "本草纲目"],d:"宣，引吐 \n辛寒至苦，有毒。 \n入口即吐，善通顶，令人嚏，风痫证多用之（张子和曰∶一妇病风痫，初一、二年一作 \n，后渐日作，甚至一日数作，求死而已。值岁大饥，采百草食，见野草若葱，采蒸饱食，觉 \n不安，吐胶涎数日，约一二斗，汗出如洗，甚昏困，后遂轻健如常人。以所食葱访人，乃憨 \n葱苗，即藜芦是矣。时珍曰∶和王妃年七十，中风不省，牙关紧闭。先考太医吏目月池翁诊 \n视，药不得入。不获已，打去一齿，浓煎"},
  "藿香":{o:["藿香"],src:["本草备要", "本草纲目"],d:"宣，去恶气 \n辛甘微温。入手足太阴（肺、脾）。快气和中，开胃止呕（胃弱、胃热而呕者忌用），去 \n恶气，进饮食。 \n治霍乱吐泻，心腹绞痛，肺虚有寒，上焦壅热（能理脾、肺之气。古方有藿香正气散， \n正气通畅，则邪逆自除）。 \n出交广，方茎有节，叶微似茄汁。古惟用叶，今枝、茎亦用之，因叶多伪也。"},
  "蘘荷":{o:[],src:["本草纲目"],d:"密置病患席下，勿令知之，必自呼蛊主姓名也。（《梅师方》）取白荷根捣汁服，蛊立出也。（《梅师方》）喉舌疮烂︰酒渍荷根半日，含漱其汁，瘥乃止。"},
  "蘩缕":{o:[],src:["本草纲目"],d:"旧二，新二。食治乌髭︰繁缕为齑，久久食之，能乌髭发。（《圣惠方》）。"},
  "虎掌":{o:[],src:["本草纲目"],d:"中风口噤目瞑，无门下药者︰开关散︰用天南星为末，入白龙脑等分，五月五日午时合之。每用中指点末，揩齿诸风口噤︰天南星（炮锉）大人三钱、小儿三字，生姜五片，苏叶一钱，水煎减半，入雄猪胆汁少许，温服。（《仁斋直指方》）纸裹斜包，剪一小孔，透气于口中，牙关自开也。"},
  "虎骨":{o:["虎骨"],src:["本草备要"],d:"宣，去风，健骨 \n味辛微热。虎属金而制木，故啸则风生。追风健骨，定痛辟邪。治风痹拘挛疼痛，惊悸 \n颠痫，犬咬骨哽（为末，水服，犬咬敷患处）。以头骨、胫骨良（虎虽死，犹立不仆，其气 \n力皆在前胫。时珍曰∶凡辟邪疰，治惊痫，瘟疟、头风，当用头骨。治手足风，当用胫骨。 \n治腰脊风，当用脊骨，各从其类也）。 \n虎肚，治反胃（取生者，存滓秽勿洗，新瓦固 存性，为末。入平胃散一两，每服三钱 \n，效。昂按∶虎肚"},
  "虫白蜡":{o:[],src:["本草纲目"],d:"新一。头上秃疮︰蜡烛频涂，勿令日晒，久则自然生发。（《集玄方》）。"},
  "虾":{o:["虾"],src:["本草备要"],d:"补阳 \n甘温。托痘疮。下浮汁，吐风痰（中风症，以虾半斤，入姜、葱、酱料水煮，先吃虾， \n次吃汁，以鹅翎探引，吐出痰涎，随证用药），壮阳道。"},
  "蚕":{o:[],src:["本草纲目"],d:"旧十五，新十九。一切风痰︰白僵蚕七个（直者），细研，姜汁一茶脚，温水调灌之。（《胜金方》）小儿惊风︰白僵蚕、蝎梢等分，天雄尖、附子尖共一钱。"},
  "蚕茧（含蚕蜕、蚕连）":{o:[],src:["本草纲目"],d:"新五。痘疮疳蚀脓水不绝︰用出了蚕蛾茧，以生白矾末填满。枯为末，擦之甚效。 ；旧四，新十五。吐血不止︰蚕蜕纸烧存性，蜜和，丸如芡实大。含化咽津。"},
  "蚤休":{o:[],src:["本草纲目"],d:"布袋中，悬风处待干。每服三丸，五更初面东念咒，井水下。连进三服，即能休粮。"},
  "蚯蚓":{o:[],src:["本草纲目"],d:"旧九，新三十四。伤寒热结︰六、七日狂乱，见鬼欲走。以大蚓半斤去泥，用人溺煮汁饮。"},
  "蚱蝉":{o:[],src:["本草纲目"],d:"新三。百日发惊︰蚱蝉（去翅、足，炙）三分，赤芍药三分，黄芩二分，水二盏，煎一盏，温服。（《圣惠方》）。"},
  "蚺蛇":{o:[],src:["本草纲目"],d:"旧二，新二。小儿急疳疮︰水调蚺蛇胆，敷之。（《圣惠》）小儿疳痢︰羸瘦多睡，坐则闭目，食不下。 ；新三。蚺蛇酒︰治诸风瘫痪，筋挛骨痛，痹木瘙痒，杀虫辟瘴，及疠风疥癣恶疮。用蚺蛇肉一斤，羌活一两，绢袋盛之，用糯米二斗蒸熟，安曲于缸底，置蛇于曲上，乃下饭密盖，待熟取酒。"},
  "蚺蛇胆":{o:["蚺蛇胆"],src:["本草备要"],d:"泻热、明目、护心 \n蚺（音髯）禀己土之气，胆属甲乙风木，气寒有小毒，其味苦而带甘。凉血明目，疗疳 \n杀虫，主厥阴、太阴（肝木、脾土）之病。 \n肉，极腴美，主治略同。 \n取胆粟许，置水上，旋行极速者真（胆上旬近头，中旬近心，下旬近尾。能护心止痛， \n受杖时噙之，杖多不死）。"},
  "蛆":{o:[],src:["本草纲目"],d:"新十。一切疳疾︰《圣济总录》︰六月取粪坑中蛆淘净，入竹筒中封之，待干研末。每服一、二钱，入麝香，米饮服之。"},
  "蛇含":{o:[],src:["本草纲目"],d:"产后泻痢︰小龙牙根一握，浓煎服之甚效，即蛇含是也。（《斗门方》）金疮出血︰蛇含草捣敷之。（《肘后方》）身面恶癣︰紫背草，入生矾研。"},
  "蛇床":{o:[],src:["本草纲目"],d:"阳事不起︰蛇床子、五味子、菟丝子等分，为末，蜜丸梧子大。每服三十丸，温酒下，日三服。（《千金方》）赤白带下，月水不来。"},
  "蛇蜕":{o:["蛇蜕"],src:["本草备要", "本草纲目"],d:"轻，宣，去风毒 \n甘咸无毒（甄权∶有毒）。性灵而能辟恶，故治鬼魅蛊毒；性窜而善去风，故治惊痫风 \n疟，重舌（《圣惠方》∶烧末敷）喉风；性毒而能杀虫，故治疥癣恶疮，疔肿痔漏；属皮而性 \n善蜕，故治皮肤疮疡，产难目翳。用白色如银者，皂荚水洗净。或酒、或醋、或蜜浸，炙 \n黄用，或烧存性，或盐泥固 ，各随本方。"},
  "蛇黄":{o:[],src:["本草纲目"],d:"暗风痫疾︰忽然仆地，不知人事，良久方醒。蛇黄，火醋淬七次，为末。每调酒服二钱，数服愈。"},
  "蛔虫":{o:[],src:["本草纲目"],d:"新三。玉箸煎︰治小儿胎赤眼、风赤眼。用小儿吐出蛔虫二条，瓷盒盛之，纸封埋湿地，五日取出，化为水，瓷瓶收。"},
  "蛙":{o:[],src:["本草纲目"],d:"新六。蛤馔︰治水肿。用活蛙三个，每个口内安铜钱一个，上著胡黄连末少许。"},
  "蛞蝓":{o:[],src:["本草纲目"],d:"新一。脚胫烂疮︰臭秽不可近。用蜒蚰十条，瓦焙研末，油调敷之，立效。"},
  "蛤粉":{o:["蛤粉"],src:["本草备要"],d:"涩 \n蛤蜊壳 为粉。与牡蛎同功（海藏曰∶肾经血分药。宋徽宗宠妃病痰嗽，面肿不寐，李 \n防御治之，三日不效，当诛，李技穷忧泣，忽闻市人卖嗽药，一文一帖，吃了今夜得睡，色 \n淡碧，李市之。恐药猛悍，先自试，觉无害，共并三帖为一以进，妃服之，是夕寝安嗽止， \n面肿亦消。帝大悦，赐直万金。李不知其方，惧得罪。伺得市人，重价求之，乃蚌壳研粉， \n少加青黛也。以淡荠水，加麻油数滴，调服。《圣惠方》∶白蚬壳研粉"},
  "蛤蟆":{o:[],src:["本草纲目"],d:"旧三，新三。风邪为病︰蛤蟆（烧灰）、朱砂等分，为末。每服一钱，水调下，日三四服，甚有神验。"},
  "蛴螬":{o:[],src:["本草纲目"],d:"旧五，新四。小儿脐疮︰蛴螬研末敷之，不过数次。（《千金方》）小儿唇紧︰蛴螬研末，猪脂和，敷之。"},
  "蜀羊泉":{o:[],src:["本草纲目"],d:"黄胆疾︰漆草一把，捣汁和酒服。不过三、五次，即愈。（《摘玄方》）。"},
  "蜀葵":{o:[],src:["本草纲目"],d:"二、三日则杀人︰蜀葵花一两（捣烂），麝香半钱。水一大盏，煎服。根亦可用。 ；大小便闭不通者︰用白花胡葵子为末，煮浓汁服之。（《千金方》）石淋破血︰五月五日，收葵子炒研，食前温酒下一钱，当下石出。（《圣惠方》）痈肿无头︰蜀葵子为末，水调敷之。"},
  "蜗牛":{o:[],src:["本草纲目"],d:"旧三，新二十。小便不通︰蜗牛，捣贴脐下，以手摩之。加麝香少许更妙。 ；旧二，新一。一切疳疾︰用自死蜗壳七枚（皮薄，色黄白者）洗净，不得少有尘滓，日干，内酥蜜于壳中。以瓷盏盛之，纸糊盏面，置炊饭上蒸之。"},
  "蜘蛛":{o:[],src:["本草纲目"],d:"旧七，新十五。中风口︰向火取蜘蛛摩偏急颊车上，候正即止。（《千金方》）小儿口噤︰《直指》立圣散︰用干蜘蛛一枚（去足，竹沥浸一宿，炙焦），蝎梢七个，腻粉少许。 ；旧一，新一。虫牙有孔︰蜘蛛壳一枚，绵裹塞之。（《备急》）牙疳出血︰蜘蛛壳，为末，入胭脂、麝香少许，敷之。 ；新四。积年诸疮︰蜘蛛膜贴之，数易。（《千金方》）反花疮疾︰同上。"},
  "蜚虻":{o:[],src:["本草纲目"],d:"旧二，新一。蛇螫血出，九窍皆有者病笃去胎︰虻虫十枚，炙，捣为末。酒服，胎即下。"},
  "蜜蜂":{o:[],src:["本草纲目"],d:"新一。大风疠疾，须眉堕落，皮肉已烂成疮者︰用蜜蜂子、胡蜂子、黄蜂子（并炒）各一分，白花蛇、乌蛇（并酒浸，去皮、骨，炙干）、全蝎（去土，炒）、白僵蚕（炒）各一两，地龙（去土，炒）半两，蝎虎（全者，炒）、赤足蜈蚣（全者，炒）各十五枚，丹砂一两，雄黄（醋熬）一分，龙脑半钱，上为末。每服一钱匕，温蜜汤调下，日三五服。"},
  "蜜蜡":{o:[],src:["本草纲目"],d:"旧十一，新十。仲景调气饮︰治赤白痢，少腹痛不可忍，下重，或面青手足俱变者。用黄蜡三钱，阿胶三钱，同熔化，入黄连末《千金》胶蜡汤︰治热痢，及妇人产后下痢。"},
  "蜣螂":{o:[],src:["本草纲目"],d:"旧七，新十七。小儿惊风︰不拘急慢。用蜣螂一枚杵烂，以水一小盏，于百沸汤中荡热，去滓饮之。"},
  "蝎":{o:["蝎"],src:["本草备要", "本草纲目"],d:"宣，去风 \n辛甘有毒。色青属木，故治诸风眩掉（皆属肝木），惊痫搐掣，口眼 斜（白附、僵蚕、 \n全蝎等分为末，名牵正散。酒服二钱，甚效），疟疾风疮，耳聋带疝，厥阴风木之病（东垣 \n曰∶凡疝气带下，皆属于风。蝎乃治风要药，俱宜加而用之。汪机曰∶破伤风，宜以全蝎、 \n防风为主）。类中风、慢脾惊属虚者忌用。全用去足，焙，或用尾，尾力尤紧。形紧小者良 \n（人被螫者，涂蜗牛即解）。"},
  "蝮蛇":{o:[],src:["本草纲目"],d:"旧一。白癞︰大蝮蛇一条，勿令伤，以酒一斗渍之，糠火温令稍热。取蛇一寸，和腊月猪脂捣敷。"},
  "蝼蛄":{o:[],src:["本草纲目"],d:"旧四，新二十。十种水病︰肿满喘促不得卧。《圣惠方》︰以蝼蛄五枚，焙干为末。"},
  "螳螂、桑螵蛸":{o:[],src:["本草纲目"],d:"新二。惊风定搐︰中分散︰用螳螂一个，蜥蜴一条，赤足蜈蚣一条，各中分之，随左右研末。记定男用左，女用右。 ；旧三，新七。遗精白浊下。（《外台小便不通︰桑螵蛸（炙黄）三十枚，黄芩二两，水煎。"},
  "螺厣草":{o:[],src:["本草纲目"],d:"吐血衄血︰镜面草水洗，擂酒服。（《朱氏集验方》）。牙齿虫痛︰《乾坤生意》︰用镜面草不拘多少，以水缸下泥同捣成膏，入香油二、三点，研匀。"},
  "蟅虫":{o:[],src:["本草纲目"],d:"新七。下瘀血汤︰治产妇腹痛有干血。用虫二十枚（熬，去足），桃仁二十枚，大黄二两，为末，炼蜜杵和，分为四丸。"},
  "蟹":{o:["蟹"],src:["本草备要"],d:"泻，散血 \n咸寒。除热解结，散血通经，续筋骨（筋绝伤者，取蟹黄、足髓，熬纳疮中，筋即续生 \n。骨节脱离者，生捣，热酒调服，渣涂半日，骨内谷谷有声即好），涂漆疮（能败漆）。然寒 \n胃动风。 \n蟹爪堕胎（产难及子死腹中者，服蟹爪汤即出。其螯烧烟，能集鼠于庭。中蟹毒者，捣 \n藕节，热酒调服。腌蟹，中入蒜则不沙）。"},
  "蟾蜍":{o:["蟾蜍"],src:["本草备要", "本草纲目"],d:"\\x即癞虾蟆\\x \n泻，疗疳，拔毒 \n蟾，土精而应月魄，辛凉微毒，入阳明胃。发汗退热，除湿杀虫，治疮疽发背（未成者 \n，用活蟾蜍系疮上。半日，蟾必昏愦，置水中救其命。再易一个，三易则毒散矣。势重者， \n剖蟾蜍合疮上，不久必臭不可闻，如此二三易，其肿自愈），小儿劳瘦疳疾。 \n蟾酥，辛温大毒。助阳气，治疔肿发背，小儿疳疾脑疳（即蟾蜍眉间白汁，能烂人肌肉 \n，惟疔疳或合他药服一二厘，取其以毒攻毒。脑疳乳"},
  "蠡实":{o:[],src:["本草纲目"],d:"诸冷极病，医所不治者︰马蔺子九升洗净，空腹服一合，酒下，日三服寒疝诸疾，寒疝不能食，及腹内一切诸疾，消食肥肌。马蔺子一升，每日取一把，以面拌煮吞之，服尽愈。（姚僧坦《集验方》）喉痹肿痛︰《卫生易简方》︰用蠡实一合，升麻五分，水一升，煎三合，入少蜜搅匀，细呷，大验。 ；睡死不寤︰蠡实根一握，杵烂，以水绞汁，稍稍灌之。（《外台秘要》）喉痹口噤︰马蔺花二两，蔓荆子一两，为末，温水服一钱。喉痹肿痛，喘息欲"},
  "血竭":{o:["血竭"],src:["本草备要"],d:"补，和血，敛疮 \n甘咸。色赤入血分。补心包、肝血不足，专除血痛，散瘀生新，为和血之圣药。治内伤 \n血聚，金疮折跌，疮口不合，止痛生肌。性急，不可多使，引脓（血竭单入血分、乳香、没 \n药兼入气分，皆木脂也）。出南番。色赤，以染透指甲者为真（假者是海母血，味大咸，有 \n腥气）。单碾用（同众药捣，则作尘飞）。"},
  "衣鱼":{o:[],src:["本草纲目"],d:"旧五，新七。小儿胎寒，腹痛汗出︰用衣中白鱼二七枚，绢包，于儿腹上回转摩之，以愈为度。（《圣惠小儿撮口︰壁鱼儿研末。"},
  "西瓜":{o:["西瓜"],src:["本草备要"],d:"泻暑 \n甘寒。解暑除烦，利便醒酒，名天生白虎汤（西瓜、甜瓜，皆属生冷，多食伤脾助湿。 \n《卫生歌》云∶瓜、桃生冷宜少食，免致成疟痢。瓜性寒，曝之尤寒。《稽食赋》云∶ \n瓜、曝则寒，油煎则冷，物性之异也）。"},
  "见肿消":{o:[],src:["本草纲目"],d:"一切肿毒及伤寒遗毒，发于耳之前后，及项下肿硬︰用见肿消草、生白芨、生白蔹、土大黄、生大蓟根、野苧麻根捣成饼，入芒硝一钱，和贴留头，干即易之。若加金线重楼及山慈菇尤妙。（《伤寒蕴要》）。"},
  "角蒿":{o:[],src:["本草纲目"],d:"齿龈宣露，多是疳也。角蒿烧灰，夜涂上。切忌油腻、沙糖、干枣。"},
  "解毒子":{o:[],src:["本草纲目"],d:"眉棱骨痛，热毒攻眼，头痛眉痛，壮热不止︰解毒子、木香、川大黄各三分，为末，浆水调膏摊贴，干即易之。（《普济方》）。"},
  "诸铁器":{o:[],src:["本草纲目"],d:"喉痹肿痛︰菖蒲根嚼汁，烧秤锤淬一杯，饮之。（《普济方》）舌肿咽痛，咽生息肉，舌肿。秤锤烧赤，淬醋一盏，咽之。 ；眼生偷针︰布针一个，对井睨视，已而折为两段，投井中，勿令人见。（张杲《医说》）。 ；小儿伤寒，百日内患壮热。用铁铧一斤，烧赤，水二斗，淬三七次，煎一半，入柳叶七片，浴之。（《圣济录》）积年齿︰旧铁铧头一枚，炭火烧赤，捻硫黄一分，猪脂一分，于上熬沸。 ；小儿下血︰方见上。妊娠咳嗽︰车缸一枚"},
  "谷精草":{o:["谷精草"],src:["本草备要", "本草纲目"],d:"轻，明目 \n辛温轻浮。上行阳明（胃），兼入厥阴（肝）。明目退翳之功在菊花之上。亦治喉痹齿痛， \n阳明风热。 \n收谷后，荒田中生。叶似嫩秧，花如白星（小儿雀盲者，羯羊肝一具，不洗，竹刀割开 \n，入谷精煮熟食之。或作丸，茶下）。"},
  "谷芽":{o:["谷芽"],src:["本草备要"],d:"健脾消食 \n甘温。开胃快脾，下气和中，消食化积。炒用。"},
  "豆蔻":{o:[],src:["本草纲目"],d:"心腹胀满短气。用草豆蔻一两，去皮为末，以木瓜生姜汤，调服半钱。（《千金方》）胃弱呕逆不食。"},
  "象皮":{o:["象皮"],src:["本草备要"],d:"外用，敛金疮 \n象肉壅肿，以刀刺之，半日即合。治金疮不合者，用其皮灰，亦可以熬膏入散。 \n象胆亦能辟尘，与熊胆同功。"},
  "豨莶":{o:[],src:["本草纲目"],d:"风寒泄泻︰火丸︰治风气行于肠胃，泄泻。火草为末，醋糊丸梧子大。每服三十丸，白汤下。"},
  "贝母":{o:["贝母"],src:["本草备要", "本草纲目"],d:"宣，散结，泻热，润肺，清火 \n微寒，苦泻心火，辛散肺郁（入肺经气分，心火降则肺气宁。《诗》曰∶言采其虻。虻 \n即贝母也。取其解郁）。润心肺，清虚痰。 \n治虚劳烦热，咳嗽上气，吐血咯血，肺痿肺痈，喉痹（君相之火）目眩（火热上攻）， \n淋沥（小肠邪热，心与小肠相表里，肺为气化之源）瘿瘤（化痰），乳闭产难。功专散结除 \n热，敷恶疮（唐时有人膊上生疮如人面，能饮酒食物，亦无他苦。遍投诸药悉受之，至贝母。 "},
  "败瓢":{o:[],src:["本草纲目"],d:"新六。中满鼓胀︰用三、五年陈壶卢瓢一个，以糯米一斗作酒，待熟，以瓢于炭火上炙热，入酒浸之，如此三、五次，将瓢烧存性，研末。每服三钱，酒下，神效。"},
  "败酱":{o:[],src:["本草纲目"],d:"肠痈有脓︰薏苡仁附子败酱散︰用薏苡仁十分，附子二分，败酱五分。捣为末。每以方寸匕，水二升，煎一升，顿服。"},
  "贯众":{o:["贯众"],src:["本草备要", "本草纲目"],d:"泻热，解毒 \n味苦微寒，有毒，而能解邪热之毒。 \n治崩中带下，产后血气胀痛，破症瘕，发斑痘（王海藏快斑散用之），化骨哽（能软坚）， \n杀三虫。 \n根似狗脊而大。汁能制三黄，化五金，伏钟乳、结砂、制汞，解毒软坚（以此浸水缸中 \n，日饮其水，能辟时疾）。"},
  "赤地利":{o:[],src:["本草纲目"],d:"产后烦渴，血气上冲也︰紫葛三两。水二升，煎一升，去滓呷之。金疮伤损，生肌破血︰用紫葛二两。"},
  "赤柽柳":{o:["赤柽柳"],src:["本草备要"],d:"\\x一名西河柳\\x \n宣，解毒 \n能使疹毒外出。末服四钱，治痧疹不出，喘嗽闷乱。沙糖调服，治疹后痢。"},
  "赤箭":{o:[],src:["本草纲目"],d:"天麻丸︰消风化痰，清利头目，宽胸利膈。治心忪烦闷，头晕欲倒，项急，肩背拘倦，神二两。为末，炼蜜丸如芡子大。 ；益气固精︰补血，黑发，益寿，有奇效。还筒子半两，芡实半两，金银花二两，破故纸（酒浸，春三、夏一、秋二，冬五日，焙，研末）二两。各研末，蜜糊丸梧子大。"},
  "赤铜屑":{o:[],src:["本草纲目"],d:"腋下狐臭︰崔氏方︰用清水洗净，又用清酢浆洗净，微揩破，取铜屑和酢热揩之，甚验。（《外台》）。"},
  "车前":{o:[],src:["本草纲目"],d:"小便血淋作痛︰车前子晒干为末，每服二钱，车前叶煎汤下。（《普济方》）石淋作痛︰车前子二升，以绢袋盛，水八升，煮取三升，服之，须臾石下。（《肘后方》）。 ；小便不通︰车前草一斤，水三升，煎取一升半，分三服。一方︰入冬瓜汁。一方︰入桑叶汁。"},
  "轻粉":{o:["轻粉"],src:["本草备要"],d:"燥，劫痰涎，外用杀虫 \n辛冷（时珍曰∶燥有毒）。杀虫治疮，劫痰消积（能消涎积。十枣汤加大黄、牵牛、轻 \n粉，名三化神 散），善入经络，螈 药多用之。不可过服常用（时珍曰∶水银阴毒，用火 \n丹砂而出。再加盐、矾，炼为轻粉。轻扬燥烈，走而不守，今人用治杨梅毒疮。虽能劫风 \n痰湿热从牙龈出，邪郁暂解，然毒瓦斯窜入经络，筋骨血液耗亡，筋失所养，变为筋挛骨痛。 \n痈肿疳漏，遂成废痼，贻害无穷。上下齿龈，属手"},
  "逆流回澜水":{o:["逆流回澜水"],src:["本草备要"],d:"宣 \n性逆而倒上，中风、卒厥宣痰饮之药宜之。"},
  "通脱木":{o:[],src:["本草纲目"],d:"洗头风痛︰新通草瓦上烧存性，研末二钱，热酒下。牙关紧者，斡口灌之。（王《百一花上粉。"},
  "酒":{o:["酒"],src:["本草备要"],d:"宣，行药势 \n辛者能散，苦者能降，甘者居中而缓，浓者热而毒，淡者利小便。用为响导，可以通行 \n一身之表，引药至极高之分。热饮伤肺，温饮和中。少饮则和血行气，壮神御寒，遣兴消愁 \n，辟邪逐秽，暖水藏，行药势。过饮则伤神耗血（亦能乱血，故饮之身面俱赤），损胃灼精， \n动火生痰，发怒助欲（酒是色媒人），致生湿热诸病（过饮则相火昌炎，肺金受灼，致生痰 \n嗽。脾因火而困怠，胃因火而呕吐，心因火而昏狂，肝因火"},
  "酢浆草":{o:[],src:["本草纲目"],d:"小便血淋︰酸草捣汁，煎五苓散服之。俗名醋啾啾是也。（王璆《百一选方》）。"},
  "酸模":{o:[],src:["本草纲目"],d:"瘭疽毒疮，肉中忽生黯子如粟豆，大者如梅李，或赤或黑，或青或白，其中有核，核有深根，应心。肿泡紫黑色，能烂筋骨，毒入脏腑杀人︰宜灸黯上百壮。以酸模叶薄其四面，防其长也。"},
  "酸浆":{o:[],src:["本草纲目"],d:"热咳咽痛灯笼草为末，白汤服，名清心丸。仍以醋调敷喉外。（《丹溪纂要》）痛︰灯笼草，炒焦研末，酒调呷之。 ；马蔺子（炒）、大盐梧子大。每服三十丸，木香汤下。（《圣济总录》）天泡湿疮︰天泡草铃儿生捣敷之。"},
  "醋":{o:["醋"],src:["本草备要"],d:"\\x一名苦酒\\x \n散瘀，敛气，消痈肿 \n酸温。散瘀解毒，下气消食（食敛缩则消矣），开胃气（令人嗜食，《本草》未载），散 \n水气。治心腹血气痛（磨木香服），产后血晕（以火淬醋，使闻其气），症结痰癖，疸黄痈肿 \n（外科敷药多用之，取其敛壅热、散瘀解毒。昂按∶贝母性散而敛疮口，盖能散，所以能敛。 \n醋性酸收而散痈肿，盖消则内散，溃则外散，收处即是散处，两者一义也）口舌生疮（含漱）， \n损伤积血（面和，"},
  "醍醐菜":{o:[],src:["本草纲目"],d:"旧一。伤中崩赤︰醍醐杵汁，拌酒煎沸，空心服一盏。（《千金方》）。"},
  "野狼毒":{o:[],src:["本草纲目"],d:"心腹连痛作胀︰用野狼毒二两附子半两，捣筛，蜜丸梧子大。一日服一丸，二日二丸，三日三丸，止；又从一丸起，至三丸止，以瘥为度。（《肘后方》）九种心痛，一虫，二蛀，三风，四悸，五食，六饮，七冷，八热，九气也。"},
  "野狼牙":{o:[],src:["本草纲目"],d:"金疮出血︰野狼牙草茎叶，熟捣贴之。（《肘后方》）小便溺血︰金粟野狼牙草（焙干，入蚌粉炒）、槐花、百药煎等分。为末。"},
  "野菊":{o:[],src:["本草纲目"],d:"瘰&#30311;未破︰野菊花根捣烂，煎酒服，以渣敷之。自消，不消亦自破也。（《瑞竹堂经验方。"},
  "金":{o:["金"],src:["本草备要", "本草纲目"],d:"重，镇心肝，定郁悸 \n辛平有毒（生金屑，服之杀人。昂按∶金性至刚重坠，与血肉之体不相宜，故服之致死 \n，非其性有毒也。人被金银灼者，并不溃烂，无毒可知矣。精金粹玉，世之宝器，岂有毒瓦斯 \n哉？）。金制木，重镇怯，故镇心肝，安魂魄（虽云重坠，亦借其宝气也。古方有红雪、紫 \n雪，皆并金银煮汁，亦假其气耳）。治惊痫风热，肝胆之病（肝经风热，则为惊痫失志，魂 \n魄飞扬。肝属木而畏金，与心为子母之脏，故其病"},
  "金丝草":{o:[],src:["本草纲目"],d:"妇人血崩：金丝草、海柏枝、砂仁、花椒、蚕退纸、旧锦灰，等分，为末，煮酒空心服。陈光述传。（《谈埜翁方》）痈疽疔肿：一切恶疮。"},
  "金星石":{o:[],src:["本草纲目"],d:"大风虫疮，有五色虫取下︰诸石丸︰用金星石、银星石、云母石、禹余粮石、滑石、阳起石、磁石、凝水石、蜜陀僧、自然铜、龙涎石等分。捣碎瓶盛，盐泥固济之。炭火十斤，过为末，醋糊丸小豆大。"},
  "金星草":{o:[],src:["本草纲目"],d:"五毒发背︰金星草和根净洗，慢火焙干。每四两入生甘草一钱，捣末，分作四服。每服用酒一升，煎二、三沸，更以温酒三、二升相和，入瓶器内封固，时时饮之。"},
  "金鱼":{o:[],src:["本草纲目"],d:"新一。久痢噤口，病势欲死︰用金丝鲤鱼一尾，重一二斤者，如常治净，用盐、酱、葱，必入胡椒末三、四钱，煮熟，置病患前嗅拱《医方摘要》）。"},
  "针砂":{o:[],src:["本草纲目"],d:"风湿脚痛︰针砂、川乌头为末，和匀炒热，绵包熨之。（《摘玄方》）风痹暖手︰针砂四两，砂三钱，黑脚白矾六钱，研末，以热醋或水拌湿，油纸裹置袋内，任意执之，冷再拌。（《圣济录》）脾劳黄病︰针砂四两（醋炒七次），干漆（烧存性）二钱，香附三钱，平胃散五钱，为末，蒸饼丸梧子大。"},
  "钓藤":{o:[],src:["本草纲目"],d:"小儿惊热︰钓藤一两，硝石半两，甘草（炙）一分。为散。每服半钱，温水服，日三服。"},
  "钟乳":{o:["钟乳"],src:["本草备要"],d:"补阳 \n甘温。阳明（胃）气分药。木石之精。强阴益阳，通百节，利九窍，补虚劳，下乳汁。 \n服之令人阳气暴充，饮食倍进，形体壮盛。然其性 悍，须命门真火衰者可偶用之。若借以 \n恣欲，多服、久服，不免淋浊痈疽之患。出洞穴中，石液凝成，下垂如冰柱。通中轻薄、如 \n鹅翎管、碎之如爪甲光明者真。炼合各如本方，蛇床为使。恶牡丹、紫石英。忌参、术、羊 \n肉、葱、蒜、胡荽。"},
  "钢铁":{o:[],src:["本草纲目"],d:"惊痫发热︰铁粉，水调少许服之。（《圣惠方》）急惊涎潮，壮热闷乱。铁粉二钱，朱砂一钱。"},
  "铁":{o:["铁"],src:["本草备要", "本草纲目"],d:"重，坠痰，镇惊 \n辛平重坠。镇心平肝，定惊疗狂，消痈解毒。诸药多忌之（李时珍曰∶补肾药尤忌之）。 \n畏磁石、皂荚（皂荚木作薪，则斧裂）。 \n时，砧上打落者名铁落（《素问》用治怒狂），如尘飞起者名铁精，器物生衣者名铁锈 \n，盐、醋浸出者名铁华（李时珍曰∶大抵借金气以平木、坠下解毒，无他义也）。 \n针砂消水肿黄胆，散瘿瘤，乌髭发（乌须方多用之）。"},
  "铁华粉":{o:[],src:["本草纲目"],d:"妇人阴挺︰铁胤粉一钱，龙脑半钱，研，水调刷产门。（危氏《得效方》）。"},
  "铁浆":{o:[],src:["本草纲目"],d:"时气生疮胸中热。铁浆饮之。（《梅师方》）一切疔疮︰铁浆，日饮一升。"},
  "铁精":{o:[],src:["本草纲目"],d:"下痢脱肛︰铁精粉敷之。（《至宝方》）女人阴脱︰铁精、羊脂，布裹炙热，熨推之。（《圣惠方》）男子阴肿︰铁精粉敷之。"},
  "铁线草":{o:[],src:["本草纲目"],d:"以乌骨鸡一斤重者，水内淹死，去毛肠，砍作肉松，入药剁匀，下麻油些少，炒黄色，随人量入酒煮熟。先以排风藤煎浓汤，沐浴头身，乃饮酒食鸡，发出粘汗即愈。如不沐浴，必发出风丹，乃愈。"},
  "铁落":{o:[],src:["本草纲目"],d:"小儿丹毒︰铁屎研末，猪脂和敷之。（《千金方》）。"},
  "铁锈":{o:[],src:["本草纲目"],d:"风瘙瘾疹︰锈铁磨水涂之。（《集简方》）汤火伤疮︰青竹烧油，同铁锈搽之。（《积德堂方》）疔肿初起︰多年土内锈钉，火醋淬，刮下锈末，不论遍次，取收之。"},
  "铁𦶟":{o:[],src:["本草纲目"],d:"项边子︰以桃核于刀上烧烟熏之。（陈氏《本草》）。"},
  "铅":{o:["铅"],src:["本草备要", "本草纲目"],d:"重，坠痰，解毒 \n甘寒属肾。禀壬癸之气，水中之金，金丹之母，八石之祖（丹灶家必用之）。安神解毒， \n坠痰杀虫，乌须（制为梳，以梳须）明目。 \n铅丹（即黄丹，用黑铅加硝、黄、盐、矾炼成）咸寒沉重，味兼盐、矾。内用坠痰去怯， \n消积杀虫，治惊疳疟痢。外用解热拔毒，去瘀长肉，熬膏必用之药（用水漂去盐硝砂石，微 \n火炒紫色，摊地上，去火毒用）。 \n铅粉主治略同（亦名胡粉锡粉。李时珍曰∶铅粉亦可代铅丹熬膏，"},
  "铅丹":{o:[],src:["本草纲目"],d:"消渴烦乱︰黄丹，新汲水服一钱，以荞麦粥压之。（《圣惠方》）吐逆不止︰碧霞丹︰用北黄丹四两，米醋半升，煎干，炭火三秤，就铫内红，冷定为末，粟米饭丸梧子大。每服七丸，醋汤下。"},
  "铅霜":{o:[],src:["本草纲目"],d:"小儿惊热，心肺积热，夜卧多惊︰铅霜、牛黄各半分，铁粉一分。研匀。每服一字，竹沥调下。"},
  "铜绿":{o:["铜绿"],src:["本草备要"],d:"\\x即铜青\\x \n宣，去风痰 \n酸平微毒。治风烂泪眼，恶疮疳疮，妇人血气心痛，吐风痰，合金疮，止血杀虫（治皆 \n肝胆之病，亦金胜木之义）。用醋制，铜刮用。"},
  "铜青":{o:[],src:["本草纲目"],d:"风痰猝中︰碧琳丹︰治痰涎潮盛，卒中不语，及一切风瘫。用生绿二两，乳细，水化去石，慢火熬干，取辰日、辰时、辰位上修合，再研入麝香一分，糯米粉糊和丸弹子大，阴干。猝中者，每丸作二服，薄荷酒研下；余风，朱砂酒化下。"},
  "银":{o:["银"],src:["本草备要", "本草纲目"],d:"功用略同。"},
  "银朱":{o:[],src:["本草纲目"],d:"小儿内钓多啼︰银朱半钱，乳香、煨蒜各一钱，为末，研丸黍米大。半岁五丸，薄荷汤下。（《心鉴》）男女阴毒︰银朱、轻粉各一钱。"},
  "锡":{o:[],src:["本草纲目"],d:"解砒霜毒︰锡器，于粗石上磨水服之。（《济急方》）杨梅毒疮︰黑铅、广锡各二钱半（结砂），蜈蚣二条，为末，纸卷作小捻，油浸一夜，点灯日照疮二次，七日见效。（《集玄方》）。"},
  "锡吝脂":{o:[],src:["本草纲目"],d:"小儿天吊多涎，搐搦不定︰锡吝脂一两（水淘黑汁令尽），水银一分（以少枣肉研，不见星），牛黄半分，麝香半分，研匀，粳米饭丸黍米大。每服三十二丸，新汲水下，名保命丹。（《普济方》）。"},
  "锻石":{o:[],src:["本草纲目"],d:"人落水死︰裹锻石纳下部中，水出尽即活。（《千金方》）痰厥气绝，心头尚温者︰千年锻石一合。水一盏，煎滚去清水，再用一盏煎极滚，澄清灌之。 ；软疖不愈︰烂船底油锻石，研末。油调敷之。（胡氏方）下体癣疮︰船灰、牛粪，烧烟熏之，一日一次，即安。"},
  "长松":{o:[],src:["本草纲目"],d:"长松酒︰滋补一切风虚，乃庐山休休子所传。长松一两五钱（状似独活而香，乃酒中圣药也）。熟地黄八钱，生地黄、黄耆（蜜炙）、陈皮各七钱，当归、浓朴、黄柏各五钱，白芍药（煨）、人参、枳壳各四钱，苍术（米泔制）、半夏（制）、天门冬、麦门冬、砂仁、黄连各三钱，木香、蜀椒、胡桃仁各二钱，小红枣肉八个，老米一撮，灯心（五寸长）一百二十根。"},
  "防葵":{o:[],src:["本草纲目"],d:"肿满洪大︰防葵研末，温酒服一刀圭，至二、三服，身及小不仁为效。（《肘后方》）癫狂邪疾︰方同上。伤寒动气，伤寒汗下后，脐左有动气︰防葵散︰用防葵一两，木香、黄芩、柴胡各半两。"},
  "阴地厥":{o:[],src:["本草纲目"],d:"男妇吐血后，胸膈虚热︰阴地厥、紫河车、贯众、甘草各半两。每服三钱，水煎服。（《圣济总录》）。"},
  "阴阳水":{o:["阴阳水"],src:["本草备要"],d:"\\x一名生熟水\\x \n宣、和阴阳 \n治霍乱吐泻有神功（阴阳不和而交争，故上吐下泻。而霍乱饮此辄定者，分其阴阳，使 \n和平也。按∶霍乱有寒、热二证，药中能治此者甚多，然未尝分别言之。仓卒患此，脉候未 \n审，慎勿轻投偏热、寒之剂。曾见有霍乱服姜汤而立毙者，唯饮阴阳水为最稳。霍乱邪在上 \n焦则吐，邪在下焦则泻，邪在中焦则吐泻兼作，此湿霍乱，症轻易治。又有心腹绞痛、不得 \n吐泻者，名干霍乱，俗名绞肠痧，其"},
  "阿魏":{o:["阿魏"],src:["本草备要"],d:"泻，消积，杀虫 \n辛平（一日温）。入脾胃。消肉积，杀细虫，去臭气（谚曰∶黄芩无假，阿魏无真。刘 \n纯曰∶阿魏无真却有真，臭而止臭是为珍），解蕈菜，自死牛马肉毒。治心腹冷痛、疟痢（疟 \n痢多由积滞而起），传尸、疳劳疰虫。出西番。木脂熬成，极臭。试取少许，安铜器一宿， \n沾处白如银，汞者真（人多以胡蒜白赝之）。用钵研细，热酒器上熏过入药。"},
  "降真香":{o:["降真香"],src:["本草备要"],d:"\\x焚之能降诸真，故名\\x \n宣，辟恶、止血、生肌 \n辛温。辟恶气怪异，疗伤折金疮，止血定痛，消肿生肌（周崇逐寇被伤，血出不止，敷 \n花芯石散，不效。军士李高，用紫金藤散敷之，血止痛定，明日结痂无瘢，曾救万人。紫金 \n藤，即降真香之最佳者也）。"},
  "雀瓮":{o:[],src:["本草纲目"],d:"新六。撮口噤风︰用棘科上雀儿饭瓮子未开口者，取内物和乳汁研，灌之。又方︰棘刚子五枚，赤足蜈蚣一条，烧存性，研匀，饭丸麻子大。"},
  "雄黄":{o:["雄黄"],src:["本草备要", "本草纲目"],d:"重，解毒，杀虫 \n辛温有毒。得正阳之气，入肝经气分。搜肝强脾，散百节大风，杀百毒，辟鬼魅。治惊 \n痫痰涎，头痛眩晕，暑疟 痢，泄泻积聚（虞雍公道中冒暑，泄痢连月，梦至仙居，延之坐 \n。壁中有词云∶暑毒在脾，湿气连脚，不泄则痢，不痢则疟。独炼雄黄，蒸饼和药，甘草作 \n汤，食之安乐。别作治疗，医家大错。如方服之遂愈）。又能化血为水，燥湿杀虫，治劳疳 \n疮疥蛇伤。赤似鸡冠，明彻不臭，重三五两者良。醋浸，"},
  "雌黄":{o:[],src:["本草纲目"],d:"反胃吐食︰雌黄一分，甘草（生）半分。为末，饭丸梧子大。以五叶草、糯米煎汤，每服四丸。"},
  "雚菌":{o:[],src:["本草纲目"],d:"旧一。蛔虫攻心如刺，吐清汁者︰萑菌一两杵末，羊肉和食之，日一顿，大效。（《外台秘要》）。"},
  "露水":{o:["露水"],src:["本草备要"],d:"润肺 \n甘平。止消渴，宜煎润肺之药。秋露造酒最清冽，百花上露，令人好颜色（霜杀物，露 \n滋物，性随时异也。露能解暑，故白露降则处暑矣。疟必由于暑，故治疟药，露一宿服）。"},
  "露蜂房":{o:["露蜂房"],src:["本草备要", "本草纲目"],d:"宣，解毒，杀虫 \n甘平有毒。治惊痫螈 ，附骨痈疽，根在脏腑（和蛇蜕、乱发、烧灰酒服。按∶附骨疽 \n不破，附骨成脓，故名。不知者，误作贼风治。附骨疽痛处发热，四体乍热乍寒，小便赤， \n大便秘而无汗，泻热发散则消。贼风痛处不热，亦不发寒热，觉身冷，欲得热熨则小宽，时 \n有汗，宜风药治之），涂瘰 成 （音漏。炙研，猪脂和涂），止风、虫牙痛（煎水含嗽。时 \n珍曰∶阳明药也，取其以毒攻毒，兼杀虫之功耳），敷"},
  "青盐":{o:["青盐"],src:["本草备要"],d:"\\x即戎盐\\x \n补肾，泻血热 \n甘咸而寒。入肾经，助水脏，平血热。治目痛赤涩，吐血溺血，齿舌出血，坚骨固齿（ \n擦牙良），明目乌须。余同食盐，出西羌。不假煎炼，方棱明莹色青者良。"},
  "青鱼":{o:[],src:["本草纲目"],d:"新八。乳蛾喉痹︰青鱼胆含咽。一方︰用汁灌鼻中，取吐。"},
  "青鱼胆":{o:["青鱼胆"],src:["本草备要"],d:"泻热，治目疾 \n苦寒色青。入肝胆。治目疾，点眼消赤肿障翳，咽津吐喉痹痰涎，涂火热疮，疗鱼骨哽 \n。腊月收，阴干。"},
  "青黛":{o:["青黛"],src:["本草备要", "本草纲目"],d:"泻肝，散郁火 \n咸寒，色青泻肝。散五脏郁火，解中、下焦蓄蕴风热（《衍义》曰∶一妇患脐、腹、二 \n阴遍生湿疮，热痒而痛，出黄汁，二便涩。用鳗鲡、松脂、黄丹之类涂之，热痛愈甚。其妇 \n嗜酒，喜食鱼、虾发风之物。乃用马齿苋四两研烂，入青黛一两和涂，热痛皆去，仍服八正 \n散而愈。此中、下焦蓄蕴风热。毒瓦斯若不出，当作肠风、内痔。妇不能禁酒物，果仍发痔） \n。 \n治伤寒发斑，吐咯血痢（阴虚火炎者忌用。合杏仁"},
  "韭":{o:["韭"],src:["本草备要", "本草纲目"],d:"补阳，散瘀 \n辛温微酸。肝之菜也，入血分而行气。归心益胃，助肾补阳（一名土钟乳，言温补也）， \n除胃热，充肺气，散瘀血，逐停痰。治吐衄损伤，一切血病（捣汁童便和服），噎膈反胃（能 \n消瘀血停痰在胃口，治反胃及胃脘痛。丹溪曰∶有食热物及郁怒，致死血留胃口作痛者，宜 \n加韭汁、桔梗入药，开提气血；有肾气上攻，致心痛者，宜韭汁和五苓散为丸，空心茴香汤 \n下。治反胃宜用牛乳加韭汁、姜汁，细细温服。盖韭汁散"},
  "预知子":{o:["预知子"],src:["本草备要", "本草纲目"],d:"补劳，泻热 \n苦寒。补五劳七伤。 \n治 癖气块，天行温疾，蛇虫咬毒。杀虫疗蛊（缀衣领中，凡遇蛊毒，则闻其声而预知 \n之，故名），利便催生。 \n藤生，子如皂角，褐色光润。出蜀中，云亦难得。"},
  "风延母":{o:[],src:["本草纲目"],d:"烂弦风眼︰千里光草，以笋壳叶包煨熟，捻汁滴入目中。（《经验良方》）。"},
  "飞廉":{o:[],src:["本草纲目"],d:"若不痛，非疳也。下部虫如马尾大，相缠出无数。十日瘥，二十日平复。"},
  "食盐":{o:["食盐"],src:["本草备要", "本草纲目"],d:"泻热，润燥，补心，通二便，宣，引吐 \n咸甘辛寒。咸润下，故通大、小便；咸走血而寒胜热，故治目赤痈肿，血热热疾；咸补 \n心，故治心虚（以水制火，取既济之义，故补心药用盐炒。一人病笑不休，用盐 赤煎沸， \n饮之而瘳。经曰∶神有余则笑不休。神，心火也。用盐，水制火也。一妇病此半年，张子和 \n亦用此法而愈）；咸入肾而主骨（故补肾药用盐汤下），故坚肌骨，治骨病齿痛（擦牙亦佳， \n清火固齿。齿缝出血，夜以盐浓"},
  "香蒲":{o:[],src:["本草纲目"],d:"妒乳乳痈︰蒲黄草根捣封之，并煎汁饮及食之。（昝殷《产宝》）热毒下痢︰蒲根二两，粟米二合，水煎服，日二次。（《圣济总录》）。"},
  "马先蒿":{o:[],src:["本草纲目"],d:"大疯癞疾，骨肉疽败，眉须堕落，身体痒痛︰以马先蒿（一名马矢蒿，一名烂石草），炒捣末。每服方寸匕，食前温酒下，一日三服，一年都瘥。（《肘后方》）。"},
  "马兜铃":{o:["马兜铃"],src:["本草备要", "本草纲目"],d:"泻肺，下气 \n体轻而虚。熟则四开象肺，故入肺。寒能清肺热。苦辛能降肺气（时珍曰∶钱乙补肺阿 \n胶散用之，非取其补肺，取其清热降气，则肺自安也。其中阿胶糯米，乃补肺之正药。昂按 \n∶清热降气，泻之即所以补之，若专一于补，适以助火而益嗽也）。 \n治痰嗽喘促，血痔 疮，大肠经热（ ，漏也，音闾，亦音漏。痔属大肠，大肠与肺为 \n表里。肺移热于大肠，故肠风痔 ，清脏热则腑热亦清矣。《千金》单服治水肿，以能泻"},
  "马兰":{o:[],src:["本草纲目"],d:"诸疟寒热︰赤脚马兰捣汁，入水少许，发日早服，或入少糖亦可。（《圣济总录》）绞肠沙痛︰马兰根叶，细嚼咽汁，立安。（《寿域神方》）打伤出血︰竹节草即马兰，同旱莲草、松香、皂子叶（即柜子叶，冬用皮）。"},
  "马勃":{o:["马勃"],src:["本草备要", "本草纲目"],d:"轻，解热，外用敷疮 \n辛平轻虚。清肺解热（东垣普济消毒饮中用之），散血止嗽。 \n治喉痹咽痛（吹喉中良，或加白矾，或硝扫喉，取吐痰愈），鼻衄失音，外用敷诸疮良。 \n生湿地朽木上。状如肺肝，紫色虚软，弹之粉出，取粉用。"},
  "马蓝":{o:[],src:["本草纲目"],d:"小儿赤痢︰捣青蓝汁二升，分四服。（《子母秘录》）小儿中蛊，下血欲死︰捣青蓝汁，频服之。（《圣惠方》）阴阳易病，伤寒初愈，交合阴阳，必病拘急，手足拳，小腹急热，头不能举，名阴阳易，当汗之。"},
  "马蔺子":{o:["马蔺子"],src:["本草备要"],d:"\\x一名蠡实\\x \n泻湿热，解毒 \n甘平。 \n治寒疝喉痹，痈肿疮疖，妇人血气烦闷，血运崩带。利大、小肠。久服令人泻。 \n丛生，叶似薤而长浓，结角子如麻大，赤色有棱。炒用。治疝用醋拌。根、叶同功。"},
  "马蕲":{o:[],src:["本草纲目"],d:"新一。慢脾惊风：马芹子、丁香、白僵蚕等分，为末。每服一钱，炙橘皮煎汤下。"},
  "马鞭草":{o:["马鞭草"],src:["本草备要", "本草纲目"],d:"泻，破血，消胀，杀虫 \n味苦微寒。破血通经，杀虫消胀。 \n治气血症瘕，痈疮阴肿（捣汁涂敷）。 \n墟陌甚多。方茎，叶似益母对生，夏、秋开细紫花，穗如车前草，类蓬蒿而细，根白而 \n小。 \n用苗、叶。"},
  "马齿苋":{o:["马齿苋"],src:["本草备要", "本草纲目"],d:"\\x一名九头狮子草\\x \n泻热，散血 \n酸寒。散血解毒，祛风杀虫。治诸淋疳痢（《海上方》∶捣汁，和鸡子白服，治赤白痢） \n，血癖恶疮（多年恶疮，敷两三遍即瘥。烧灰煎膏，涂秃疮湿癣），小儿丹毒（捣汁饮，以 \n滓涂之），利肠滑产。叶如马齿，有大、小二种，小者入药。性至难燥，去茎用（亦忌鱼、 \n鳖同食）。"},
  "驴溺":{o:["驴溺"],src:["本草备要"],d:"泻，杀虫 \n辛寒。杀虫，治反胃噎膈（须热饮之。张文仲《备急方》曰∶昔患反胃，奉敕调治，竟 \n不能疗。一卫士云∶服驴屎极验。遂服二合，只吐一半，再服二合，食粥便定。宫中患反胃 \n者五六人，同服之俱瘥）。"},
  "鬼臼":{o:[],src:["本草纲目"],d:"子死腹中，胞破不生，此方累效，救人岁万数也︰鬼臼不拘多少，黄色者，去毛为细末，不字神散。（《妇人良方》）射工中人，寒热发疮︰鬼臼叶一把，苦酒渍，捣取汁。服一升，日二次。"},
  "鬼针草":{o:[],src:["本草纲目"],d:"割甲伤肉不愈︰鬼针草苗、鼠粘子根捣汁，和腊猪脂涂。（《千金》）。"},
  "鮧鱼":{o:[],src:["本草纲目"],d:"身面白驳︰鱼（半斤）一头，去肠，以粳饭、盐、椒如常作，以荷叶作三包系之。更以荷叶重包，令臭烂。先以布拭赤，乃炙包，乘热熨，令汗出。 ；新一。骨鲠在喉︰栗子肉上皮半两（研末），乳香、鱼肝各一分，同捣，丸梧子大。以绵裹一丸，水润，外留绵线吞下，钓出。"},
  "鱁鮧":{o:[],src:["本草纲目"],d:"新一。折伤出血但不透膜者︰以海味中咸白鳔，大片色白有红丝者，成片铺在伤处，以帛缚之，即止。（《普济方》）。 ；新十一。产难︰鱼胶五寸，烧存性为末。温酒服。"},
  "鱓（善）鱼":{o:[],src:["本草纲目"],d:"新二。疮蛀烂︰用黄鳝鱼数条打死，香油抹腹，蟠疮上系定，顷则痛不可忍，然后取下看，腹有针眼皆虫也。未尽更作，后以人胫骨灰，油调搽之。"},
  "鱼子":{o:[],src:["本草纲目"],d:"新一。决明散︰治一切远年障翳，生肉，赤肿疼痛。用鱼子（活水中生下者）半两（以硫黄水温温洗净），石决明、草决明、青葙子、谷精草、枸杞子、黄连、炙甘草、枳实（麸炒）、牡蛎粉、蛇蜕（烧灰）、白芷、龙骨、黄柏各一两，白附子（炮）、白蒺藜（炒）、蝉蜕、黄芩（炒）、羌活各半两，虎睛一只（切作七片五更时茶服，午、夜再服。"},
  "鱼鲊":{o:[],src:["本草纲目"],d:"新二。白驳风︰以荷叶裹令臭，拭代指痛︰先刺去脓血，炙皮裹之。《千金方》。"},
  "鲍鱼":{o:[],src:["本草纲目"],d:"旧一。妊娠感寒腹痛︰干鱼一枚烧灰，酒服方寸匕，取汗瘥。（《子母秘录》）头。 ；新三。杂物眯目︰鲍鱼头二枚，地肤子半合，水煮烂。取汁注目中，即出。"},
  "鲚鱼":{o:[],src:["本草纲目"],d:"新一。有数孔︰用耕土烧赤，以苦酒浸之，合壁土令热，以大次。（《千金方》）。"},
  "鲛鱼":{o:[],src:["本草纲目"],d:"旧一，新一。治疰鲛鱼皮散︰颂曰︰胡洽治五尸鬼疰，百毒恶气。鲛鱼皮（炙）、朱砂、雄黄、金牙、蜀椒、细辛、鬼臼、干姜、莽草、天雄、麝香、鸡舌香、桂心各一两，贝母半两，蜈蚣、蜥蜴各（炙）二枚，为末。"},
  "鲤鱼":{o:["鲤鱼"],src:["本草备要", "本草纲目"],d:"通，行水 \n甘平。下水气，利小便。治咳逆上气，香港脚黄胆，妊娠水肿（古方治水肿，有鲤鱼汤、 \n鲤鱼粥。刘河间曰∶鲤之治水，鸭之利水，所谓因其气相感也）。 \n鲤鱼骨烧灰，疗鱼骨哽。"},
  "鲫鱼":{o:["鲫鱼"],src:["本草备要", "本草纲目"],d:"补土和胃 \n甘温。诸鱼属火，独鲫属土。土能制水，故有和胃、实肠、行水之功（作 食，治香港脚 \n及上气）。忌麦冬、芥菜、沙糖、猪肝。"},
  "鲮鲤":{o:[],src:["本草纲目"],d:"旧四，新十九。中风瘫痪，手足不举︰用穿山甲（左瘫用右甲，右痪用左甲，炮熟）、大川乌头（炮熟）、红海蛤（如棋子大者）各二两，为末。每用半两，捣葱白汁和成浓饼，径寸半，随左右贴脚心，缚定。"},
  "鳗鲡":{o:["鳗鲡"],src:["本草备要"],d:"补虚，杀虫 \n甘平。去风杀虫（按∶虫由风生，故风字从虫）。治骨蒸劳瘵，湿痹风瘙，阴户蚀痒（皆 \n有虫。张鼎云∶其骨烧烟，蚊化为水，熏竹木，辟蛀虫；置衣箱，辟诸蠹），补虚损（有病 \n瘵者，相染已死数人。乃取病者钉之棺中，弃于流水，永绝传染。渔人异之，开视，见一女 \n子尚活。取置渔舍，多食鳗鲡，病愈，遂以为妻。《圣惠方》∶鳗鲡淡炙食，治诸虫，心痛多 \n吐，冷气上攻满闷）。"},
  "鳗鲡鱼":{o:[],src:["本草纲目"],d:"旧三。诸虫心痛，多吐清水︰鳗鲡淡煮，饱食三、五度，即瘥。（《外台》）骨蒸劳瘦︰用鳗鲡二肠风下虫︰同上。 ；旧一。一切恶疮用蛇鱼骨炙为末，入诸色膏药中贴之，外以纸护之。（《经验》）血。"},
  "鳜鱼":{o:[],src:["本草纲目"],d:"旧一。骨鲠竹木刺入咽喉︰不拘大人小儿，日久或入脏腑，痛刺黄瘦甚者，服之皆出。腊月收鳜鱼胆，悬北檐下令干。"},
  "鳝鱼":{o:["鳝鱼"],src:["本草备要"],d:"宣，去风 \n甘温。补五脏，除风湿。 \n尾血，疗口眼 斜（少和麝香，左 涂右，右 涂左，正即洗去。《千金》云∶鳖血、 \n鸡冠血和伏龙肝，并治口 ），滴耳治耳痛，滴鼻治鼻衄，点目治痘后生翳（时珍曰∶鳝善 \n穿穴，与蛇同性。故能走经络，疗风邪及诸窍之病。风中血脉，用血主之，从其类也）。"},
  "鳢肠":{o:[],src:["本草纲目"],d:"金陵煎，益髭发，变白为黑︰金陵草一秤，六月以后收采，拣青嫩无泥土者。不用洗，摘去黄叶，烂捣，新布绞取汁，以纱绢滤过，入通油器钵盛之，日中煎五日。又取生姜一斤绞汁，白蜜一斤合和，日中煎，以柳本篦搅勿停手，待如稀饧，药乃成矣。"},
  "鳢鱼":{o:[],src:["本草纲目"],d:"旧三，新二。十种水汽垂死︰鳢鱼（一斤重者）煮汁，和冬瓜、葱白作羹食。（《心镜》）下一切气︰诜曰︰用大鳢一头开肚，入胡椒末半两，大蒜三两颗，缝合，同小豆一升煮熟，下萝卜三、五颗，葱一握，俱切碎，煮熟，空腹食之至饱，并饮汁。"},
  "鳢鱼胆":{o:["鳢鱼胆"],src:["本草备要"],d:"泻热 \n凡胆皆苦，惟鳢鱼胆甘（昂按∶味终带苦）。喉痹将死者，点入即瘥，病深者水调灌之。 \n俗名乌鱼，即七星鱼（首有七星，夜朝北斗，道家谓之水厌。雁为天厌，犬为地厌。《卫生 \n》歌云∶雁行有序犬有义，黑鱼拱北知臣礼，人无礼义反食之，天地鬼神皆不喜。杨拱《医 \n方摘要》云∶除夕黄昏时，取大黑鳢鱼一尾，小者二三尾，煮汤浴儿，遍身七窃俱到，能免 \n出痘。不可嫌腥，而以清水洗去也。如不信，留一手或一足不洗，"},
  "鸡":{o:["鸡"],src:["本草备要"],d:"补 \n属巽属木（故动风）。其肉甘温，补虚温中（日华曰∶黑雌鸡补产后虚劳。马益卿曰∶ \n妊妇宜食牡鸡，取阳精之全于天也。崔行功曰∶妇人产死，多是富贵扰攘，致产妇惊乱故耳。 \n屏人静产，更烂煮牡鸡汁作粳米粥与食，自然无恙。鸡汁性滑而濡，不食其肉，恐难化 \n也。 \n俗家每产后即食鸡啖卵，壮者幸无事，弱者因而致疾矣。龚云林曰∶四五年老母鸡，取 \n汤煮粥食，能固胎）。 \n鸡冠居清高之分，其血乃精华所聚，雄而"},
  "鸡冠花":{o:[],src:["本草纲目"],d:"吐血不止︰白鸡冠花，醋浸煮七次，为末。每服二钱，热酒下。（《经验方》）结阴便血︰鸡冠花、椿根白皮等分，为末，炼蜜丸梧子大。"},
  "鸡肠":{o:[],src:["本草纲目"],d:"旧四，新五。止小便利︰鸡肠草一斤，于豆豉汁中煮，和米作羹及粥，频食之。（《食医心镜》）。"},
  "鸡苏":{o:["鸡苏"],src:["本草备要"],d:"\\x一名水苏，一名龙脑薄荷\\x \n轻，宣，散热，理血 \n辛而微温。清肺下气理血，辟恶而消谷。 \n治头风目眩，肺痿血痢，吐衄崩淋，喉腥口臭，邪热诸病（《局方》有龙脑鸡苏丸）。 \n方茎中虚，似苏叶而微长，密齿面皱，气甚辛烈。"},
  "鸢尾":{o:[],src:["本草纲目"],d:"飞尸游蛊著喉中，气欲绝者︰鸢尾根削去皮，纳喉中，摩病处，令血出为佳。（陈藏器《本草拾遗》）鬼魅邪气︰四物鸢头散︰东海鸢头、黄牙（即金牙）、莨菪子、防葵各一分，为末。酒服方寸《短剧方》）。"},
  "鸭":{o:["鸭"],src:["本草备要"],d:"补阴 \n甘冷。入肺、肾血分，滋阴补虚，除蒸止嗽，利水道，治热痢。白毛乌骨者，为虚劳圣 \n药，取金肃水寒之象也（葛可久有白凤膏）。老者良。酒或童便煮。热血解金、银、丹石、 \n砒霜诸毒及中恶、溺死者。 \n卵甘咸微寒。能滋阴，除心腹膈热。盐藏，食良。"},
  "鸭跖草":{o:[],src:["本草纲目"],d:"小便不通︰竹鸡草一两，车前草一两，捣汁入蜜少许，空心服之。（《集简方》）下痢赤白︰蓝姑草（即淡竹叶菜），煎汤日服之。（《活幼全书》）喉痹肿痛︰鸭跖草汁点之。"},
  "鹤虱":{o:["鹤虱"],src:["本草备要"],d:"泻，杀虫 \n苦辛，有小毒。杀五脏虫，治蛔啮腹痛（面白唇红，时发时止者，为虫痛，肥肉汁调末 \n服）。 \n《沈存中笔记》云∶是杜牛膝子（或曰非也，别是一种）。最黏人衣。有狐气，炒热则香。"},
  "麦门冬":{o:[],src:["本草纲目"],d:"消渴饮水︰用上元板桥麦门冬（鲜肥者）二大两。宣州黄连（九节者）二大两，去两头尖三、五节，小刀子调理去皮毛了，吹去尘，更以生布摩拭秤之，捣末。以肥大苦瓠汁浸麦门冬，经宿然后去心，即于臼中捣烂，纳黄连末和捣，并手丸如梧子大。"},
  "黄明胶":{o:["黄明胶"],src:["本草备要"],d:"\\x即牛皮胶\\x \n补虚 \n甘平。功与阿胶相近，亦可代用。同葱白煮粥，通大便（李时珍曰∶真阿胶难得，牛皮 \n胶亦可权用。其性味皆平补，宜于虚热之人。张仲景治泻痢，阿胶与黄胶、黄蜡并用。陈藏 \n器曰∶诸胶皆能疗风补虚止泄，驴皮主风为最。《经验方》云∶痈疽初起，酒顿黄明胶四两 \n，服尽，毒不内攻。《唐氏方》∶加穿山甲四片，烧存性用。昂谓∶此方若验，胜于服蜡矾 \n丸也）。"},
  "黄环":{o:[],src:["本草纲目"],d:"野狼跋子。"},
  "黄矾":{o:[],src:["本草纲目"],d:"耳出汁︰黄矾二两烧枯，绵裹二钱塞之。（《圣惠方》）妇人颊疮，每年频发︰水银一两半，以猪脂揉擦，令消尽。入黄矾石末二两，胡粉一两，再加猪脂和令如泥。"},
  "黄荠水":{o:["黄荠水"],src:["本草备要"],d:"宣，涌，吐 \n酸咸，吐痰饮、宿食。酸苦涌泄为阴也。"},
  "黄药子":{o:[],src:["本草纲目"],d:"吐血不止︰药子一两，水煎服。（《圣惠方》）咯血吐血︰《百一选方》︰用蒲黄、黄药子等分，为末，掌中舐之。王衮《博济方》︰用黄鼻衄不止︰黄药子为末。"},
  "黄蜀葵":{o:[],src:["本草纲目"],d:"沙石淋痛︰黄蜀葵花一两，炒为末，每米饮服一钱，名独圣散。（《普济方》）难产催生︰如圣散︰治胎脏干涩难产，剧者并进三服，良久腹中气宽，胎滑即下也。用黄葵花焙研末，熟汤调服二钱。 ；临产催生︰宗奭曰︰临产时以四十九粒研烂，温水服之，良久即产。《经验后方》︰用子焙研三钱，井华水服。无子用根，煎汁服。"},
  "黄颔蛇":{o:[],src:["本草纲目"],d:"新三。犬啮伤自死蛇一枚，烧焦为末，纳入疮孔中。（《千金方》）五月五日自死赤蛇，烧灰。 ；新二。发背肿毒︰蛇头烧灰，醋和敷之，日三易。（《千金》）蛤蟆疮︰五月五日蛇头，及野猪脂同水衣封之，佳。 ；新一。一切冷漏︰自死蛇，取骨为末封之。大痛，以杏仁膏摩之，即止。 ；新三。噎膈︰用蛇含蛤蟆，泥包烧存性，研末。米饮服。"},
  "黄颡鱼":{o:[],src:["本草纲目"],d:"新三。水汽浮肿︰用黄颡三尾，绿豆一合，大蒜三瓣，水煮烂，去鱼食豆，以汁调商陆末一钱服。其水化为清气而消。 ；新一。生津丸︰治消渴饮水无度。以黄颡鱼涎和青蛤粉、滑石末等分，丸梧子大。"},
  "黑大豆":{o:["黑大豆"],src:["本草备要"],d:"补肾，解毒 \n甘寒色黑。属水似肾，肾之谷也（豆有五色，各入五脏），故能补肾镇心（肾水足，则 \n心火宁），明目（肾水足则目明），利水下气（古方治水肿，每单用，或加他药），散热祛风 \n（炒热酒沃，饮其汁，治产后中风危笃及妊娠腰痛，兼能发表。《千金》云∶一以去风，一 \n以消血结），活血（《产书》云∶熬令烟绝，酒淋服，下产后余血）解毒（苏颂曰∶古称大豆 \n解百药毒，试之不然，又加甘草，其验乃奇），消肿止痛"},
  "鼍龙":{o:[],src:["本草纲目"],d:"旧一。肠风痔疾︰颂曰︰用皮及骨烧灰，米饮空心服二钱。甚者，入红鸡冠花、白矾为末和之。"},
  "鼠妇":{o:[],src:["本草纲目"],d:"旧一，新八。产妇尿秘︰鼠妇七枚熬，研末，酒服。（《千金翼》）撮口脐风︰《圣惠》︰用鼠妇虫杵，绞汁少许，灌之。"},
  "鼠尾草":{o:[],src:["本草纲目"],d:"大腹水蛊︰方见马鞭草下。久痢休息，时止时作︰鼠尾草花捣末。饮服一钱。"},
  "鼠矢":{o:["鼠矢"],src:["本草备要"],d:"宣，调阴阳 \n甘而微寒。治伤寒劳复发热，男子阴易腹痛（妇人伤寒初愈，即与交接，毒中男人，名 \n阴易。若女人与伤寒男子交者，名阳易。《活人》有鼠矢汤）。两头尖者，为雄鼠屎。 \n鼠胆明目。汁滴耳中，治二十年老聋（陶弘景曰∶鼠胆随死辄消，不易得也）。 \n鼠肉治儿疳鼠 （河间曰∶鼠性善穿，而治疮 ，因其性为用也）。"},
  "龙":{o:[],src:["本草纲目"],d:"健忘：久服聪明，益智慧。用白龙骨、虎骨、远志等分，为末。食后酒服方寸匕，日三。"},
  "龙胆草":{o:["龙胆草"],src:["本草备要"],d:"泻肝胆火，下焦湿热 \n大苦大寒，沉阴下行。益肝胆而泻火（相火寄于肝胆，有泻无补，泻其邪热，即所以补 \n火也），兼入膀胱、肾经。除下焦之湿热，与防己同功。酒浸亦能外行、上行。 \n治骨间寒热（肾主骨），惊痫邪气（肝经风火），时气温热，热痢疸黄、寒湿香港脚（足伤 \n湿热，则成香港脚。肿而痛者，为湿香港脚，宜清热利湿搜风。又有挛缩枯细，痛而不肿者，名 \n干香港脚，宜养血润燥），咽喉风热，赤睛 肉（泻肝胆火"},
  "龙舌草":{o:[],src:["本草纲目"],d:"乳痈肿毒︰龙舌草、忍冬藤，研烂，蜜和傅之。（《多能鄙事》）。"},
  "龙葵":{o:[],src:["本草纲目"],d:"去热少睡︰龙葵菜同米，煮作羹粥食之。（《食医心镜》）茎、叶、根。 ；通利小便︰方见上。从高坠下欲死者︰取老鸦眼睛草茎叶捣汁服，以渣敷患处。（《唐瑶经验方》）火焰丹肿︰老鸦眼睛草叶，入醋细研敷之，能消赤肿。"},
  "龙齿":{o:["龙齿"],src:["本草备要"],d:"涩，镇惊 \n涩凉。镇心安魂。治大人痉癫狂热，小儿五惊十二痫（《卫生宝鉴》曰∶龙齿安魂，虎 \n睛定魄。龙属木，主肝，肝藏魂。虎属金，主肺，肺藏魄也）。治同龙骨。"},
  "𦯶麻":{o:[],src:["本草纲目"],d:"一切眼疾︰麻子一升。为末。以猪肝批片，蘸末炙服一字，陈米饮下，磨去壳，马尾筛取黄肉去焦壳，每十两可得四两药慢炙熟，为末，醋和丸梧子大。"},
  "𫚥":{o:[],src:["本草纲目"],d:"新五。鳖症疼痛︰《类编》云︰景陈弟长子拱病鳖症，隐隐见皮内，痛不可忍。外医洪氏曰︰可以鲜虾作羹食之。"}
};